import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface EmployeeSalaryData {
  id: string;
  name: string;
  email: string;
  designation: string;
  month: string;
  year: number;
  basic: number;
  hra: number;
  conveyance: number;
  specialAllowance: number;
  pf: number;
  professionalTax: number;
  incomeTax: number;
  workingDays: number;
  daysPresent: number;
  grossSalary: number;
  netSalary: number;
}

export enum TabType {
  HOME = 'home',
  PAYSLIPS = 'payslips',
  INSIGHTS = 'insights'
}

import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { EmployeeSalaryData } from '../types';

export const generateSinglePayslip = (employee: EmployeeSalaryData, save: boolean = true) => {
  const doc = new jsPDF();

  // Header
  doc.setFontSize(22);
  doc.setTextColor(40);
  doc.text('PayslipFlow Solutions', 105, 20, { align: 'center' });

  doc.setFontSize(10);
  doc.text('123 Corporate Plaza, Business District, City - 560001', 105, 28, { align: 'center' });
  doc.line(20, 35, 190, 35);

  // Employee Info
  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.text(`Payslip for ${employee.month} ${employee.year}`, 20, 45);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.text(`Employee ID: ${employee.id}`, 20, 55);
  doc.text(`Name: ${employee.name}`, 20, 60);
  doc.text(`Designation: ${employee.designation}`, 20, 65);
  doc.text(`Working Days: ${employee.workingDays}`, 140, 55);
  doc.text(`Days Present: ${employee.daysPresent}`, 140, 60);

  // Earnings Table
  (doc as any).autoTable({
    startY: 75,
    head: [['Earnings', 'Amount (INR)']],
    body: [
      ['Basic Salary', employee.basic.toFixed(2)],
      ['HRA', employee.hra.toFixed(2)],
      ['Conveyance', employee.conveyance.toFixed(2)],
      ['Special Allowance', employee.specialAllowance.toFixed(2)],
      [{ content: 'Total Gross Earnings', styles: { fontStyle: 'bold' } }, { content: employee.grossSalary.toFixed(2), styles: { fontStyle: 'bold' } }],
    ],
    theme: 'striped',
    headStyles: { fillColor: [59, 130, 246] },
  });

  // Deductions Table
  (doc as any).autoTable({
    startY: (doc as any).lastAutoTable.finalY + 10,
    head: [['Deductions', 'Amount (INR)']],
    body: [
      ['Provident Fund (PF)', employee.pf.toFixed(2)],
      ['Professional Tax', employee.professionalTax.toFixed(2)],
      ['Income Tax (TDS)', employee.incomeTax.toFixed(2)],
      [{ content: 'Total Deductions', styles: { fontStyle: 'bold' } }, { content: (employee.pf + employee.professionalTax + employee.incomeTax).toFixed(2), styles: { fontStyle: 'bold' } }],
    ],
    theme: 'striped',
    headStyles: { fillColor: [239, 68, 68] },
  });

  // Net Pay
  const finalY = (doc as any).lastAutoTable.finalY + 15;
  doc.setFillColor(243, 244, 246);
  doc.rect(20, finalY - 5, 170, 15, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.text(`NET TAKE HOME: INR ${employee.netSalary.toFixed(2)}`, 105, finalY + 5, { align: 'center' });

  // Footer
  doc.setFontSize(8);
  doc.setFont('helvetica', 'italic');
  doc.text('This is a computer-generated payslip and does not require a signature.', 105, 280, { align: 'center' });

  if (save) {
    doc.save(`Payslip_${employee.name}_${employee.month}_${employee.year}.pdf`);
  }
  return doc;
};

export const generateBulkPayslips = (employees: EmployeeSalaryData[]) => {
  const finalDoc = new jsPDF();

  employees.forEach((employee, index) => {
    if (index > 0) finalDoc.addPage();

    // Add same content as single generator to finalDoc
    // For simplicity in this demo, we can just call the drawing logic directly
    // but a cleaner way is to refactor drawing logic into a shared function.
    // For now, we'll just show the concept.

    const tempDoc = generateSinglePayslip(employee, false);
    // Note: merging pages in jsPDF is complex, usually we draw everything on one instance
    // Re-drawing logic here:
    drawOnDoc(finalDoc, employee);
  });

  finalDoc.save(`Bulk_Payslips_${Date.now()}.pdf`);
};

