import React, { useState, useCallback } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Upload, 
  Download, 
  Users, 
  Wallet,
  Calendar,
  AlertCircle
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType } from './types';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        try {
          const parsedData = results.data.map((row: any) => {
            const basic = parseFloat(row.basic) || 0;
            const hra = parseFloat(row.hra) || 0;
            const conveyance = parseFloat(row.conveyance) || 0;
            const specialAllowance = parseFloat(row.specialAllowance) || 0;
            const pf = parseFloat(row.pf) || 0;
            const professionalTax = parseFloat(row.professionalTax) || 0;
            const incomeTax = parseFloat(row.incomeTax) || 0;
            const gross = basic + hra + conveyance + specialAllowance;
            const net = gross - (pf + professionalTax + incomeTax);

            return {
              id: row.id || Math.random().toString(36).substr(2, 9),
              name: row.name || 'Unknown',
              email: row.email || '',
              designation: row.designation || 'Staff',
              month: row.month || 'Current',
              year: parseInt(row.year) || new Date().getFullYear(),
              basic,
              hra,
              conveyance,
              specialAllowance,
              pf,
              professionalTax,
              incomeTax,
              workingDays: parseInt(row.workingDays) || 30,
              daysPresent: parseInt(row.daysPresent) || 30,
              grossSalary: gross,
              netSalary: net,
            } as EmployeeSalaryData;
          });
          setEmployees(parsedData);
          setUploadError(null);
        } catch (err) {
          setUploadError("Error parsing CSV data. Please check formatting.");
        }
      },
      error: (err) => {
        setUploadError("Failed to read the file.");
      }
    });
  };

  const clearData = () => {
    setEmployees([]);
    setUploadError(null);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      {/* Sidebar */}
      <nav className="w-full md:w-64 bg-white border-b md:border-r border-gray-200 p-4 flex flex-col gap-2">
        <div className="flex items-center gap-2 mb-8 px-2">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold text-xl">
            P
          </div>
          <h1 className="text-xl font-bold text-gray-800">PayslipFlow</h1>
        </div>

        <button
          onClick={() => setActiveTab(TabType.HOME)}
          className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
            activeTab === TabType.HOME 
              ? 'bg-blue-50 text-blue-600 font-semibold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-100'
          }`}
        >
          <LayoutDashboard size={20} />
          <span>Home</span>
        </button>

        <button
          onClick={() => setActiveTab(TabType.PAYSLIPS)}
          className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
            activeTab === TabType.PAYSLIPS 
              ? 'bg-blue-50 text-blue-600 font-semibold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-100'
          }`}
        >
          <FileText size={20} />
          <span>Payslips</span>
        </button>

        <button
          onClick={() => setActiveTab(TabType.INSIGHTS)}
          className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
            activeTab === TabType.INSIGHTS 
              ? 'bg-blue-50 text-blue-600 font-semibold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-100'
          }`}
        >
          <PieChart size={20} />
          <span>Insights</span>
        </button>

        <div className="mt-auto pt-8 border-t border-gray-100 px-2">
          <p className="text-xs text-gray-400 uppercase tracking-widest font-bold mb-4">Admin Controls</p>
          <label className="flex items-center gap-3 px-4 py-3 rounded-xl cursor-pointer text-blue-600 hover:bg-blue-50 transition-all border-2 border-dashed border-blue-200">
            <Upload size={20} />
            <span className="font-medium text-sm">Upload CSV</span>
            <input type="file" accept=".csv" onChange={handleFileUpload} className="hidden" />
          </label>
          <button 
            onClick={clearData}
            className="w-full flex items-center gap-3 px-4 py-3 mt-2 rounded-xl text-red-500 hover:bg-red-50 transition-all text-sm font-medium"
          >
            Clear Records
          </button>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 p-6 md:p-10 overflow-auto">
        {uploadError && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-xl flex items-center gap-3 text-red-700">
            <AlertCircle size={20} />
            <p className="text-sm font-medium">{uploadError}</p>
          </div>
        )}

        {employees.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-4 max-w-md mx-auto">
            <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 mb-2">
              <Upload size={40} />
            </div>
            <h2 className="text-2xl font-bold text-gray-800">Welcome to PayslipFlow</h2>
            <p className="text-gray-500">
              Get started by uploading your employee salary CSV. Your dashboard will automatically populate with data, payslips, and financial insights.
            </p>
            <div className="bg-white p-4 border rounded-lg text-left text-xs text-gray-400 font-mono w-full">
              <p className="font-bold mb-2">Required Columns:</p>
              id, name, designation, month, year, basic, hra, conveyance, specialAllowance, pf, professionalTax, incomeTax, workingDays, daysPresent
            </div>
          </div>
        ) : (
          <>
            {activeTab === TabType.HOME && <HomeTab employees={employees} />}
            {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} />}
            {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
          </>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { EmployeeSalaryData } from '../types';
import { Download, FileDown, Search, CheckCircle2 } from 'lucide-react';
import { generateSinglePayslip, generateBulkPayslips } from '../utils/pdfGenerator';

interface PayslipsTabProps {
  employees: EmployeeSalaryData[];
}

const PayslipsTab: React.FC<PayslipsTabProps> = ({ employees }) => {
  const [searchTerm, setSearchTerm] = React.useState('');

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    emp.id.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Generate Payslips</h2>
          <p className="text-gray-500">Download individual or bulk salary statements</p>
        </div>
        <button 
          onClick={() => generateBulkPayslips(employees)}
          className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-200"
        >
          <FileDown size={20} />
          <span>Download All Combined (PDF)</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
        <input 
          type="text" 
          placeholder="Search by name or employee ID..."
          className="w-full pl-12 pr-4 py-4 bg-white border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {filteredEmployees.map((emp) => (
          <div key={emp.id} className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-all flex flex-col group">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center font-bold text-lg">
                {emp.name[0]}
              </div>
              <div className="text-right">
                <span className="text-[10px] font-bold text-blue-500 uppercase tracking-wider bg-blue-50 px-2 py-1 rounded">
                  Ready
                </span>
              </div>
            </div>

            <h4 className="font-bold text-gray-800 truncate">{emp.name}</h4>
            <p className="text-xs text-gray-400 mb-4">{emp.designation}</p>

            <div className="space-y-2 mb-6">
              <div className="flex justify-between text-xs text-gray-500">
                <span>Month</span>
                <span className="font-medium text-gray-700">{emp.month} {emp.year}</span>
              </div>
              <div className="flex justify-between text-xs text-gray-500">
                <span>Net Pay</span>
                <span className="font-bold text-blue-600">₹{emp.netSalary.toLocaleString()}</span>
              </div>
            </div>

            <button 
              onClick={() => generateSinglePayslip(emp)}
              className="mt-auto w-full flex items-center justify-center gap-2 py-3 bg-gray-50 text-gray-600 font-bold rounded-xl hover:bg-blue-600 hover:text-white transition-all group-hover:shadow-lg"
            >
              <Download size={18} />
              <span>Download PDF</span>
            </button>
          </div>
        ))}

        {filteredEmployees.length === 0 && (
          <div className="col-span-full py-20 text-center text-gray-400 italic">
            No employees found matching your search.
          </div>
        )}
      </div>
    </div>
  );
};

export default PayslipsTab;

import React from 'react';
import { EmployeeSalaryData } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { TrendingUp, CreditCard, Activity, Calendar, Download } from 'lucide-react';

interface InsightsTabProps {
  employees: EmployeeSalaryData[];
}

const InsightsTab: React.FC<InsightsTabProps> = ({ employees }) => {
  const totalBudget = employees.reduce((sum, emp) => sum + emp.grossSalary, 0);
  const totalNet = employees.reduce((sum, emp) => sum + emp.netSalary, 0);
  const totalPF = employees.reduce((sum, emp) => sum + emp.pf, 0);
  const totalTaxes = employees.reduce((sum, emp) => sum + (emp.incomeTax + emp.professionalTax), 0);
  const avgWorkingDays = employees.reduce((sum, emp) => sum + emp.workingDays, 0) / employees.length;
  const avgPresence = employees.reduce((sum, emp) => sum + emp.daysPresent, 0) / employees.length;

  const barData = employees.slice(0, 10).map(emp => ({
    name: emp.name.split(' ')[0],
    net: emp.netSalary,
    gross: emp.grossSalary
  }));

  const pieData = [
    { name: 'Take Home (Net)', value: totalNet, color: '#3b82f6' },
    { name: 'PF Contributions', value: totalPF, color: '#10b981' },
    { name: 'Taxes (TDS+PT)', value: totalTaxes, color: '#ef4444' },
    { name: 'Other Allowances', value: totalBudget - (totalNet + totalPF + totalTaxes), color: '#8b5cf6' }
  ];

  const handleExportInsights = () => {
    const csvContent = "data:text/csv;charset=utf-8," 
      + "Metric,Value\n"
      + `Total Budget (Gross),${totalBudget}\n`
      + `Total PF,${totalPF}\n`
      + `Total Taxes,${totalTaxes}\n`
      + `Avg Attendance,${(avgPresence / avgWorkingDays * 100).toFixed(2)}%`;

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "financial_insights.csv");
    document.body.appendChild(link);
    link.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in zoom-in-95 duration-500">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-800">Financial Insights</h2>
        <button 
          onClick={handleExportInsights}
          className="flex items-center gap-2 px-4 py-2 border-2 border-gray-200 rounded-xl text-gray-600 font-bold hover:bg-gray-50 transition-all text-sm"
        >
          <Download size={18} />
          Export Insights CSV
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <TrendingUp className="text-blue-600 mb-2" size={24} />
          <p className="text-gray-500 text-xs font-bold uppercase">Total Budget</p>
          <h4 className="text-xl font-bold text-gray-800">₹{totalBudget.toLocaleString()}</h4>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <CreditCard className="text-green-600 mb-2" size={24} />
          <p className="text-gray-500 text-xs font-bold uppercase">Total PF</p>
          <h4 className="text-xl font-bold text-gray-800">₹{totalPF.toLocaleString()}</h4>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <Calendar className="text-orange-600 mb-2" size={24} />
          <p className="text-gray-500 text-xs font-bold uppercase">Avg Presence</p>
          <h4 className="text-xl font-bold text-gray-800">{avgPresence.toFixed(1)} / {avgWorkingDays.toFixed(0)} Days</h4>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <Activity className="text-red-600 mb-2" size={24} />
          <p className="text-gray-500 text-xs font-bold uppercase">Tax Deductions</p>
          <h4 className="text-xl font-bold text-gray-800">₹{totalTaxes.toLocaleString()}</h4>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Salary Distribution (Top 10)</h3>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#9ca3af' }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#9ca3af' }} />
                <Tooltip 
                  cursor={{ fill: '#f9fafb' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="gross" fill="#93c5fd" radius={[4, 4, 0, 0]} name="Gross Salary" />
                <Bar dataKey="net" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Net Salary" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Budget Breakdown</h3>
          <div className="h-[350px] flex flex-col md:flex-row items-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={120}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex flex-col gap-3 justify-center w-full md:w-64">
              {pieData.map((item) => (
                <div key={item.name} className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }}></div>
                  <div className="flex-1">
                    <p className="text-xs font-bold text-gray-800">{item.name}</p>
                    <p className="text-[10px] text-gray-400">₹{item.value.toLocaleString()}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

