import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { EmployeeSalaryData } from '../types';

const drawPayslip = (doc: jsPDF, employee: EmployeeSalaryData) => {
  // Header
  doc.setFontSize(20);
  doc.setTextColor(40);
  doc.text('PayslipFlow Solutions', 105, 15, { align: 'center' });

  doc.setFontSize(9);
  doc.text('Monthly Salary Statement', 105, 22, { align: 'center' });
  doc.line(15, 28, 195, 28);

  // Employee Header Info
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text(`Employee Details`, 15, 35);
  doc.setFont('helvetica', 'normal');

  const leftCol = 15;
  const rightCol = 110;

  doc.text(`Name: ${employee.name}`, leftCol, 42);
  doc.text(`Employee ID: ${employee.id}`, leftCol, 47);
  doc.text(`ESI No: ${employee.esiNo}`, leftCol, 52);
  doc.text(`UAN No: ${employee.uanNo}`, leftCol, 57);

  doc.text(`Month/Year: ${employee.month} ${employee.year}`, rightCol, 42);
  doc.text(`Fixed Gross: Rs. ${employee.fixedGross.toFixed(2)}`, rightCol, 47);
  doc.text(`Days (Total/Worked): ${employee.totalDays} / ${employee.workedDays}`, rightCol, 52);
  doc.text(`OT Hours: ${employee.otHours}`, rightCol, 57);

  // Earnings Table
  (doc as any).autoTable({
    startY: 65,
    margin: { left: 15, right: 15 },
    head: [['Earnings', 'Amount (INR)']],
    body: [
      ['Basic & DA', employee.basicDA.toFixed(2)],
      ['Bonus', employee.bonus.toFixed(2)],
      ['OT Amount', employee.otAmount.toFixed(2)],
      [{ content: 'Total Gross Earnings', styles: { fontStyle: 'bold' } }, { content: employee.grossEarnings.toFixed(2), styles: { fontStyle: 'bold' } }],
    ],
    theme: 'grid',
    headStyles: { fillColor: [59, 130, 246] },
    styles: { fontSize: 9 }
  });

  // Deductions Table
  (doc as any).autoTable({
    startY: (doc as any).lastAutoTable.finalY + 5,
    margin: { left: 15, right: 15 },
    head: [['Deductions', 'Amount (INR)']],
    body: [
      ['ESI @ 0.75%', employee.esiDeduction.toFixed(2)],
      ['PF @ 12%', employee.pfDeduction.toFixed(2)],
      ['Professional Tax (PT)', employee.ptDeduction.toFixed(2)],
      ['LWF', employee.lwfDeduction.toFixed(2)],
      ['Canteen', employee.canteenDeduction.toFixed(2)],
      [{ content: 'Total Deductions', styles: { fontStyle: 'bold' } }, { content: employee.totalDeductions.toFixed(2), styles: { fontStyle: 'bold' } }],
    ],
    theme: 'grid',
    headStyles: { fillColor: [239, 68, 68] },
    styles: { fontSize: 9 }
  });

  // Net Pay
  const finalY = (doc as any).lastAutoTable.finalY + 12;
  doc.setFillColor(243, 244, 246);
  doc.rect(15, finalY - 6, 180, 12, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(12);
  doc.text(`NET PAYABLE: INR ${employee.netSalary.toFixed(2)}`, 105, finalY + 2, { align: 'center' });

  doc.setFontSize(8);
  doc.setFont('helvetica', 'italic');
  doc.text('This is a computer generated document.', 105, 285, { align: 'center' });
};

export const generateSinglePayslip = (employee: EmployeeSalaryData, save: boolean = true) => {
  const doc = new jsPDF();
  drawPayslip(doc, employee);
  if (save) {
    doc.save(`Payslip_${employee.id}_${employee.month}.pdf`);
  }
  return doc;
};

export const generateBulkPayslips = (employees: EmployeeSalaryData[]) => {
  const doc = new jsPDF();
  employees.forEach((emp, i) => {
    if (i > 0) doc.addPage();
    drawPayslip(doc, emp);
  });
  doc.save(`Bulk_Payslips_${Date.now()}.pdf`);
};

import React, { useState, useCallback, useRef } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Upload, 
  Settings,
  AlertCircle,
  Check,
  X
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping } from './types';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);

  // Mapping State
  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          // Initial Auto-mapping
          const initialMapping: Partial<ColumnMapping> = {};
          const fieldToCsvMap: Record<string, string[]> = {
            id: ['employee', 'id', 'emp id', 'emp code'],
            name: ['employee name', 'name', 'full name'],
            esiNo: ['esi no', 'esi'],
            uanNo: ['uan no', 'uan'],
            totalDays: ['no of days', 'total days'],
            workedDays: ['worked days', 'days present'],
            otHours: ['ot hours', 'overtime hours'],
            fixedGross: ['fixed gross', 'gross salary'],
            basicDA: ['basic & da', 'basic'],
            bonus: ['bonus'],
            otAmount: ['ot amount', 'overtime amount'],
            esiDeduction: ['esi @0.75%', 'esi deduction'],
            pfDeduction: ['pf @ 12%', 'pf deduction', 'provident fund'],
            ptDeduction: ['pt', 'professional tax'],
            lwfDeduction: ['lwf'],
            canteenDeduction: ['canteen']
          };

          Object.keys(fieldToCsvMap).forEach(field => {
            const match = headers.find(h => 
              fieldToCsvMap[field].includes(h.toLowerCase().trim())
            );
            if (match) initialMapping[field as keyof ColumnMapping] = match;
          });

          setMapping(initialMapping);
          setShowMapping(true);
        }
      }
    });
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => parseFloat(row[mapping[field]!] || '0') || 0;

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const grossEarnings = basicDA + bonus + otAmount;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const canteen = getVal('canteenDeduction');
        const totalDeductions = esi + pf + pt + lwf + canteen;

        return {
          id: row[mapping.id!] || 'N/A',
          name: row[mapping.name!] || 'Unknown',
          esiNo: row[mapping.esiNo!] || 'N/A',
          uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'),
          workedDays: getVal('workedDays'),
          otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'),
          basicDA,
          bonus,
          otAmount,
          esiDeduction: esi,
          pfDeduction: pf,
          ptDeduction: pt,
          lwfDeduction: lwf,
          canteenDeduction: canteen,
          grossEarnings,
          totalDeductions,
          netSalary: grossEarnings - totalDeductions,
          month: monthNames[now.getMonth()],
          year: now.getFullYear()
        } as EmployeeSalaryData;
      });

      setEmployees(parsedData);
      setShowMapping(false);
      setUploadError(null);
    } catch (err) {
      setUploadError("Processing failed. Please check your mapping.");
    }
  };

  const clearData = () => {
    setEmployees([]);
    setUploadError(null);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      {/* Sidebar */}
      <nav className="w-full md:w-72 bg-white border-r border-gray-100 p-6 flex flex-col gap-2">
        <div className="flex items-center gap-3 mb-10 px-2">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white font-bold text-2xl shadow-xl shadow-indigo-100">
            P
          </div>
          <div>
            <h1 className="text-xl font-extrabold text-gray-900 tracking-tight">PayslipFlow</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest">Admin Portal</p>
          </div>
        </div>

        <button
          onClick={() => setActiveTab(TabType.HOME)}
          className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${
            activeTab === TabType.HOME 
              ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-50'
          }`}
        >
          <LayoutDashboard size={22} />
          <span>Dashboard</span>
        </button>

        <button
          onClick={() => setActiveTab(TabType.PAYSLIPS)}
          className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${
            activeTab === TabType.PAYSLIPS 
              ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-50'
          }`}
        >
          <FileText size={22} />
          <span>Payslips</span>
        </button>

        <button
          onClick={() => setActiveTab(TabType.INSIGHTS)}
          className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${
            activeTab === TabType.INSIGHTS 
              ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' 
              : 'text-gray-500 hover:bg-gray-50'
          }`}
        >
          <PieChart size={22} />
          <span>Insights</span>
        </button>

        <div className="mt-auto pt-8 border-t border-gray-50">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-full flex items-center justify-center gap-3 px-4 py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98]"
          >
            <Upload size={20} />
            <span>Upload New Data</span>
          </button>
          <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />

          <button 
            onClick={clearData}
            className="w-full mt-3 flex items-center justify-center gap-2 py-3 text-sm font-semibold text-red-500 hover:bg-red-50 rounded-xl transition-colors"
          >
            Reset Application
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 p-8 overflow-auto">
        {uploadError && (
          <div className="mb-8 p-4 bg-red-50 border border-red-200 rounded-2xl flex items-center gap-4 text-red-700">
            <div className="p-2 bg-red-100 rounded-full"><AlertCircle size={20} /></div>
            <p className="text-sm font-bold">{uploadError}</p>
          </div>
        )}

        {employees.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center max-w-lg mx-auto text-center py-20">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-600 mb-8 animate-pulse">
              <Upload size={48} />
            </div>
            <h2 className="text-3xl font-extrabold text-gray-900 mb-4 tracking-tight">Generate Monthly Payslips</h2>
            <p className="text-gray-500 mb-8 leading-relaxed">
              Upload your employee attendance and salary CSV. Our smart mapping tool will handle your custom column names automatically.
            </p>
            <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm w-full">
              <div className="flex items-center gap-3 text-left mb-4">
                <Check className="text-green-500" size={18} />
                <span className="text-sm font-semibold text-gray-700">Custom Column Mapping</span>
              </div>
              <div className="flex items-center gap-3 text-left mb-4">
                <Check className="text-green-500" size={18} />
                <span className="text-sm font-semibold text-gray-700">Detailed ESI/PF Calculations</span>
              </div>
              <div className="flex items-center gap-3 text-left">
                <Check className="text-green-500" size={18} />
                <span className="text-sm font-semibold text-gray-700">Bulk PDF Generation</span>
              </div>
            </div>
          </div>
        ) : (
          <div className="animate-in fade-in duration-700">
            {activeTab === TabType.HOME && <HomeTab employees={employees} />}
            {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} />}
            {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
          </div>
        )}
      </main>

      {/* Mapping Modal */}
      {showMapping && (
        <div className="fixed inset-0 z-50 bg-gray-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-[32px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h3 className="text-2xl font-extrabold text-gray-900">Map Your Columns</h3>
                <p className="text-gray-500 text-sm mt-1">Connect your file headers to system fields</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-gray-100 rounded-full text-gray-400">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto space-y-6">
              <div className="grid grid-cols-2 gap-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest px-1">
                <span>System Field</span>
                <span>Your Excel Header</span>
              </div>

              {[
                { key: 'id', label: 'Employee ID' },
                { key: 'name', label: 'Employee Name' },
                { key: 'esiNo', label: 'ESI Number' },
                { key: 'uanNo', label: 'UAN Number' },
                { key: 'totalDays', label: 'Total Days in Month' },
                { key: 'workedDays', label: 'Worked Days' },
                { key: 'fixedGross', label: 'Fixed Gross' },
                { key: 'basicDA', label: 'Basic & DA' },
                { key: 'bonus', label: 'Bonus' },
                { key: 'otAmount', label: 'OT Amount' },
                { key: 'esiDeduction', label: 'ESI Deduction' },
                { key: 'pfDeduction', label: 'PF Deduction' },
                { key: 'ptDeduction', label: 'Professional Tax' },
                { key: 'lwfDeduction', label: 'LWF' },
                { key: 'canteenDeduction', label: 'Canteen' }
              ].map((field) => (
                <div key={field.key} className="flex items-center gap-4 bg-gray-50 p-4 rounded-2xl border border-gray-100">
                  <div className="flex-1">
                    <span className="font-bold text-gray-800 text-sm">{field.label}</span>
                  </div>
                  <div className="flex-1">
                    <select 
                      value={mapping[field.key as keyof ColumnMapping] || ''}
                      onChange={(e) => setMapping({ ...mapping, [field.key]: e.target.value })}
                      className="w-full bg-white border border-gray-200 rounded-xl px-3 py-2 text-sm font-medium focus:ring-2 focus:ring-indigo-500 outline-none"
                    >
                      <option value="">-- Select Column --</option>
                      {csvHeaders.map(h => (
                        <option key={h} value={h}>{h}</option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>

            <div className="p-8 bg-gray-50 border-t border-gray-100 flex gap-4">
              <button 
                onClick={() => setShowMapping(false)}
                className="flex-1 py-4 font-bold text-gray-500 bg-white border border-gray-200 rounded-2xl hover:bg-gray-50 transition-all"
              >
                Cancel
              </button>
              <button 
                onClick={processDataWithMapping}
                className="flex-[2] py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"
              >
                Finish & Import Data
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

