    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          // Initial Auto-mapping
          const initialMapping: Partial<ColumnMapping> = {};
          const fieldToCsvMap: Record<string, string[]> = {
            id: ['employee', 'id', 'employee id', 'emp code'],
            name: ['employee name', 'name'],
            esiNo: ['esi no', 'esi'],
            uanNo: ['uan no', 'uan'],
            totalDays: ['no of days', 'total days'],
            workedDays: ['worked days', 'days present'],
            otHours: ['ot hours'],
            fixedGross: ['fixed gross'],
            basicDA: ['basic & da', 'basic'],
            bonus: ['bonus'],
            otAmount: ['ot amount'],
            arrears: ['arrears', 'arreras'],
            attendanceBonus: ['attendance bonus'],
