    try {
      const now = new Date();
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => parseFloat(row[mapping[field]!] || '0') || 0;

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attBonus;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const canteen = getVal('canteenDeduction');
        const other = getVal('otherDeduction');
        const totalDeductions = esi + pf + pt + lwf + canteen + other;

        return {
          id: row[mapping.id!] || 'N/A',
          name: row[mapping.name!] || 'Unknown',
          esiNo: row[mapping.esiNo!] || 'N/A',
          uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'),
          workedDays: getVal('workedDays'),
          otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'),
          basicDA,
          bonus,
          otAmount,
          arrears,
          attendanceBonus: attBonus,
          esiDeduction: esi,
          pfDeduction: pf,
          ptDeduction: pt,
          lwfDeduction: lwf,
          canteenDeduction: canteen,
          otherDeduction: other,
          grossEarnings,
          totalDeductions,
          netSalary: grossEarnings - totalDeductions,
          month: monthNames[now.getMonth()],
          year: now.getFullYear()
        } as EmployeeSalaryData;
      });

      setEmployees(prev => [...prev, ...parsedData]);
      setShowMapping(false);
      setUploadError(null);
    } catch (err) {
      setUploadError("Processing failed. Please check your mapping.");
    }
  };

