import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, AreaChart, Area } from 'recharts';
import { TrendingUp, Calculator, ShieldCheck, Download, Calendar, Repeat } from 'lucide-react';

interface InsightsTabProps {
  employees: EmployeeSalaryData[];
}

const InsightsTab: React.FC<InsightsTabProps> = ({ employees }) => {
  const [compareMode, setCompareMode] = useState<'monthly' | 'yearly'>('monthly');

  const totalGross = employees.reduce((sum, emp) => sum + emp.grossEarnings, 0);
  const totalPF = employees.reduce((sum, emp) => sum + emp.pfDeduction, 0);
  const totalESI = employees.reduce((sum, emp) => sum + emp.esiDeduction, 0);
  const totalPT = employees.reduce((sum, emp) => sum + emp.ptDeduction, 0);

  const pieData = [
    { name: 'PF Fund', value: totalPF, color: '#6366f1' },
    { name: 'ESI Payout', value: totalESI, color: '#10b981' },
    { name: 'Prof. Tax', value: totalPT, color: '#f59e0b' },
    { name: 'Others', value: employees.reduce((sum, emp) => sum + emp.lwfDeduction + emp.canteenDeduction + emp.otherDeduction, 0), color: '#ef4444' }
  ];

  const comparisonData = useMemo(() => {
    if (compareMode === 'monthly') {
      const monthMap: Record<string, number> = {};
      employees.forEach(emp => {
        const key = `${emp.month} ${emp.year}`;
        monthMap[key] = (monthMap[key] || 0) + emp.netSalary;
      });
      // Sort by chronological order if possible (simplified for Dec-Jan logic)
      const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      return Object.entries(monthMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => {
          const [mA, yA] = a.name.split(' ');
          const [mB, yB] = b.name.split(' ');
          if (yA !== yB) return parseInt(yA) - parseInt(yB);
          return monthsOrder.indexOf(mA) - monthsOrder.indexOf(mB);
        });
    } else {
      const yearMap: Record<string, number> = {};
      employees.forEach(emp => {
        yearMap[emp.year] = (yearMap[emp.year] || 0) + emp.netSalary;
      });
      return Object.entries(yearMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => parseInt(a.name) - parseInt(b.name));
    }
  }, [employees, compareMode]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900">Financial Insights</h2>
          <p className="text-gray-500 text-sm">Real-time analysis of payroll expenditures</p>
        </div>

        <div className="flex items-center bg-white border border-gray-200 p-1 rounded-2xl shadow-sm">
          <button 
            onClick={() => setCompareMode('monthly')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-all ${compareMode === 'monthly' ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Monthly View
          </button>
          <button 
            onClick={() => setCompareMode('yearly')}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-all ${compareMode === 'yearly' ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-gray-400 hover:text-gray-600'}`}
          >
            Yearly View
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm">
          <TrendingUp className="text-indigo-600 mb-4" size={24} />
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total CTC Payout</p>
          <h4 className="text-xl font-black text-gray-900">₹{totalGross.toLocaleString()}</h4>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm">
          <ShieldCheck className="text-emerald-600 mb-4" size={24} />
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">ESI Contributions</p>
          <h4 className="text-xl font-black text-gray-900">₹{totalESI.toLocaleString()}</h4>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm">
          <Calculator className="text-orange-600 mb-4" size={24} />
          <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">PF Deposits</p>
          <h4 className="text-xl font-black text-gray-900">₹{totalPF.toLocaleString()}</h4>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-gray-100 shadow-sm flex flex-col justify-between">
          <Download className="text-blue-600 mb-4" size={24} />
          <button className="text-[10px] font-bold text-blue-600 uppercase tracking-widest text-left hover:underline">
            Download Report (CSV)
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm">
          <div className="flex items-center justify-between mb-10">
            <h3 className="text-lg font-black text-gray-900">{compareMode === 'monthly' ? 'Monthly' : 'Yearly'} Net Payout Trend</h3>
            <div className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[10px] font-bold uppercase">
              Payout Growth
            </div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={comparisonData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 700, fill: '#94a3b8' }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 700, fill: '#94a3b8' }} tickFormatter={(val) => `₹${(val/100000).toFixed(1)}L`} />
                <Tooltip 
                  cursor={{ stroke: '#e2e8f0', strokeWidth: 1 }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }}
                  formatter={(val: number) => [`₹${val.toLocaleString()}`, 'Net Payout']}
                />
                <Area type="monotone" dataKey="value" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm flex flex-col">
          <h3 className="text-lg font-black text-gray-900 mb-8">Payout Distribution</h3>
          <div className="flex-1 min-h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={70} outerRadius={100} paddingAngle={10} dataKey="value">
                  {pieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                </Pie>
                <Tooltip contentStyle={{ borderRadius: '16px', border: 'none' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="space-y-3 mt-4">
            {pieData.map(item => (
              <div key={item.name} className="flex items-center justify-between p-3 bg-gray-50 rounded-2xl">
                <div className="flex items-center gap-3">
                  <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.color }} />
                  <p className="text-[10px] font-bold text-gray-500 uppercase">{item.name}</p>
                </div>
                <p className="text-xs font-black text-gray-900">₹{item.value.toLocaleString()}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-gray-100 shadow-sm">
        <h3 className="text-lg font-black text-gray-900 mb-6">Comparison Summary</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="p-6 bg-indigo-50 rounded-3xl">
            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mb-1">Avg Net Pay</p>
            <p className="text-lg font-black text-indigo-900">₹{(totalGross/employees.length).toLocaleString(undefined, {maximumFractionDigits: 0})}</p>
          </div>
          <div className="p-6 bg-emerald-50 rounded-3xl">
            <p className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest mb-1">Max Monthly Budget</p>
            <p className="text-lg font-black text-emerald-900">₹{Math.max(...comparisonData.map(d => d.value)).toLocaleString()}</p>
          </div>
          <div className="p-6 bg-orange-50 rounded-3xl">
            <p className="text-[10px] font-bold text-orange-400 uppercase tracking-widest mb-1">Total Employees (Unique)</p>
            <p className="text-lg font-black text-orange-900">{new Set(employees.map(e => e.id)).size}</p>
          </div>
          <div className="p-6 bg-red-50 rounded-3xl">
            <p className="text-[10px] font-bold text-red-400 uppercase tracking-widest mb-1">Statutory Ratio</p>
            <p className="text-lg font-black text-red-900">{((totalPF + totalESI) / totalGross * 100).toFixed(1)}%</p>
          </div>
        </div>
      </div>
    </div>
  );
};

