          month: months[m],
          year: year
        });
      });
    }

    setEmployees(allRecords);
    setUploadError(null);
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const initialMapping: Partial<ColumnMapping> = {};
          const fieldToCsvMap: Record<string, string[]> = {
            id: ['employee', 'id', 'employee id', 'emp code'],
            name: ['employee name', 'name'],
            esiNo: ['esi no', 'esi'],
            uanNo: ['uan no', 'uan'],
            totalDays: ['no of days', 'total days'],
            workedDays: ['worked days', 'days present'],
            otHours: ['ot hours'],
            fixedGross: ['fixed gross'],
            basicDA: ['basic & da', 'basic'],
            bonus: ['bonus'],
            otAmount: ['ot amount'],
            arrears: ['arrears', 'arreras'],
            attendanceBonus: ['attendance bonus'],
            esiDeduction: ['esi @0.75%', 'esi deduction'],
            pfDeduction: ['pf @ 12%', 'pf deduction'],
            ptDeduction: ['pt', 'professional tax'],
            lwfDeduction: ['lwf'],
            otherDeduction: ['other deduction'],
            canteenDeduction: ['canteen']
          };

          Object.keys(fieldToCsvMap).forEach(field => {
            const match = headers.find(h => 
              fieldToCsvMap[field].includes(h.toLowerCase().trim())
            );
            if (match) initialMapping[field as keyof ColumnMapping] = match;
          });

          setMapping(initialMapping);
          setShowMapping(true);
        }
      }
    });
    // Reset file input value to allow re-upload of same file
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => parseFloat(row[mapping[field]!] || '0') || 0;

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attBonus;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const canteen = getVal('canteenDeduction');
        const other = getVal('otherDeduction');
        const totalDeductions = esi + pf + pt + lwf + canteen + other;

        return {
          id: row[mapping.id!] || 'N/A',
          name: row[mapping.name!] || 'Unknown',
          esiNo: row[mapping.esiNo!] || 'N/A',
          uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'),
          workedDays: getVal('workedDays'),
          otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'),
          basicDA,
          bonus,
          otAmount,
          arrears,
          attendanceBonus: attBonus,
          esiDeduction: esi,
          pfDeduction: pf,
          ptDeduction: pt,
          lwfDeduction: lwf,
          canteenDeduction: canteen,
          otherDeduction: other,
          grossEarnings,
          totalDeductions,
          netSalary: grossEarnings - totalDeductions,
          month: monthNames[now.getMonth()],
          year: now.getFullYear()
        } as EmployeeSalaryData;
      });

      setEmployees(prev => [...prev, ...parsedData]);
      setShowMapping(false);
      setUploadError(null);
    } catch (err) {
      setUploadError("Processing failed. Please check your mapping.");
    }
  };

  const clearData = () => {
    setEmployees([]);
    setUploadError(null);
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-72 bg-white border-r border-gray-100 p-6 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-3 mb-8 px-2">
          {companyLogo ? (
            <img src={companyLogo} alt="Company Logo" className="w-12 h-12 object-contain rounded-xl shadow-md border border-gray-100 p-1" />
          ) : (
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white font-bold text-2xl shadow-xl shadow-indigo-100">
              M
            </div>
          )}
          <div>
            <h1 className="text-xl font-extrabold text-gray-900 tracking-tight">Maruthi Admin</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest">HR Portal</p>
          </div>
        </div>

        <div className="mb-6 px-2">
          <button 
            onClick={() => logoInputRef.current?.click()}
            className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-gray-50 border border-gray-200 text-gray-600 rounded-xl text-xs font-bold hover:bg-gray-100 transition-all"
          >
            <ImageIcon size={14} />
            Update Company Logo
          </button>
          <input ref={logoInputRef} type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}>
          <LayoutDashboard size={22} />
          <span>Dashboard</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}>
          <FileText size={22} />
          <span>Payslips</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-3 px-4 py-3.5 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-50 text-indigo-600 font-bold shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}>
          <PieChart size={22} />
          <span>Insights</span>
        </button>

        <div className="mt-auto pt-8 border-t border-gray-50 space-y-3">
          <button onClick={triggerUpload} className="w-full flex items-center justify-center gap-3 px-4 py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98]">
            <Upload size={20} />
            <span>Import CSV</span>
          </button>
          <button onClick={loadDummyData} className="w-full flex items-center justify-center gap-3 px-4 py-3 bg-white border-2 border-indigo-100 text-indigo-600 rounded-2xl font-bold hover:bg-indigo-50 transition-all text-sm">
            <Database size={18} />
            <span>Load Test Data</span>
          </button>
          <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
          <button onClick={clearData} className="w-full mt-3 flex items-center justify-center gap-2 py-3 text-sm font-semibold text-red-500 hover:bg-red-50 rounded-xl transition-colors">
            Reset All Data
          </button>
        </div>
      </nav>

      <main className="flex-1 p-8 overflow-auto">
        {uploadError && (
          <div className="mb-8 p-4 bg-red-50 border border-red-200 rounded-2xl flex items-center gap-4 text-red-700">
            <div className="p-2 bg-red-100 rounded-full"><AlertCircle size={20} /></div>
            <p className="text-sm font-bold">{uploadError}</p>
          </div>
        )}

        {employees.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center max-w-lg mx-auto text-center py-20">
            <div className="w-24 h-24 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-600 mb-8 animate-pulse">
              <Upload size={48} />
            </div>
            <h2 className="text-3xl font-extrabold text-gray-900 mb-4 tracking-tight">Maruthi HR Payslip Portal</h2>
            <p className="text-gray-500 mb-8 leading-relaxed">
              Upload your payroll spreadsheet and use our column mapper to generate official payslips. Or use the test button in the sidebar.
            </p>
            <button onClick={loadDummyData} className="px-8 py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">
              Start with Dummy Data
            </button>
          </div>
        ) : (
          <div className="animate-in fade-in duration-700">
            {activeTab === TabType.HOME && <HomeTab employees={employees} onUploadTrigger={triggerUpload} />}
            {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} companyLogo={companyLogo} />}
            {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
          </div>
        )}
      </main>

      {showMapping && (
        <div className="fixed inset-0 z-50 bg-gray-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-3xl rounded-[32px] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-gray-100 flex items-center justify-between bg-indigo-600 text-white">
              <div>
                <h3 className="text-2xl font-extrabold">Excel Column Mapping</h3>
                <p className="text-indigo-100 text-sm mt-1">Select the correct headers from your file</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { key: 'id', label: 'Employee ID' }, { key: 'name', label: 'Employee Name' }, { key: 'esiNo', label: 'ESI No' },
                { key: 'uanNo', label: 'UAN No' }, { key: 'totalDays', label: 'Total Days' }, { key: 'workedDays', label: 'Worked Days' },
                { key: 'otHours', label: 'OT Hours' }, { key: 'fixedGross', label: 'Fixed Gross' }, { key: 'basicDA', label: 'Basic & DA' },
                { key: 'bonus', label: 'Bonus' }, { key: 'otAmount', label: 'OT Amount' }, { key: 'arrears', label: 'Arrears' },
                { key: 'attendanceBonus', label: 'Attendance Bonus' }, { key: 'esiDeduction', label: 'ESI @ 0.75%' },
                { key: 'pfDeduction', label: 'PF @ 12%' }, { key: 'ptDeduction', label: 'Professional Tax' },
                { key: 'lwfDeduction', label: 'LWF' }, { key: 'otherDeduction', label: 'Other Deduction' },
                { key: 'canteenDeduction', label: 'Canteen' }
              ].map((field) => (
                <div key={field.key} className="flex flex-col gap-2">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">{field.label}</label>
                  <select 
                    value={mapping[field.key as keyof ColumnMapping] || ''}
                    onChange={(e) => setMapping({ ...mapping, [field.key]: e.target.value })}
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm font-semibold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  >
                    <option value="">-- Ignore Field --</option>
                    {csvHeaders.map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>

            <div className="p-8 bg-gray-50 border-t border-gray-100 flex gap-4">
              <button onClick={() => setShowMapping(false)} className="flex-1 py-4 font-bold text-gray-500 bg-white border border-gray-200 rounded-2xl hover:bg-gray-100 transition-all">
                Cancel
              </button>
              <button onClick={processDataWithMapping} className="flex-[2] py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">
                Sync Employee Data
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { Users, CreditCard, PieChart, Calendar, Upload, ChevronLeft, ChevronRight } from 'lucide-react';

interface HomeTabProps {
  employees: EmployeeSalaryData[];
  onUploadTrigger?: () => void;
}

const ITEMS_PER_PAGE = 10;

const HomeTab: React.FC<HomeTabProps> = ({ employees, onUploadTrigger }) => {
  const availablePeriods = useMemo(() => {
    const periods = new Set(employees.map(e => `${e.month} ${e.year}`));
    return Array.from(periods).sort();
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[availablePeriods.length - 1] || "");
  const [currentPage, setCurrentPage] = useState(1);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => `${e.month} ${e.year}` === selectedPeriod);
  }, [employees, selectedPeriod]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredEmployees.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredEmployees.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredEmployees, currentPage]);

  const totalNet = filteredEmployees.reduce((acc, emp) => acc + emp.netSalary, 0);
  const totalPF = filteredEmployees.reduce((acc, emp) => acc + emp.pfDeduction, 0);

  // Reset page when period changes
  React.useEffect(() => {
    setCurrentPage(1);
  }, [selectedPeriod]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Monthly Dashboard</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium">Overview of your workforce and payroll efficiency</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm flex-1 lg:flex-none">
            <Calendar size={18} className="text-indigo-500" />
            <select 
              value={selectedPeriod} 
              onChange={(e) => setSelectedPeriod(e.target.value)}
              className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full"
            >
              {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          <button 
            onClick={onUploadTrigger}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98] flex-1 lg:flex-none"
          >
            <Upload size={18} />
            <span className="whitespace-nowrap">Upload Payroll CSV</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl shadow-inner shadow-indigo-100/50"><Users size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Active Headcount</p>
              <h3 className="text-3xl font-black text-gray-900">{filteredEmployees.length}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-inner shadow-emerald-100/50"><CreditCard size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Net Payout</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalNet.toLocaleString()}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-orange-50 text-orange-600 rounded-2xl shadow-inner shadow-orange-100/50"><PieChart size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Statutory PF</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalPF.toLocaleString()}</h3>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-8 border-b border-gray-50 bg-white flex items-center justify-between">
          <div>
            <h2 className="text-xl font-black text-gray-900 tracking-tight">Employee Register</h2>
            <p className="text-xs text-gray-400 font-medium mt-1">Detailed view of individual earnings and deductions</p>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-emerald-600 uppercase bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">Verified</span>
            <span className="text-[10px] font-bold text-gray-400 uppercase bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-100">{filteredEmployees.length} Total</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/30 text-gray-400 text-[10px] font-bold uppercase tracking-widest border-b border-gray-50">
                <th className="px-8 py-6">Employee</th>
                <th className="px-8 py-6">Statutory Details</th>
                <th className="px-8 py-6">Attendance</th>
                <th className="px-8 py-6 text-right">Gross Pay</th>
                <th className="px-8 py-6 text-right">Deductions</th>
                <th className="px-8 py-6 text-right">Net Salary</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {currentItems.map((emp) => (
                <tr key={`${emp.id}-${emp.month}-${emp.year}`} className="hover:bg-indigo-50/20 transition-colors group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="text-sm font-extrabold text-gray-900 group-hover:text-indigo-600 transition-colors">{emp.name}</p>
                      <p className="text-[10px] text-indigo-400 font-bold tracking-tight uppercase">ID: {emp.id}</p>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col gap-1">
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-300 uppercase w-6">ESI</span>
                        <span className="text-[11px] text-gray-600 font-semibold">{emp.esiNo || 'N/A'}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-300 uppercase w-6">UAN</span>
                        <span className="text-[11px] text-gray-600 font-semibold">{emp.uanNo || 'N/A'}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] font-bold text-gray-400">{((emp.workedDays/emp.totalDays)*100).toFixed(0)}% Presence</span>
                      </div>
                      <div className="h-2 w-32 bg-gray-100 rounded-full overflow-hidden flex shadow-inner">
                        <div 
                          className={`h-full rounded-full ${emp.workedDays/emp.totalDays > 0.8 ? 'bg-emerald-500' : 'bg-amber-500'}`}
                          style={{ width: `${(emp.workedDays/emp.totalDays)*100}%` }}
                        ></div>
                      </div>
                      <p className="text-[10px] font-bold text-gray-600">{emp.workedDays} Days Worked</p>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-right font-black text-sm text-gray-800">
                    ₹{emp.grossEarnings.toLocaleString()}
                  </td>
                  <td className="px-8 py-6 text-right font-black text-sm text-red-500">
                    ₹{emp.totalDeductions.toLocaleString()}
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex flex-col items-end">
                      <span className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-2xl text-xs font-black shadow-sm shadow-indigo-100/50">
                        ₹{emp.netSalary.toLocaleString()}
                      </span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination UI */}
        <div className="px-8 py-6 bg-gray-50/50 border-t border-gray-50 flex flex-col sm:flex-row items-center justify-between gap-4">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">
            Showing <span className="text-gray-900">{Math.min(filteredEmployees.length, (currentPage - 1) * ITEMS_PER_PAGE + 1)}</span> to <span className="text-gray-900">{Math.min(filteredEmployees.length, currentPage * ITEMS_PER_PAGE)}</span> of <span className="text-gray-900">{filteredEmployees.length}</span> Employees
          </p>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
              disabled={currentPage === 1}
              className="p-2.5 bg-white border border-gray-200 rounded-xl text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-sm active:scale-95"
            >
              <ChevronLeft size={18} />
            </button>

            <div className="flex items-center gap-1">
              {[...Array(totalPages)].map((_, i) => {
                const pageNum = i + 1;
                // Show first, last, and pages around current
                if (
                  pageNum === 1 || 
                  pageNum === totalPages || 
                  (pageNum >= currentPage - 1 && pageNum <= currentPage + 1)
                ) {
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setCurrentPage(pageNum)}
                      className={`min-w-[40px] h-[40px] rounded-xl text-xs font-black transition-all shadow-sm ${
                        currentPage === pageNum 
                          ? 'bg-indigo-600 text-white shadow-indigo-200' 
                          : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                } else if (
                  (pageNum === currentPage - 2 && pageNum > 1) ||
                  (pageNum === currentPage + 2 && pageNum < totalPages)
                ) {
                  return <span key={pageNum} className="px-2 text-gray-300 font-bold">...</span>;
                }
                return null;
              })}
            </div>

            <button 
              onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
              disabled={currentPage === totalPages}
              className="p-2.5 bg-white border border-gray-200 rounded-xl text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-sm active:scale-95"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HomeTab;

export interface EmployeeSalaryData {
  id: string;
  name: string;
  esiNo: string;
  uanNo: string;
  totalDays: number;
  workedDays: number;
  otHours: number;
  fixedGross: number;
  basicDA: number;
  bonus: number;
  otAmount: number;
  arrears: number;
  attendanceBonus: number;
  esiDeduction: number;
  pfDeduction: number;
  ptDeduction: number;
  lwfDeduction: number;
  otherDeduction: number;
  canteenDeduction: number;
  // Derived
