/**
 * This service is architected to be swapped with a real backend 
 * (e.g., Supabase, Firebase, or a custom Node.js API).
 * 
 * To move to a real cloud: 
 * 1. Replace the localStorage logic with 'fetch' or your DB SDK.
 * 2. Keep the method signatures identical.
 */

const STORAGE_KEY = 'payslip_portal_cloud_data';

export const cloudApi = {
  /**
   * Fetches all employee records from the "Cloud"
   */
  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    return new Promise((resolve) => {
      // Simulating network latency
      setTimeout(() => {
        const data = localStorage.getItem(STORAGE_KEY);
        resolve(data ? JSON.parse(data) : []);
      }, 800);
    });
  },

  /**
   * Saves a batch of records to the "Cloud"
   */
  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          // In a real backend, this would be a POST /api/employees call
          // For now, we persist to browser's persistent storage
          localStorage.setItem(STORAGE_KEY, JSON.stringify(employees));
          resolve();
        } catch (err) {
          reject(new Error("Cloud storage quota exceeded or connection lost."));
        }
      }, 1500);
    });
  },

  /**
   * Clears all data from the "Cloud"
   */
  async clearCloudData(): Promise<void> {
    return new Promise((resolve) => {
      setTimeout(() => {
        localStorage.removeItem(STORAGE_KEY);
        resolve();
      }, 500);
    });
  }
};

