                { k: 'id', l: 'Employee ID' }, { k: 'name', l: 'Employee Name' }, { k: 'esiNo', l: 'ESI Account' },
                { k: 'uanNo', l: 'UAN Number' }, { k: 'totalDays', l: 'Total Period Days' }, { k: 'workedDays', l: 'Attended Days' },
