  id: string;
  name: string;
  esiNo: string;
  uanNo: string;
  totalDays: number;
  workedDays: number;
  otHours: number;
  fixedGross: number;
  basicDA: number;
  bonus: number;
  otAmount: number;
  arrears: number;
  attendanceBonus: number;
  esiDeduction: number;
  pfDeduction: number;
  ptDeduction: number;
  lwfDeduction: number;
  otherDeduction: number;
  canteenDeduction: number;
  // Derived
  grossEarnings: number;
