  const loadDummyData = () => {
    const dummyNames = ["Aklesh Singh", "Priya Sharma", "Rahul Verma", "Sneha Patil", "Amit Kumar", "Arjun Mehra"];
    const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const allRecords: EmployeeSalaryData[] = [];
    const prevMonthDate = getPrevMonthEnd();

    for (let m = 6; m < months.length; m++) {
      dummyNames.forEach((name, index) => {
        const basicDA = 12000 + Math.random() * 3000;
        const bonus = 500;
        const otAmount = 500;
        const arrears = 0;
        const attendanceBonus = 500;

        const esi = 150;
        const pf = 1800;
        const pt = 200;
        const lwf = 10;
        const canteen = 500;
        const other = 0;

        const grossEarnings = basicDA + bonus + otAmount + arrears + attendanceBonus;
        const totalDeductions = esi + pf + pt + lwf + other + canteen;

        allRecords.push({
          id: `EMP-${index + 101}`, name: name.toUpperCase(), esiNo: '1234567890', uanNo: '100123456789',
          totalDays: 31, workedDays: 26 + Math.floor(Math.random() * 5), otHours: 5, fixedGross: 20000, 
          basicDA, bonus, otAmount, arrears, attendanceBonus, 
          esiDeduction: esi, pfDeduction: pf, ptDeduction: pt, lwfDeduction: lwf, 
          otherDeduction: other, canteenDeduction: canteen, 
          grossEarnings, totalDeductions, netSalary: grossEarnings - totalDeductions, 
          month: months[m], year: 2025, displayDate: prevMonthDate
        });
      });
    }
    setEmployees(allRecords);
    pushToCloud(allRecords);
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const prevMonthDate = getPrevMonthEnd();

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => parseFloat(row[mapping[field]!] || '0') || 0;

        // Calculations strictly as requested:
        // Total Earned Gross = sum(Basic & DA, Bonus, OT Amount, Arrears, Attendance Bonus)
        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attendanceBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attendanceBonus;

        // Total Deductions = sum(ESI @0.75%, PF @ 12%, PT, LWF, Other Deduction, Canteen)
        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const other = getVal('otherDeduction');
        const canteen = getVal('canteenDeduction');
        const totalDeductions = esi + pf + pt + lwf + other + canteen;

        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA, bonus, otAmount, arrears, attendanceBonus,
          esiDeduction: esi, pfDeduction: pf, ptDeduction: pt, lwfDeduction: lwf,
          canteenDeduction: canteen, otherDeduction: other,
          grossEarnings, totalDeductions, netSalary: grossEarnings - totalDeductions, 
          month: monthNames[now.getMonth()], year: now.getFullYear(),
          displayDate: prevMonthDate
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { setUploadError("Mapping processing failed."); }
  };

  const clearData = () => {
    setEmployees([]);
    cloudApi.clearCloudData();
    setSync(prev => ({ ...prev, lastSynced: new Date() }));
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-4 mb-10 px-2">
          <img src={companyLogo} alt="Logo" className="w-14 h-14 object-contain rounded-2xl shadow-lg border border-gray-100 p-2 bg-gray-50/50" />
          <div>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter">Maruthi Admin</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest leading-none">Cloud Portal</p>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} />
          <span>Dashboard</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <FileText size={20} />
          <span>Payslips</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <PieChart size={20} />
          <span>Insights</span>
        </button>

        <div className="mt-8 pt-8 border-t border-gray-50 space-y-4">
          <div className="px-4 py-4 bg-gray-50/50 rounded-2xl border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Database Sync</span>
              <div className={`w-2 h-2 rounded-full ${sync.status === 'online' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'} ${sync.isSyncing ? 'animate-pulse' : ''}`} />
            </div>
            <p className="text-[11px] font-bold text-gray-600 flex items-center gap-2">
              {sync.isSyncing ? <RefreshCcw size={12} className="animate-spin" /> : <Cloud size={12} />}
              {sync.isSyncing ? 'Syncing...' : sync.lastSynced ? `Synced ${sync.lastSynced.toLocaleTimeString()}` : 'Not synced'}
            </p>
          </div>

          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 py-4 text-xs font-black text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all">
            <LogOut size={16} /> LOG OUT
          </button>
        </div>

        <div className="mt-auto space-y-3">
          <button onClick={() => logoInputRef.current?.click()} className="w-full py-3 bg-gray-50 text-[10px] font-black text-gray-500 rounded-xl hover:bg-gray-100 transition-all border border-gray-100 flex items-center justify-center gap-2">
            <ImageIcon size={14} /> REPLACE COMPANY LOGO
          </button>
          <input ref={logoInputRef} type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
          <button onClick={loadDummyData} className="w-full py-3 bg-white text-[10px] font-black text-indigo-500 rounded-xl border-2 border-indigo-50 hover:bg-indigo-50/50 transition-all">LOAD CLOUD TEST DATA</button>
          <button onClick={clearData} className="w-full py-3 text-[10px] font-black text-red-500 bg-red-50 rounded-xl hover:bg-red-100 transition-all">CLEAR ALL DATABASE</button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        {uploadError && (
          <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[24px] flex items-center gap-4 text-red-700 animate-in slide-in-from-top-4">
            <AlertCircle size={24} />
            <p className="text-sm font-bold">{uploadError}</p>
            <button onClick={() => setUploadError(null)} className="ml-auto p-1 hover:bg-red-100 rounded-full transition-colors"><X size={18} /></button>
          </div>
        )}

        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={employees} onUploadTrigger={() => fileInputRef.current?.click()} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
      </main>

      {showMapping && (
        <div className="fixed inset-0 z-50 bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col max-h-[90vh] border border-white">
            <div className="p-10 border-b border-gray-50 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">Cloud Database Mapping</h3>
                <p className="text-indigo-100 text-sm mt-1 font-medium text-pretty">Select the CSV columns that correspond to the fields below.</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={28} /></button>
            </div>
            <div className="p-10 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 bg-gray-50/30">
              {[
                { k: 'id', l: 'Employee ID' }, { k: 'name', l: 'Employee Name' }, { k: 'esiNo', l: 'ESI Account' },
                { k: 'uanNo', l: 'UAN Number' }, { k: 'totalDays', l: 'Total Period Days' }, { k: 'workedDays', l: 'Worked Days' },
                { k: 'otHours', l: 'OT Hours' }, { k: 'fixedGross', l: 'Fixed Gross' }, { k: 'basicDA', l: 'Basic + DA' },
                { k: 'bonus', l: 'Bonus' }, { k: 'otAmount', l: 'OT Amount' }, { k: 'arrears', l: 'Arrears' },
                { k: 'attendanceBonus', l: 'Attendance Bonus' }, { k: 'esiDeduction', l: 'ESI Deduction' },
                { k: 'pfDeduction', l: 'PF Deduction' }, { k: 'ptDeduction', l: 'Prof. Tax' },
                { k: 'lwfDeduction', l: 'LWF' }, { k: 'canteenDeduction', l: 'Canteen' }, { k: 'otherDeduction', l: 'Other Deduction' }
              ].map((f) => (
                <div key={f.k} className="flex flex-col gap-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full" /> {f.l}
                  </label>
                  <select 
                    value={mapping[f.k as keyof ColumnMapping] || ''}
                    onChange={(e) => setMapping({ ...mapping, [f.k]: e.target.value })}
                    className="w-full bg-white border border-gray-200 rounded-2xl px-5 py-3 text-sm font-bold focus:ring-4 focus:ring-indigo-100 outline-none transition-all shadow-sm"
                  >
                    <option value="">-- Ignore Field --</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={() => setShowMapping(false)} className="flex-1 py-5 font-black text-gray-400 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-all uppercase tracking-widest text-xs">Discard</button>
              <button onClick={processDataWithMapping} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> SAVE & SYNC TO CLOUD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { Users, CreditCard, PieChart, Calendar, Upload, ChevronLeft, ChevronRight } from 'lucide-react';

interface HomeTabProps {
  employees: EmployeeSalaryData[];
  onUploadTrigger?: () => void;
}

const ITEMS_PER_PAGE = 10;

const HomeTab: React.FC<HomeTabProps> = ({ employees, onUploadTrigger }) => {
  const availablePeriods = useMemo(() => {
    const periods = new Set(employees.map(e => `${e.month} ${e.year}`));
    return Array.from(periods).sort();
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[availablePeriods.length - 1] || "");
  const [currentPage, setCurrentPage] = useState(1);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => `${e.month} ${e.year}` === selectedPeriod);
  }, [employees, selectedPeriod]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredEmployees.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredEmployees.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredEmployees, currentPage]);

  const totalNet = filteredEmployees.reduce((acc, emp) => acc + emp.netSalary, 0);
  const totalPF = filteredEmployees.reduce((acc, emp) => acc + emp.pfDeduction, 0);

  // Reset page when period changes
  React.useEffect(() => {
    setCurrentPage(1);
  }, [selectedPeriod]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Monthly Dashboard</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium">Overview of your workforce and payroll efficiency</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm flex-1 lg:flex-none">
            <Calendar size={18} className="text-indigo-500" />
            <select 
              value={selectedPeriod} 
              onChange={(e) => setSelectedPeriod(e.target.value)}
              className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full"
            >
              {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          <button 
            onClick={onUploadTrigger}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98] flex-1 lg:flex-none"
          >
            <Upload size={18} />
            <span className="whitespace-nowrap">Upload Payroll CSV</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl shadow-inner shadow-indigo-100/50"><Users size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Active Headcount</p>
              <h3 className="text-3xl font-black text-gray-900">{filteredEmployees.length}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-inner shadow-emerald-100/50"><CreditCard size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Net Payout</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalNet.toLocaleString()}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm transition-all hover:shadow-md">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-orange-50 text-orange-600 rounded-2xl shadow-inner shadow-orange-100/50"><PieChart size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Statutory PF</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalPF.toLocaleString()}</h3>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-8 border-b border-gray-50 bg-white flex items-center justify-between">
          <div>
            <h2 className="text-xl font-black text-gray-900 tracking-tight">Employee Register</h2>
            <p className="text-xs text-gray-400 font-medium mt-1">Detailed view of individual earnings and deductions</p>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-emerald-600 uppercase bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">Verified</span>
            <span className="text-[10px] font-bold text-gray-400 uppercase bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-100">{filteredEmployees.length} Total</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/30 text-gray-400 text-[10px] font-bold uppercase tracking-widest border-b border-gray-50">
                <th className="px-8 py-6">Employee</th>
                <th className="px-8 py-6">Date</th>
                <th className="px-8 py-6">Statutory Details</th>
                <th className="px-8 py-6">Attendance</th>
                <th className="px-8 py-6 text-right">Gross Pay</th>
                <th className="px-8 py-6 text-right">Deductions</th>
                <th className="px-8 py-6 text-right">Net Salary</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {currentItems.map((emp) => (
                <tr key={`${emp.id}-${emp.month}-${emp.year}`} className="hover:bg-indigo-50/20 transition-colors group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="text-sm font-extrabold text-gray-900 group-hover:text-indigo-600 transition-colors">{emp.name}</p>
                      <p className="text-[10px] text-indigo-400 font-bold tracking-tight uppercase">ID: {emp.id}</p>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-xs font-bold text-gray-500 uppercase whitespace-nowrap">
                    {emp.displayDate}
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col gap-1">
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-300 uppercase w-6">ESI</span>
                        <span className="text-[11px] text-gray-600 font-semibold">{emp.esiNo || 'N/A'}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-300 uppercase w-6">UAN</span>
                        <span className="text-[11px] text-gray-600 font-semibold">{emp.uanNo || 'N/A'}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] font-bold text-gray-400">{((emp.workedDays/emp.totalDays)*100).toFixed(0)}% Presence</span>
                      </div>
                      <div className="h-2 w-32 bg-gray-100 rounded-full overflow-hidden flex shadow-inner">
                        <div 
                          className={`h-full rounded-full ${emp.workedDays/emp.totalDays > 0.8 ? 'bg-emerald-500' : 'bg-amber-500'}`}
                          style={{ width: `${(emp.workedDays/emp.totalDays)*100}%` }}
                        ></div>
                      </div>
                      <p className="text-[10px] font-bold text-gray-600">{emp.workedDays} Days Worked</p>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-right font-black text-sm text-gray-800">
                    ₹{emp.grossEarnings.toLocaleString()}
                  </td>
                  <td className="px-8 py-6 text-right font-black text-sm text-red-500">
                    ₹{emp.totalDeductions.toLocaleString()}
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex flex-col items-end">
                      <span className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-2xl text-xs font-black shadow-sm shadow-indigo-100/50">
                        ₹{emp.netSalary.toLocaleString()}
                      </span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination UI */}
        <div className="px-8 py-6 bg-gray-50/50 border-t border-gray-50 flex flex-col sm:flex-row items-center justify-between gap-4">
          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">
            Showing <span className="text-gray-900">{Math.min(filteredEmployees.length, (currentPage - 1) * ITEMS_PER_PAGE + 1)}</span> to <span className="text-gray-900">{Math.min(filteredEmployees.length, currentPage * ITEMS_PER_PAGE)}</span> of <span className="text-gray-900">{filteredEmployees.length}</span> Employees
          </p>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
              disabled={currentPage === 1}
              className="p-2.5 bg-white border border-gray-200 rounded-xl text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-sm active:scale-95"
            >
              <ChevronLeft size={18} />
            </button>

            <div className="flex items-center gap-1">
              {[...Array(totalPages)].map((_, i) => {
                const pageNum = i + 1;
                // Show first, last, and pages around current
                if (
                  pageNum === 1 || 
                  pageNum === totalPages || 
                  (pageNum >= currentPage - 1 && pageNum <= currentPage + 1)
                ) {
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setCurrentPage(pageNum)}
                      className={`min-w-[40px] h-[40px] rounded-xl text-xs font-black transition-all shadow-sm ${
                        currentPage === pageNum 
                          ? 'bg-indigo-600 text-white shadow-indigo-200' 
                          : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                } else if (
                  (pageNum === currentPage - 2 && pageNum > 1) ||
                  (pageNum === currentPage + 2 && pageNum < totalPages)
                ) {
                  return <span key={pageNum} className="px-2 text-gray-300 font-bold">...</span>;
                }
                return null;
              })}
            </div>

            <button 
              onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
              disabled={currentPage === totalPages}
              className="p-2.5 bg-white border border-gray-200 rounded-xl text-gray-400 hover:text-indigo-600 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-sm active:scale-95"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

