import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { Users, CreditCard, PieChart, Calendar, Upload, ChevronLeft, ChevronRight } from 'lucide-react';

interface HomeTabProps {
  employees: EmployeeSalaryData[];
  onUploadTrigger?: () => void;
}

const ITEMS_PER_PAGE = 10;

const HomeTab: React.FC<HomeTabProps> = ({ employees, onUploadTrigger }) => {
  const availablePeriods = useMemo(() => {
    const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const periods = Array.from(new Set(employees.map(e => `${e.month} ${e.year}`)));

    // Explicitly type 'a' and 'b' as strings to resolve TS 'unknown' property error for split()
    return periods.sort((a: string, b: string) => {
      const [mA, yA] = a.split(' ');
      const [mB, yB] = b.split(' ');
      if (yA !== yB) return parseInt(yB) - parseInt(yA); // Recent years first
      return monthsOrder.indexOf(mB) - monthsOrder.indexOf(mA); // Recent months first
    });
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[0] || "");
  const [currentPage, setCurrentPage] = useState(1);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => `${e.month} ${e.year}` === selectedPeriod);
  }, [employees, selectedPeriod]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredEmployees.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredEmployees.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredEmployees, currentPage]);

  const totalNet = filteredEmployees.reduce((acc, emp) => acc + emp.netSalary, 0);
  const totalPF = filteredEmployees.reduce((acc, emp) => acc + emp.pfDeduction, 0);

  // Reset page when period changes
  React.useEffect(() => {
    setCurrentPage(1);
  }, [selectedPeriod]);

  // Sync state if employees change
  React.useEffect(() => {
    if (!selectedPeriod && availablePeriods.length > 0) {
      setSelectedPeriod(availablePeriods[0]);
    }
  }, [availablePeriods, selectedPeriod]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Monthly Dashboard</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium">Overview of your workforce and payroll efficiency</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm flex-1 lg:flex-none">
            <Calendar size={18} className="text-indigo-500" />
            <select 
              value={selectedPeriod} 
              onChange={(e) => setSelectedPeriod(e.target.value)}
              className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full"
            >
              {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          <button 
            onClick={onUploadTrigger}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-[0.98] flex-1 lg:flex-none"
          >
            <Upload size={18} />
            <span className="whitespace-nowrap">Upload Payroll CSV</span>
          </button>
        </div>
