import React, { useState, useCallback, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Upload, 
  AlertCircle,
  X,
  Database,
  Image as ImageIcon,
  Cloud,
  RefreshCcw,
  LogOut,
  CheckCircle2
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping, AuthState, SyncStatus } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import Login from './components/Login';

const DUMMY_LOGO = "data:image/png;base64,";

const FIELD_DEFINITIONS: { key: keyof ColumnMapping; label: string; aliases: string[] }[] = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code', 'emp_id', 'employee_id'] },
  { key: 'name', label: 'Employee Name', aliases: ['name', 'emp name', 'employee name', 'fullname', 'full name'] },
  { key: 'esiNo', label: 'ESI Account', aliases: ['esi', 'esi no', 'esi number', 'esi_no'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan', 'uan no', 'uan number', 'uan_no'] },
  { key: 'totalDays', label: 'Total Period Days', aliases: ['total days', 'days in month', 'month days'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked', 'worked days', 'present', 'present days'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot', 'ot hours', 'overtime hours'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary', 'fixed_gross'] },
  { key: 'basicDA', label: 'Basic + DA', aliases: ['basic', 'basic da', 'basic+da', 'basic_da'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus', 'statutory bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount', 'overtime pay', 'ot_amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears', 'arrear'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus', 'att bonus', 'att_bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction', 'esi @', 'esi_deduction'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'pf @', 'epf', 'pf_deduction'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax', 'professional tax', 'pt_deduction'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf', 'labour welfare', 'lwf_deduction'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen', 'canteen deduction', 'canteen_deduction'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'others', 'misc deduction'] }
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    loading: true
  });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DUMMY_LOGO);
  const [sync, setSync] = useState<SyncStatus>({
    lastSynced: null,
    isSyncing: false,
    status: 'online'
  });

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_admin_session');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
  }, []);

  const handleLogin = (password: string) => {
    if (password === 'admin123') {
      localStorage.setItem('payslip_admin_session', 'active');
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid administrator credentials.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_admin_session');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) {
      loadFromCloud();
    }
  }, [auth.isAuthenticated]);

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud synchronization failed.");
    }
  };

  const handleLogoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => setCompanyLogo(e.target?.result as string);
    reader.readAsDataURL(file);
  };

  const getPrevMonthEnd = () => {
    const now = new Date();
    const lastDayPrev = new Date(now.getFullYear(), now.getMonth(), 0);
    const day = String(lastDayPrev.getDate()).padStart(2, '0');
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const month = monthNames[lastDayPrev.getMonth()];
    const year = lastDayPrev.getFullYear();
    return `${day}-${month}-${year}`;
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim();
    if (str === '-' || str === '') return 0;
    str = str.replace(/,/g, '').replace(/\s/g, '');
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const newMapping: Partial<ColumnMapping> = {};
          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => 
              fieldDef.aliases.some(alias => h.toLowerCase().trim() === alias || h.toLowerCase().includes(alias))
            );
            if (match) {
              if (!Object.values(newMapping).includes(match)) {
                newMapping[fieldDef.key] = match;
              }
            }
          });

          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const prevMonthEndStr = getPrevMonthEnd();

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attendanceBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attendanceBonus;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const other = getVal('otherDeduction');
        const canteen = getVal('canteenDeduction');
        const totalDeductions = esi + pf + pt + lwf + other + canteen;

        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA, bonus, otAmount, arrears, attendanceBonus,
          esiDeduction: esi, pfDeduction: pf, ptDeduction: pt, lwfDeduction: lwf,
          canteenDeduction: canteen, otherDeduction: other,
          grossEarnings, totalDeductions, netSalary: grossEarnings - totalDeductions, 
          month: displayMonth, year: displayYear,
          displayDate: prevMonthEndStr
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { 
      setUploadError("Mapping processing failed."); 
    }
  };

  const clearData = () => {
    setEmployees([]);
    cloudApi.clearCloudData();
    setSync(prev => ({ ...prev, lastSynced: new Date() }));
  };

  const getAvailableHeaders = (currentFieldKey: keyof ColumnMapping) => {
    const selectedHeaders = Object.entries(mapping)
      .filter(([key]) => key !== currentFieldKey)
      .map(([_, header]) => header);
    return csvHeaders.filter(h => !selectedHeaders.includes(h));
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-4 mb-10 px-2">
          <img src={companyLogo} alt="Logo" className="w-14 h-14 object-contain rounded-2xl shadow-lg border border-gray-100 p-2 bg-gray-50/50" />
          <div>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter">Maruthi Admin</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest leading-none">Cloud Portal</p>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} />
          <span>Dashboard</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <FileText size={20} />
          <span>Payslips</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <PieChart size={20} />
          <span>Insights</span>
        </button>

        <div className="mt-8 pt-8 border-t border-gray-50 space-y-4">
          <div className="px-4 py-4 bg-gray-50/50 rounded-2xl border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Database Sync</span>
              <div className={`w-2 h-2 rounded-full ${sync.status === 'online' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'} ${sync.isSyncing ? 'animate-pulse' : ''}`} />
            </div>
            <p className="text-[11px] font-bold text-gray-600 flex items-center gap-2">
              {sync.isSyncing ? <RefreshCcw size={12} className="animate-spin" /> : <Cloud size={12} />}
              {sync.isSyncing ? 'Syncing...' : sync.lastSynced ? `Synced ${sync.lastSynced.toLocaleTimeString()}` : 'Not synced'}
            </p>
          </div>

          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 py-4 text-xs font-black text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all">
            <LogOut size={16} /> LOG OUT
          </button>
        </div>

        <div className="mt-auto space-y-3">
          <button onClick={() => logoInputRef.current?.click()} className="w-full py-3 bg-gray-50 text-[10px] font-black text-gray-500 rounded-xl hover:bg-gray-100 transition-all border border-gray-100 flex items-center justify-center gap-2">
            <ImageIcon size={14} /> REPLACE COMPANY LOGO
          </button>
          <input ref={logoInputRef} type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
          <button onClick={clearData} className="w-full py-3 text-[10px] font-black text-red-500 bg-red-50 rounded-xl hover:bg-red-100 transition-all">CLEAR ALL DATABASE</button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        {uploadError && (
          <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[24px] flex items-center gap-4 text-red-700 animate-in slide-in-from-top-4">
            <AlertCircle size={24} />
            <p className="text-sm font-bold">{uploadError}</p>
            <button onClick={() => setUploadError(null)} className="ml-auto p-1 hover:bg-red-100 rounded-full transition-colors"><X size={18} /></button>
          </div>
        )}

        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={employees} onUploadTrigger={() => fileInputRef.current?.click()} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
      </main>

      {showMapping && (
        <div className="fixed inset-0 z-50 bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col max-h-[90vh] border border-white">
            <div className="p-10 border-b border-gray-50 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">Cloud Database Mapping</h3>
                <p className="text-indigo-100 text-sm mt-1 font-medium text-pretty">Map CSV columns to database fields. Used columns are hidden from other lists.</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={28} /></button>
            </div>
            <div className="p-10 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 bg-gray-50/30">
              {FIELD_DEFINITIONS.map((f) => (
                <div key={f.key} className="flex flex-col gap-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${mapping[f.key] ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'bg-gray-300'}`} /> 
                    {f.label}
                    {mapping[f.key] && <CheckCircle2 size={12} className="text-emerald-500 ml-auto" />}
                  </label>
                  <select 
                    value={mapping[f.key] || ''}
                    onChange={(e) => setMapping({ ...mapping, [f.key]: e.target.value })}
                    className={`w-full bg-white border rounded-2xl px-5 py-3 text-sm font-bold focus:ring-4 focus:ring-indigo-100 outline-none transition-all shadow-sm ${mapping[f.key] ? 'border-emerald-200 text-gray-900' : 'border-gray-200 text-gray-400'}`}
                  >
                    <option value="">-- Ignore Field --</option>
                    {mapping[f.key] && <option value={mapping[f.key]}>{mapping[f.key]}</option>}
                    {getAvailableHeaders(f.key).map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={() => setShowMapping(false)} className="flex-1 py-5 font-black text-gray-400 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-all uppercase tracking-widest text-xs">Discard</button>
              <button onClick={processDataWithMapping} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> SYNC TO CLOUD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { EmployeeSalaryData } from '../types';
import { Download, FileDown, Search, Eye, X, Loader2, Calendar } from 'lucide-react';
import { generateSinglePayslip, generateBulkPayslips } from '../utils/pdfGenerator';

interface PayslipsTabProps {
  employees: EmployeeSalaryData[];
  companyLogo?: string;
}

const PayslipsTab: React.FC<PayslipsTabProps> = ({ employees, companyLogo }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [previewPdfUrl, setPreviewPdfUrl] = useState<string | null>(null);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const availablePeriods = useMemo(() => {
    const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const periods = Array.from(new Set(employees.map(e => `${e.month} ${e.year}`)));

    return periods.sort((a: string, b: string) => {
      const [mA, yA] = a.split(' ');
      const [mB, yB] = b.split(' ');
      if (yA !== yB) return parseInt(yB) - parseInt(yA);
      return monthsOrder.indexOf(mB) - monthsOrder.indexOf(mA);
    });
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[0] || "");

  const filteredEmployees = useMemo(() => {
    return employees.filter(emp => {
      const matchesSearch = emp.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           emp.id.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesPeriod = !selectedPeriod || `${emp.month} ${emp.year}` === selectedPeriod;
      return matchesSearch && matchesPeriod;
    });
  }, [employees, searchTerm, selectedPeriod]);

  const handleViewPdf = (emp: EmployeeSalaryData) => {
    try {
      if (previewPdfUrl) {
        URL.revokeObjectURL(previewPdfUrl);
      }

      const doc = generateSinglePayslip(emp, companyLogo, false);
      const arrBuffer = doc.output('arraybuffer');
      const blob = new Blob([arrBuffer], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);

      setPreviewPdfUrl(url);
      setIsPreviewOpen(true);
    } catch (err) {
      console.error("PDF Preview generation failed", err);
    }
  };

  const closePreview = () => {
    if (previewPdfUrl) {
      URL.revokeObjectURL(previewPdfUrl);
      setPreviewPdfUrl(null);
    }
    setIsPreviewOpen(false);
  };

  useEffect(() => {
    return () => {
      if (previewPdfUrl) URL.revokeObjectURL(previewPdfUrl);
    };
  }, [previewPdfUrl]);

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Generate Payslips</h2>
          <p className="text-gray-500 font-medium">Download individual or bulk salary statements</p>
        </div>
        <button 
          onClick={() => generateBulkPayslips(filteredEmployees, companyLogo)}
          className="flex items-center gap-3 px-6 py-4 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 uppercase tracking-widest text-xs"
        >
          <FileDown size={18} />
          <span>Download {selectedPeriod || 'Filtered'} Bulk</span>
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-indigo-600 transition-colors" size={20} />
          <input 
            type="text" 
            placeholder="Search by name or employee ID..."
            className="w-full pl-14 pr-6 py-5 bg-white border border-gray-100 rounded-[24px] focus:ring-4 focus:ring-indigo-50 outline-none transition-all shadow-sm font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-3 bg-white px-6 py-5 rounded-[24px] border border-gray-100 shadow-sm md:w-64">
          <Calendar size={20} className="text-indigo-500" />
          <select 
            value={selectedPeriod} 
            onChange={(e) => setSelectedPeriod(e.target.value)}
            className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full"
          >
            <option value="">All Periods</option>
            {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {filteredEmployees.map((emp) => (
          <div key={`${emp.id}-${emp.month}-${emp.year}`} className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all flex flex-col group">
            <div className="flex justify-between items-start mb-6">
              <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black text-xl overflow-hidden border border-indigo-100 shadow-inner">
                {companyLogo ? (
                   <img src={companyLogo} alt="" className="w-full h-full object-contain p-2" />
                ) : emp.name[0]}
              </div>
              <div className="text-right">
                <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">
                  Ready
                </span>
              </div>
            </div>

            <h4 className="font-black text-gray-900 truncate tracking-tight">{emp.name}</h4>
            <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mb-6">Emp ID: {emp.id}</p>

            <div className="space-y-3 mb-8 bg-gray-50/50 p-4 rounded-2xl border border-gray-100">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Period</span>
                <span className="text-xs font-black text-gray-700">{emp.month} {emp.year}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Net Payable</span>
                <span className="text-sm font-black text-indigo-600">₹{emp.netSalary.toLocaleString()}</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3 mt-auto">
              <button 
                onClick={() => handleViewPdf(emp)}
                className="flex items-center justify-center gap-2 py-3.5 bg-white text-gray-600 font-black rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-all text-[10px] uppercase tracking-widest"
              >
                <Eye size={16} />
                <span>View</span>
              </button>
              <button 
                onClick={() => generateSinglePayslip(emp, companyLogo)}
                className="flex items-center justify-center gap-2 py-3.5 bg-indigo-50 text-indigo-600 font-black rounded-2xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all text-[10px] uppercase tracking-widest shadow-sm shadow-indigo-100/50"
              >
                <Download size={16} />
                <span>Get PDF</span>
              </button>
            </div>
          </div>
        ))}
      </div>

      {isPreviewOpen && previewPdfUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-10 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-6xl h-full max-h-[90vh] rounded-[40px] shadow-3xl overflow-hidden flex flex-col border border-white animate-in zoom-in-95 duration-300">
            <div className="p-8 border-b border-gray-100 bg-white flex items-center justify-between">
              <div>
                <h3 className="text-xl font-black text-gray-900 tracking-tight flex items-center gap-3">
                  <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl"><Eye size={20}/></div>
                  Payslip Preview
                </h3>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">Maruthi HR Solution • Live View</p>
              </div>
              <button 
                onClick={closePreview}
                className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-500 rounded-2xl transition-all border border-transparent hover:border-red-100"
              >
                <X size={24} />
              </button>
            </div>
            <div className="flex-1 bg-gray-100/50 relative flex items-center justify-center">
              <div className="absolute inset-0 flex items-center justify-center text-gray-300 -z-10">
                <Loader2 size={48} className="animate-spin text-indigo-200" />
              </div>
              <object 
                key={previewPdfUrl}
                data={`${previewPdfUrl}#toolbar=0&navpanes=0`} 
                type="application/pdf"
                className="w-full h-full border-none bg-white rounded-b-2xl" 
              >
                 <div className="flex flex-col items-center justify-center h-full p-10 text-center">
                    <p className="text-gray-500 font-bold mb-4">Your browser does not support inline PDF viewing.</p>
                    <a href={previewPdfUrl} download="Payslip_Preview.pdf" className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-black">Download to View</a>
                 </div>
              </object>
            </div>
            <div className="p-8 bg-white border-t border-gray-100 flex justify-end gap-4">
              <button 
                onClick={closePreview}
                className="px-8 py-4 font-black text-gray-400 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-all uppercase tracking-widest text-xs"
              >
                Close Preview
              </button>
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = previewPdfUrl;
                  link.download = `Payslip_Preview.pdf`;
                  link.click();
                }}
                className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center gap-3"
              >
                <Download size={18} /> Download Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PayslipsTab;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Upload, 
  AlertCircle,
  X,
  Database,
  Image as ImageIcon,
  Cloud,
  RefreshCcw,
  LogOut,
  CheckCircle2
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping, AuthState, SyncStatus } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import Login from './components/Login';

const DUMMY_LOGO = "data:image/png;base64,";

const FIELD_DEFINITIONS: { key: keyof ColumnMapping; label: string; aliases: string[] }[] = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code', 'emp_id', 'employee_id'] },
  { key: 'name', label: 'Employee Name', aliases: ['name', 'emp name', 'employee name', 'fullname', 'full name'] },
  { key: 'esiNo', label: 'ESI Account', aliases: ['esi', 'esi no', 'esi number', 'esi_no'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan', 'uan no', 'uan number', 'uan_no'] },
  { key: 'totalDays', label: 'Total Period Days', aliases: ['total days', 'days in month', 'month days'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked', 'worked days', 'present', 'present days'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot', 'ot hours', 'overtime hours'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary', 'fixed_gross'] },
  { key: 'basicDA', label: 'Basic + DA', aliases: ['basic', 'basic da', 'basic+da', 'basic_da'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus', 'statutory bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount', 'overtime pay', 'ot_amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears', 'arrear'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus', 'att bonus', 'att_bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction', 'esi @', 'esi_deduction'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'pf @', 'epf', 'pf_deduction'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax', 'professional tax', 'pt_deduction'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf', 'labour welfare', 'lwf_deduction'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen', 'canteen deduction', 'canteen_deduction'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'others', 'misc deduction'] }
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    loading: true
  });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DUMMY_LOGO);
  const [sync, setSync] = useState<SyncStatus>({
    lastSynced: null,
    isSyncing: false,
    status: 'online'
  });

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_admin_session');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
  }, []);

  const handleLogin = (password: string) => {
    if (password === 'admin123') {
      localStorage.setItem('payslip_admin_session', 'active');
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid administrator credentials.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_admin_session');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) {
      loadFromCloud();
    }
  }, [auth.isAuthenticated]);

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud synchronization failed.");
    }
  };

  const handleLogoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => setCompanyLogo(e.target?.result as string);
    reader.readAsDataURL(file);
  };

  const getPrevMonthEnd = () => {
    const now = new Date();
    const lastDayPrev = new Date(now.getFullYear(), now.getMonth(), 0);
    const day = String(lastDayPrev.getDate()).padStart(2, '0');
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const month = monthNames[lastDayPrev.getMonth()];
    const year = lastDayPrev.getFullYear();
    return `${day}-${month}-${year}`;
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim();
    if (str === '-' || str === '') return 0;
    str = str.replace(/,/g, '').replace(/\s/g, '');
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const newMapping: Partial<ColumnMapping> = {};
          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => 
              fieldDef.aliases.some(alias => h.toLowerCase().trim() === alias || h.toLowerCase().includes(alias))
            );
            if (match) {
              if (!Object.values(newMapping).includes(match)) {
                newMapping[fieldDef.key] = match;
              }
            }
          });

          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const prevMonthEndStr = getPrevMonthEnd();

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attendanceBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attendanceBonus;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const other = getVal('otherDeduction');
        const canteen = getVal('canteenDeduction');
        const totalDeductions = esi + pf + pt + lwf + other + canteen;

        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA, bonus, otAmount, arrears, attendanceBonus,
          esiDeduction: esi, pfDeduction: pf, ptDeduction: pt, lwfDeduction: lwf,
          canteenDeduction: canteen, otherDeduction: other,
          grossEarnings, totalDeductions, netSalary: grossEarnings - totalDeductions, 
          month: displayMonth, year: displayYear,
          displayDate: prevMonthEndStr
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { 
      setUploadError("Mapping processing failed."); 
    }
  };

  const clearData = () => {
    setEmployees([]);
    cloudApi.clearCloudData();
    setSync(prev => ({ ...prev, lastSynced: new Date() }));
  };

  const getAvailableHeaders = (currentFieldKey: keyof ColumnMapping) => {
    const selectedHeaders = Object.entries(mapping)
      .filter(([key]) => key !== currentFieldKey)
      .map(([_, header]) => header);
    return csvHeaders.filter(h => !selectedHeaders.includes(h));
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-4 mb-10 px-2">
          <img src={companyLogo} alt="Logo" className="w-14 h-14 object-contain rounded-2xl shadow-lg border border-gray-100 p-2 bg-gray-50/50" />
          <div>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter">Maruthi Admin</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest leading-none">Cloud Portal</p>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} />
          <span>Dashboard</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <FileText size={20} />
          <span>Payslips</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <PieChart size={20} />
          <span>Insights</span>
        </button>

        <div className="mt-8 pt-8 border-t border-gray-50 space-y-4">
          <div className="px-4 py-4 bg-gray-50/50 rounded-2xl border border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Database Sync</span>
              <div className={`w-2 h-2 rounded-full ${sync.status === 'online' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500'} ${sync.isSyncing ? 'animate-pulse' : ''}`} />
            </div>
            <p className="text-[11px] font-bold text-gray-600 flex items-center gap-2">
              {sync.isSyncing ? <RefreshCcw size={12} className="animate-spin" /> : <Cloud size={12} />}
              {sync.isSyncing ? 'Syncing...' : sync.lastSynced ? `Synced ${sync.lastSynced.toLocaleTimeString()}` : 'Not synced'}
            </p>
          </div>

          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 py-4 text-xs font-black text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all">
            <LogOut size={16} /> LOG OUT
          </button>
        </div>

        <div className="mt-auto space-y-3">
          <button onClick={() => logoInputRef.current?.click()} className="w-full py-3 bg-gray-50 text-[10px] font-black text-gray-500 rounded-xl hover:bg-gray-100 transition-all border border-gray-100 flex items-center justify-center gap-2">
            <ImageIcon size={14} /> REPLACE COMPANY LOGO
          </button>
          <input ref={logoInputRef} type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" />
          <button onClick={clearData} className="w-full py-3 text-[10px] font-black text-red-500 bg-red-50 rounded-xl hover:bg-red-100 transition-all">CLEAR ALL DATABASE</button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        {uploadError && (
          <div className="mb-8 p-5 bg-red-50 border border-red-100 rounded-[24px] flex items-center gap-4 text-red-700 animate-in slide-in-from-top-4">
            <AlertCircle size={24} />
            <p className="text-sm font-bold">{uploadError}</p>
            <button onClick={() => setUploadError(null)} className="ml-auto p-1 hover:bg-red-100 rounded-full transition-colors"><X size={18} /></button>
          </div>
        )}

        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={employees} onUploadTrigger={() => fileInputRef.current?.click()} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={employees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={employees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
      </main>

      {showMapping && (
        <div className="fixed inset-0 z-50 bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col max-h-[90vh] border border-white">
            <div className="p-10 border-b border-gray-50 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black tracking-tight">Cloud Database Mapping</h3>
                <p className="text-indigo-100 text-sm mt-1 font-medium text-pretty">Map CSV columns to database fields. Used columns are hidden from other lists.</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={28} /></button>
            </div>
            <div className="p-10 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 bg-gray-50/30">
              {FIELD_DEFINITIONS.map((f) => (
                <div key={f.key} className="flex flex-col gap-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${mapping[f.key] ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'bg-gray-300'}`} /> 
                    {f.label}
                    {mapping[f.key] && <CheckCircle2 size={12} className="text-emerald-500 ml-auto" />}
                  </label>
                  <select 
                    value={mapping[f.key] || ''}
                    onChange={(e) => setMapping({ ...mapping, [f.key]: e.target.value })}
                    className={`w-full bg-white border rounded-2xl px-5 py-3 text-sm font-bold focus:ring-4 focus:ring-indigo-100 outline-none transition-all shadow-sm ${mapping[f.key] ? 'border-emerald-200 text-gray-900' : 'border-gray-200 text-gray-400'}`}
                  >
                    <option value="">-- Ignore Field --</option>
                    {mapping[f.key] && <option value={mapping[f.key]}>{mapping[f.key]}</option>}
                    {getAvailableHeaders(f.key).map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={() => setShowMapping(false)} className="flex-1 py-5 font-black text-gray-400 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-all uppercase tracking-widest text-xs">Discard</button>
              <button onClick={processDataWithMapping} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> SYNC TO CLOUD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { EmployeeSalaryData } from '../types';
import { Download, FileDown, Search, Eye, X, Loader2, Calendar } from 'lucide-react';
import { generateSinglePayslip, generateBulkPayslips } from '../utils/pdfGenerator';

interface PayslipsTabProps {
  employees: EmployeeSalaryData[];
  companyLogo?: string;
}

const PayslipsTab: React.FC<PayslipsTabProps> = ({ employees, companyLogo }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [previewPdfUrl, setPreviewPdfUrl] = useState<string | null>(null);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const availablePeriods = useMemo(() => {
    const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const periods = Array.from(new Set(employees.map(e => `${e.month} ${e.year}`)));

    return periods.sort((a: string, b: string) => {
      const [mA, yA] = a.split(' ');
      const [mB, yB] = b.split(' ');
      if (yA !== yB) return parseInt(yB) - parseInt(yA);
      return monthsOrder.indexOf(mB) - monthsOrder.indexOf(mA);
    });
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[0] || "");

  const filteredEmployees = useMemo(() => {
    return employees.filter(emp => {
      const matchesSearch = emp.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           emp.id.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesPeriod = !selectedPeriod || `${emp.month} ${emp.year}` === selectedPeriod;
      return matchesSearch && matchesPeriod;
    });
  }, [employees, searchTerm, selectedPeriod]);

  const handleViewPdf = (emp: EmployeeSalaryData) => {
    try {
      if (previewPdfUrl) {
        URL.revokeObjectURL(previewPdfUrl);
      }

      const doc = generateSinglePayslip(emp, companyLogo, false);
      const arrBuffer = doc.output('arraybuffer');
      // Create a typed array for the blob to ensure stability
      const uint8Array = new Uint8Array(arrBuffer);
      const blob = new Blob([uint8Array], { type: 'application/pdf' });
      const url = URL.createObjectURL(blob);

      setPreviewPdfUrl(url);
      setIsPreviewOpen(true);
    } catch (err) {
      console.error("PDF Preview generation failed", err);
    }
  };

  const closePreview = () => {
    if (previewPdfUrl) {
      URL.revokeObjectURL(previewPdfUrl);
      setPreviewPdfUrl(null);
    }
    setIsPreviewOpen(false);
  };

  useEffect(() => {
    return () => {
      if (previewPdfUrl) URL.revokeObjectURL(previewPdfUrl);
    };
  }, [previewPdfUrl]);

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Generate Payslips</h2>
          <p className="text-gray-500 font-medium">Download individual or bulk salary statements</p>
        </div>
        <button 
          onClick={() => generateBulkPayslips(filteredEmployees, companyLogo)}
          className="flex items-center gap-3 px-6 py-4 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 uppercase tracking-widest text-xs"
        >
          <FileDown size={18} />
          <span>Download {selectedPeriod || 'Filtered'} Bulk</span>
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-indigo-600 transition-colors" size={20} />
          <input 
            type="text" 
            placeholder="Search by name or employee ID..."
            className="w-full pl-14 pr-6 py-5 bg-white border border-gray-100 rounded-[24px] focus:ring-4 focus:ring-indigo-50 outline-none transition-all shadow-sm font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-3 bg-white px-6 py-5 rounded-[24px] border border-gray-100 shadow-sm md:w-64">
          <Calendar size={20} className="text-indigo-500" />
          <select 
            value={selectedPeriod} 
            onChange={(e) => setSelectedPeriod(e.target.value)}
            className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full"
          >
            <option value="">All Periods</option>
            {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {filteredEmployees.map((emp) => (
          <div key={`${emp.id}-${emp.month}-${emp.year}`} className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all flex flex-col group">
            <div className="flex justify-between items-start mb-6">
              <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black text-xl overflow-hidden border border-indigo-100 shadow-inner">
                {companyLogo ? (
                   <img src={companyLogo} alt="" className="w-full h-full object-contain p-2" />
                ) : emp.name[0]}
              </div>
              <div className="text-right">
                <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">
                  Ready
                </span>
              </div>
            </div>

            <h4 className="font-black text-gray-900 truncate tracking-tight">{emp.name}</h4>
            <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mb-6">Emp ID: {emp.id}</p>

            <div className="space-y-3 mb-8 bg-gray-50/50 p-4 rounded-2xl border border-gray-100">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Period</span>
                <span className="text-xs font-black text-gray-700">{emp.month} {emp.year}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Net Payable</span>
                <span className="text-sm font-black text-indigo-600">₹{emp.netSalary.toLocaleString()}</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3 mt-auto">
              <button 
                onClick={() => handleViewPdf(emp)}
                className="flex items-center justify-center gap-2 py-3.5 bg-white text-gray-600 font-black rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-all text-[10px] uppercase tracking-widest"
              >
                <Eye size={16} />
                <span>View</span>
              </button>
              <button 
                onClick={() => generateSinglePayslip(emp, companyLogo)}
                className="flex items-center justify-center gap-2 py-3.5 bg-indigo-50 text-indigo-600 font-black rounded-2xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all text-[10px] uppercase tracking-widest shadow-sm shadow-indigo-100/50"
              >
                <Download size={16} />
                <span>Get PDF</span>
              </button>
            </div>
          </div>
        ))}
      </div>

      {isPreviewOpen && previewPdfUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-10 bg-gray-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-6xl h-full max-h-[90vh] rounded-[40px] shadow-3xl overflow-hidden flex flex-col border border-white animate-in zoom-in-95 duration-300">
            <div className="p-8 border-b border-gray-100 bg-white flex items-center justify-between">
              <div>
                <h3 className="text-xl font-black text-gray-900 tracking-tight flex items-center gap-3">
                  <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl"><Eye size={20}/></div>
                  Payslip Preview
                </h3>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">Maruthi HR Solution • Portal View</p>
              </div>
              <button 
                onClick={closePreview}
                className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-500 rounded-2xl transition-all border border-transparent hover:border-red-100"
              >
                <X size={24} />
              </button>
            </div>
            <div className="flex-1 bg-gray-100/50 relative flex items-center justify-center">
              <div className="absolute inset-0 flex items-center justify-center text-gray-300 -z-10">
                <Loader2 size={48} className="animate-spin text-indigo-200" />
              </div>
              {/* Using clean iframe without fragments for maximum compatibility */}
              <iframe 
                key={previewPdfUrl}
                src={previewPdfUrl} 
                className="w-full h-full border-none bg-white rounded-b-2xl" 
                title="Payslip PDF Viewer"
              />
            </div>
            <div className="p-8 bg-white border-t border-gray-100 flex justify-end gap-4">
              <button 
                onClick={closePreview}
                className="px-8 py-4 font-black text-gray-400 bg-gray-50 rounded-2xl hover:bg-gray-100 transition-all uppercase tracking-widest text-xs"
              >
                Close Preview
              </button>
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = previewPdfUrl;
                  link.download = `Payslip_Preview.pdf`;
                  link.click();
                }}
                className="px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center gap-3"
              >
                <Download size={18} /> Download Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PayslipsTab;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Upload, 
  AlertCircle,
  X,
  Database,
  Image as ImageIcon,
  Cloud,
  RefreshCcw,
  LogOut,
  CheckCircle2
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping, AuthState, SyncStatus } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import Login from './components/Login';

const DUMMY_LOGO = "data:image/png;base64,";

const FIELD_DEFINITIONS: { key: keyof ColumnMapping; label: string; aliases: string[] }[] = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code', 'emp_id', 'employee_id'] },
  { key: 'name', label: 'Employee Name', aliases: ['name', 'emp name', 'employee name', 'fullname', 'full name'] },
  { key: 'esiNo', label: 'ESI Account', aliases: ['esi', 'esi no', 'esi number', 'esi_no'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan', 'uan no', 'uan number', 'uan_no'] },
  { key: 'totalDays', label: 'Total Period Days', aliases: ['total days', 'days in month', 'month days'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked', 'worked days', 'present', 'present days'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot', 'ot hours', 'overtime hours'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary', 'fixed_gross'] },
  { key: 'basicDA', label: 'Basic + DA', aliases: ['basic', 'basic da', 'basic+da', 'basic_da'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus', 'statutory bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount', 'overtime pay', 'ot_amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears', 'arrear'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus', 'att bonus', 'att_bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction', 'esi @', 'esi_deduction'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'pf @', 'epf', 'pf_deduction'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax', 'professional tax', 'pt_deduction'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf', 'labour welfare', 'lwf_deduction'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen', 'canteen deduction', 'canteen_deduction'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'others', 'misc deduction'] }
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    loading: true
  });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DUMMY_LOGO);
  const [sync, setSync] = useState<SyncStatus>({
    lastSynced: null,
    isSyncing: false,
    status: 'online'
  });

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_admin_session');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
  }, []);

  const handleLogin = (password: string) => {
    if (password === 'admin123') {
      localStorage.setItem('payslip_admin_session', 'active');
      setAuth({ isAuthenticated: true, user: 'Admin', loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid administrator credentials.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_admin_session');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) {
      loadFromCloud();
    }
  }, [auth.isAuthenticated]);

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud synchronization failed.");
    }
  };

  const handleLogoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => setCompanyLogo(e.target?.result as string);
    reader.readAsDataURL(file);
  };

  const getPrevMonthEnd = () => {
    const now = new Date();
    const lastDayPrev = new Date(now.getFullYear(), now.getMonth(), 0);
    const day = String(lastDayPrev.getDate()).padStart(2, '0');
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const month = monthNames[lastDayPrev.getMonth()];
    const year = lastDayPrev.getFullYear();
    return `${day}-${month}-${year}`;
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim();
    if (str === '-' || str === '') return 0;
    str = str.replace(/,/g, '').replace(/\s/g, '');
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const newMapping: Partial<ColumnMapping> = {};
          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => 
              fieldDef.aliases.some(alias => h.toLowerCase().trim() === alias || h.toLowerCase().includes(alias))
            );
            if (match) {
              if (!Object.values(newMapping).includes(match)) {
                newMapping[fieldDef.key] = match;
              }
            }
          });

          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const prevMonthEndStr = getPrevMonthEnd();

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);

        const basicDA = getVal('basicDA');
        const bonus = getVal('bonus');
        const otAmount = getVal('otAmount');
        const arrears = getVal('arrears');
        const attendanceBonus = getVal('attendanceBonus');
        const grossEarnings = basicDA + bonus + otAmount + arrears + attendanceBonus;

        const esi = getVal('esiDeduction');
        const pf = getVal('pfDeduction');
        const pt = getVal('ptDeduction');
        const lwf = getVal('lwfDeduction');
        const other = getVal('otherDeduction');
        const canteen = getVal('canteenDeduction');
        const totalDeductions = esi + pf + pt + lwf + other + canteen;

        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA, bonus, otAmount, arrears, attendanceBonus,
          esiDeduction: esi, pfDeduction: pf, ptDeduction: pt, lwfDeduction: lwf,
          canteenDeduction: canteen, otherDeduction: other,
          grossEarnings, totalDeductions, netSalary: grossEarnings - totalDeductions, 
          month: displayMonth, year: displayYear,
          displayDate: prevMonthEndStr
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { 
      setUploadError("Mapping processing failed."); 
    }
  };

  const clearData = () => {
    setEmployees([]);
    cloudApi.clearCloudData();
    setSync(prev => ({ ...prev, lastSynced: new Date() }));
  };

  const getAvailableHeaders = (currentFieldKey: keyof ColumnMapping) => {
    const selectedHeaders = Object.entries(mapping)
      .filter(([key]) => key !== currentFieldKey)
      .map(([_, header]) => header);
    return csvHeaders.filter(h => !selectedHeaders.includes(h));
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-4 mb-10 px-2">
          <img src={companyLogo} alt="Logo" className="w-14 h-14 object-contain rounded-2xl shadow-lg border border-gray-100 p-2 bg-gray-50/50" />
          <div>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter">Maruthi Admin</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest leading-none">Cloud Portal</p>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-xl shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} />
