    if (currentEmployee) {
       const doc = generateSinglePayslip(currentEmployee, companyLogo, false);
       // This is the most robust way to open a PDF in a new window/tab
       doc.output('dataurlnewwindow');
    }
  };

  const handleZipDownload = async () => {
    if (filteredEmployees.length === 0) return;
    setIsZipping(true);
    try {
      await generateIndividualZippedPayslips(filteredEmployees, companyLogo);
    } catch (err) {
      console.error("ZIP Generation failed", err);
