          >
            {isZipping ? <Loader2 size={16} className="animate-spin" /> : <FolderArchive size={16} />}
            <span>Download Individuals (ZIP)</span>
          </button>
          <button 
            onClick={() => generateBulkPayslips(filteredEmployees, companyLogo)}
