import React, { useState, useEffect } from 'react';
import { User, Role, EmployeeSalaryData } from '../types';
import { cloudApi } from '../services/api';
import { UserPlus, RefreshCcw, Key, Shield, Trash2, CheckCircle2, AlertCircle } from 'lucide-react';

interface UserManagementTabProps {
  employees: EmployeeSalaryData[];
}

const UserManagementTab: React.FC<UserManagementTabProps> = ({ employees }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    const data = await cloudApi.fetchUsers();
    setUsers(data);
  };

  const generatePassword = () => {
    const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    return Array(8).fill(0).map(() => chars[Math.floor(Math.random() * chars.length)]).join('');
  };

  const handleAutoProvision = async () => {
    setIsGenerating(true);
    const uniqueEmpIds = Array.from(new Set(employees.map(e => e.id)));
    const existingUsernames = new Set(users.map(u => u.username));

    const newUsers: User[] = [...users];
    let createdCount = 0;

    uniqueEmpIds.forEach(id => {
      if (!existingUsernames.has(id)) {
        const emp = employees.find(e => e.id === id);
        newUsers.push({
          username: id,
          password: generatePassword(),
          role: Role.EMPLOYEE,
          name: emp?.name
        });
        createdCount++;
      }
    });

    if (createdCount > 0) {
      await cloudApi.saveUsers(newUsers);
      setUsers(newUsers);
      setSuccessMsg(`Successfully provisioned ${createdCount} new employee accounts.`);
    } else {
      setSuccessMsg("No new employees found to provision.");
    }

    setIsGenerating(false);
    setTimeout(() => setSuccessMsg(null), 5000);
  };

  const deleteUser = async (username: string) => {
    if (username === 'admin') return; // Protect system admin
    const updated = users.filter(u => u.username !== username);
    await cloudApi.saveUsers(updated);
    setUsers(updated);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col md:flex-row items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Access Control</h2>
          <p className="text-sm text-gray-500 font-medium">Manage login credentials for your workforce</p>
        </div>

        <button 
          onClick={handleAutoProvision}
          disabled={isGenerating || employees.length === 0}
          className="flex items-center gap-3 px-6 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all disabled:opacity-50"
        >
          {isGenerating ? <RefreshCcw size={18} className="animate-spin" /> : <UserPlus size={18} />}
          <span className="text-xs uppercase tracking-widest">Auto-Provision Accounts</span>
        </button>
      </div>

      {successMsg && (
