            <button onClick={() => generateBulkPayslips(filteredEmployees, companyLogo)} className="flex items-center gap-3 px-6 py-4 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-100 uppercase tracking-widest text-[10px]">
              <FileDown size={18} /><span>Bulk PDF</span>
            </button>
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        {showBulkOptions && (
          <div className="relative group flex-1">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-indigo-600" size={20} />
            <input type="text" placeholder="Search by name or employee ID..." className="w-full pl-14 pr-6 py-5 bg-white border border-gray-100 rounded-[24px] focus:ring-4 focus:ring-indigo-50 outline-none transition-all shadow-sm font-medium" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
