];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DUMMY_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'online' });

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_session_v2');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: JSON.parse(savedSession), loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
  }, []);

  const handleLogin = async (username: string, password: string) => {
    const user = await cloudApi.authenticate(username, password);
    if (user) {
      localStorage.setItem('payslip_session_v2', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid credentials. Check Username/ID and Password.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_session_v2');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) loadFromCloud();
  }, [auth.isAuthenticated]);

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud synchronization failed.");
    }
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim().replace(/,/g, '').replace(/\s/g, '');
    if (str === '-' || str === '') return 0;
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true, skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);
          const newMapping: Partial<ColumnMapping> = {};
          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => fieldDef.aliases.some(alias => h.toLowerCase().trim().includes(alias)));
            if (match && !Object.values(newMapping).includes(match)) newMapping[fieldDef.key] = match;
          });
          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const day = String(prevDateObj.getDate()).padStart(2, '0');
      const prevMonthEndStr = `${day}-${displayMonth}-${displayYear}`;

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);
        const earnings = getVal('basicDA') + getVal('bonus') + getVal('otAmount') + getVal('arrears') + getVal('attendanceBonus');
        const deductions = getVal('esiDeduction') + getVal('pfDeduction') + getVal('ptDeduction') + getVal('lwfDeduction') + getVal('otherDeduction') + getVal('canteenDeduction');
        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA: getVal('basicDA'), bonus: getVal('bonus'),
          otAmount: getVal('otAmount'), arrears: getVal('arrears'), attendanceBonus: getVal('attendanceBonus'),
          esiDeduction: getVal('esiDeduction'), pfDeduction: getVal('pfDeduction'), ptDeduction: getVal('ptDeduction'),
          lwfDeduction: getVal('lwfDeduction'), canteenDeduction: getVal('canteenDeduction'), otherDeduction: getVal('otherDeduction'),
          grossEarnings: earnings, totalDeductions: deductions, netSalary: earnings - deductions, 
          month: displayMonth, year: displayYear, displayDate: prevMonthEndStr
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { setUploadError("Mapping failed."); }
  };

  // Roles & Permissions
  const isAdmin = auth.user?.role === Role.ADMIN;
  // Note: HR/Finance staff (Role.EMPLOYEE) now see ALL employees, same as admin.
  const displayEmployees = employees;

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex items-center gap-4 mb-10 px-2">
          <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3">
             <Building2 size={28} />
          </div>
          <div>
            <h1 className="text-xl font-black text-gray-900 tracking-tighter">Payroll Pro</h1>
            <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest leading-none">
              {isAdmin ? 'Payroll Admin' : 'HR/Finance Staff'}
            </p>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} /><span>Dashboard</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold' : 'text-gray-400 hover:bg-gray-50'}`}>
          <FileText size={20} /><span>Employee Payslips</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold' : 'text-gray-400 hover:bg-gray-50'}`}>
          <PieChart size={20} /><span>Finance Insights</span>
        </button>

        {isAdmin && (
          <button onClick={() => setActiveTab(TabType.USERS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.USERS ? 'bg-indigo-600 text-white font-bold' : 'text-gray-400 hover:bg-gray-50'}`}>
            <UsersIcon size={20} /><span>Manage Staff</span>
          </button>
        )}

        <div className="mt-8 pt-8 border-t border-gray-50 space-y-4">
          <div className="px-4 py-4 bg-gray-50 rounded-2xl border border-gray-100">
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Signed in as</p>
            <p className="text-xs font-bold text-gray-700 truncate">{auth.user?.name || auth.user?.username}</p>
          </div>
          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 py-4 text-xs font-black text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all">
            <LogOut size={16} /> LOG OUT
          </button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={displayEmployees} onUploadTrigger={isAdmin ? () => fileInputRef.current?.click() : undefined} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={displayEmployees} companyLogo={companyLogo} showBulkOptions={isAdmin} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={displayEmployees} />}
          {activeTab === TabType.USERS && isAdmin && <UserManagementTab employees={employees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
      </main>

      {showMapping && isAdmin && (
        <div className="fixed inset-0 z-50 bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-10 border-b border-gray-50 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-2xl font-black">CSV Data Mapping</h3>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={28} /></button>
            </div>
            <div className="p-10 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 bg-gray-50/30">
              {FIELD_DEFINITIONS.map((f) => (
                <div key={f.key} className="flex flex-col gap-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase">{f.label}</label>
                  <select value={mapping[f.key] || ''} onChange={(e) => setMapping({ ...mapping, [f.key]: e.target.value })} className="w-full bg-white border border-gray-200 rounded-2xl px-5 py-3 text-sm font-bold">
                    <option value="">-- Ignore --</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={processDataWithMapping} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> COMPLETE UPLOAD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { Users, CreditCard, PieChart, Calendar, Upload, ChevronLeft, ChevronRight, TrendingUp } from 'lucide-react';

interface HomeTabProps {
  employees: EmployeeSalaryData[];
  onUploadTrigger?: () => void;
}

const ITEMS_PER_PAGE = 10;

const HomeTab: React.FC<HomeTabProps> = ({ employees, onUploadTrigger }) => {
  // Always company-wide view since this app is for HR/Finance staff
  const availablePeriods = useMemo(() => {
    const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const periods = Array.from(new Set(employees.map(e => `${e.month} ${e.year}`)));
    return periods.sort((a: string, b: string) => {
      const [mA, yA] = a.split(' ');
      const [mB, yB] = b.split(' ');
      if (yA !== yB) return parseInt(yB) - parseInt(yA);
      return monthsOrder.indexOf(mB) - monthsOrder.indexOf(mA);
    });
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[0] || "");
  const [currentPage, setCurrentPage] = useState(1);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => `${e.month} ${e.year}` === selectedPeriod);
  }, [employees, selectedPeriod]);

  const totalPages = Math.ceil(filteredEmployees.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredEmployees.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredEmployees, currentPage]);

  const totalNet = filteredEmployees.reduce((acc, emp) => acc + emp.netSalary, 0);
  const totalPF = filteredEmployees.reduce((acc, emp) => acc + emp.pfDeduction, 0);

  React.useEffect(() => { setCurrentPage(1); }, [selectedPeriod]);
  React.useEffect(() => {
    if (!selectedPeriod && availablePeriods.length > 0) setSelectedPeriod(availablePeriods[0]);
  }, [availablePeriods, selectedPeriod]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Payroll Overview</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium">Monitoring company-wide payroll distribution and efficiency</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          {availablePeriods.length > 0 && (
            <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm flex-1 lg:flex-none">
              <Calendar size={18} className="text-indigo-500" />
              <select value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)} className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full">
                {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          )}

          {onUploadTrigger && (
            <button onClick={onUploadTrigger} className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98] flex-1 lg:flex-none">
              <Upload size={18} /><span className="whitespace-nowrap">Upload Monthly Data</span>
            </button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl shadow-inner"><Users size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Employees</p>
              <h3 className="text-3xl font-black text-gray-900">{filteredEmployees.length}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-inner"><CreditCard size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Net Payout</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalNet.toLocaleString()}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-orange-50 text-orange-600 rounded-2xl shadow-inner"><PieChart size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">PF Statutory Fund</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalPF.toLocaleString()}</h3>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-8 border-b border-gray-50 bg-white flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 tracking-tight">Staff Payroll Register</h2>
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-emerald-600 uppercase bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">Ready for Audit</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/30 text-gray-400 text-[10px] font-bold uppercase tracking-widest border-b border-gray-50">
                <th className="px-8 py-6">Staff Member</th>
                <th className="px-8 py-6">Period</th>
                <th className="px-8 py-6">Attendance</th>
                <th className="px-8 py-6 text-right">Gross Pay</th>
                <th className="px-8 py-6 text-right">Deductions</th>
                <th className="px-8 py-6 text-right">Net Payable</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {currentItems.map((emp) => (
                <tr key={`${emp.id}-${emp.month}-${emp.year}`} className="hover:bg-indigo-50/20 transition-colors group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="text-sm font-extrabold text-gray-900 group-hover:text-indigo-600">{emp.name}</p>
                      <p className="text-[10px] text-indigo-400 font-bold uppercase">ID: {emp.id}</p>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-xs font-bold text-gray-500 uppercase">{emp.month} {emp.year}</td>
                  <td className="px-8 py-6">
                    <div className="space-y-1.5">
                      <div className="h-2 w-32 bg-gray-100 rounded-full overflow-hidden flex">
                        <div className={`h-full rounded-full ${emp.workedDays/emp.totalDays > 0.8 ? 'bg-emerald-500' : 'bg-amber-500'}`} style={{ width: `${(emp.workedDays/emp.totalDays)*100}%` }}></div>
                      </div>
                      <p className="text-[10px] font-bold text-gray-600">{emp.workedDays} Days Worked</p>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-right font-black text-sm text-gray-800">₹{emp.grossEarnings.toLocaleString()}</td>
                  <td className="px-8 py-6 text-right font-black text-sm text-red-500">₹{emp.totalDeductions.toLocaleString()}</td>
                  <td className="px-8 py-6 text-right">
                    <span className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-2xl text-xs font-black">₹{emp.netSalary.toLocaleString()}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {totalPages > 1 && (
          <div className="px-8 py-6 bg-gray-50/50 border-t border-gray-50 flex items-center justify-between">
            <p className="text-xs font-bold text-gray-400 uppercase">Page {currentPage} of {totalPages}</p>
            <div className="flex items-center gap-2">
              <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} className="p-2.5 bg-white border border-gray-200 rounded-xl"><ChevronLeft size={18} /></button>
              <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} className="p-2.5 bg-white border border-gray-200 rounded-xl"><ChevronRight size={18} /></button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default HomeTab;

import React, { useState, useEffect } from 'react';
import { User, Role, EmployeeSalaryData } from '../types';
import { cloudApi } from '../services/api';
import { UserPlus, RefreshCcw, Key, Shield, Trash2, CheckCircle2, AlertCircle, X, UserCheck } from 'lucide-react';

interface UserManagementTabProps {
  employees: EmployeeSalaryData[];
}

const UserManagementTab: React.FC<UserManagementTabProps> = ({ employees }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Form State
  const [newUserName, setNewUserName] = useState('');
  const [newUserUsername, setNewUserUsername] = useState('');
  const [newUserPassword, setNewUserPassword] = useState('');
  const [newUserRole, setNewUserRole] = useState<Role>(Role.EMPLOYEE);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    const data = await cloudApi.fetchUsers();
    setUsers(data);
  };

  const generatePassword = () => {
    const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%";
    const pass = Array(10).fill(0).map(() => chars[Math.floor(Math.random() * chars.length)]).join('');
    setNewUserPassword(pass);
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUserName || !newUserUsername || !newUserPassword) return;

    const newUser: User = {
      name: newUserName,
      username: newUserUsername,
      password: newUserPassword,
      role: newUserRole
    };

    const updatedUsers = [...users, newUser];
    await cloudApi.saveUsers(updatedUsers);
    setUsers(updatedUsers);
    setSuccessMsg(`Account created for ${newUserName}`);
    setIsModalOpen(false);

    // Reset form
    setNewUserName('');
    setNewUserUsername('');
    setNewUserPassword('');
    setNewUserRole(Role.EMPLOYEE);

    setTimeout(() => setSuccessMsg(null), 3000);
  };

  const deleteUser = async (username: string) => {
    if (username === 'admin') return; 
    const updated = users.filter(u => u.username !== username);
    await cloudApi.saveUsers(updated);
    setUsers(updated);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col md:flex-row items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Staff Management</h2>
          <p className="text-sm text-gray-500 font-medium">Control access for Payroll and HR/Finance team members</p>
        </div>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-3 px-6 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all"
        >
          <UserPlus size={18} />
          <span className="text-xs uppercase tracking-widest">Add New Staff Member</span>
        </button>
      </div>

      {successMsg && (
        <div className="p-5 bg-emerald-50 border border-emerald-100 rounded-2xl flex items-center gap-4 text-emerald-700 animate-in slide-in-from-top-4">
          <CheckCircle2 size={24} />
          <p className="text-sm font-bold">{successMsg}</p>
        </div>
      )}

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50/50 border-b border-gray-50">
              <tr className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                <th className="px-8 py-6">Staff Name</th>
                <th className="px-8 py-6">Username / ID</th>
                <th className="px-8 py-6">Role / Team</th>
