}

export type ColumnMapping = Record<keyof Omit<EmployeeSalaryData, 'grossEarnings' | 'totalDeductions' | 'netSalary' | 'month' | 'year' | 'displayDate'>, string>;

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
  loading: boolean;
}

export interface SyncStatus {
  lastSynced: Date | null;
  isSyncing: boolean;
