import { EmployeeSalaryData, User, Role } from '../types';

const STORAGE_KEY = 'payslip_portal_cloud_data';
const USERS_KEY = 'payslip_portal_users';

// Initialize with a default admin if none exists
const initializeUsers = () => {
  const existing = localStorage.getItem(USERS_KEY);
  if (!existing) {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'admin@maruthi.com'
    };
    localStorage.setItem(USERS_KEY, JSON.stringify([defaultAdmin]));
  }
};

initializeUsers();

export const cloudApi = {
  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    return new Promise((resolve) => {
      setTimeout(() => {
        const data = localStorage.getItem(STORAGE_KEY);
        resolve(data ? JSON.parse(data) : []);
      }, 500);
    });
  },

  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(employees));
          resolve();
        } catch (err) {
          reject(new Error("Cloud storage quota exceeded."));
        }
      }, 800);
    });
  },

  async clearCloudData(): Promise<void> {
    localStorage.removeItem(STORAGE_KEY);
  },

  // User Management
  async fetchUsers(): Promise<User[]> {
    const data = localStorage.getItem(USERS_KEY);
    return data ? JSON.parse(data) : [];
  },

  async saveUsers(users: User[]): Promise<void> {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
  },

  // Fixed the return type of authenticate to Promise<User | null> to resolve async typing and Object assignment errors
  async authenticate(username: string, password: string): Promise<User | null> {
    const users = await this.fetchUsers();
    const user = users.find(u => u.username === username && u.password === password);
    return user || null;
  }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
