const STORAGE_KEY = 'payslip_portal_cloud_data_v3';
const USERS_KEY = 'payslip_portal_users_v3';
const ENCRYPTION_SECRET = 'MARUTHI_SECURE_2025_KEY'; // In a real app, this would be server-side

// Simulated Encryption Helper
const secureStore = {
  encrypt: (data: any): string => {
    const json = JSON.stringify(data);
    // Simple Base64 + Secret Salt obfuscation for prototype security
    return btoa(unescape(encodeURIComponent(json + ENCRYPTION_SECRET)));
  },
  decrypt: (cipher: string): any => {
    try {
      const decoded = decodeURIComponent(escape(atob(cipher)));
      const cleanJson = decoded.replace(ENCRYPTION_SECRET, '');
      return JSON.parse(cleanJson);
    } catch (e) {
      console.error("Decryption failed - data integrity compromised");
      return null;
    }
  }
};

const initializeUsers = () => {
  const existing = localStorage.getItem(USERS_KEY);
  if (!existing) {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'maruthihrsolution25@gmail.com'
    };
    localStorage.setItem(USERS_KEY, secureStore.encrypt([defaultAdmin]));
  }
};

