import React, { useState, useMemo } from 'react';
import { EmployeeSalaryData } from '../types';
import { Users, CreditCard, PieChart, Calendar, Upload, ChevronLeft, ChevronRight, TrendingUp, Building2, Shield, Eye, EyeOff } from 'lucide-react';

interface HomeTabProps {
  employees: EmployeeSalaryData[];
  onUploadTrigger?: () => void;
}

const ITEMS_PER_PAGE = 10;

const MaskedField: React.FC<{ value: string; label: string }> = ({ value, label }) => {
  const [show, setShow] = useState(false);
  const maskedValue = value && value !== 'N/A' 
    ? `${value.slice(0, 3)} •••• ${value.slice(-4)}` 
    : value;

  return (
    <div className="flex items-center gap-2 group/mask cursor-help" onClick={() => setShow(!show)} title={`Click to toggle ${label}`}>
      <span className="text-[10px] font-bold text-gray-400 uppercase w-12">{label}:</span>
      <span className="text-[10px] font-black text-gray-800 font-mono">
        {show ? value : maskedValue}
      </span>
      {show ? <EyeOff size={10} className="text-indigo-400" /> : <Eye size={10} className="text-gray-300 opacity-0 group-hover/mask:opacity-100" />}
    </div>
  );
};

const HomeTab: React.FC<HomeTabProps> = ({ employees, onUploadTrigger }) => {
  const availablePeriods = useMemo(() => {
    const monthsOrder = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const periods = Array.from(new Set(employees.map(e => `${e.month} ${e.year}`)));
    return periods.sort((a: string, b: string) => {
      const [mA, yA] = a.split(' ');
      const [mB, yB] = b.split(' ');
      if (yA !== yB) return parseInt(yB) - parseInt(yA);
      return monthsOrder.indexOf(mB) - monthsOrder.indexOf(mA);
    });
  }, [employees]);

  const [selectedPeriod, setSelectedPeriod] = useState(availablePeriods[0] || "");
  const [currentPage, setCurrentPage] = useState(1);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => `${e.month} ${e.year}` === selectedPeriod);
  }, [employees, selectedPeriod]);

  const totalPages = Math.ceil(filteredEmployees.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredEmployees.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredEmployees, currentPage]);

  const totalNet = filteredEmployees.reduce((acc, emp) => acc + emp.netSalary, 0);
  const totalPF = filteredEmployees.reduce((acc, emp) => acc + emp.pfDeduction, 0);

  React.useEffect(() => { setCurrentPage(1); }, [selectedPeriod]);
  React.useEffect(() => {
    if (!selectedPeriod && availablePeriods.length > 0) setSelectedPeriod(availablePeriods[0]);
  }, [availablePeriods, selectedPeriod]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Payroll Summary</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium">Monitoring company-wide payroll distribution for auditing purposes</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          {availablePeriods.length > 0 && (
            <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-100 shadow-sm flex-1 lg:flex-none">
              <Calendar size={18} className="text-indigo-500" />
              <select value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)} className="text-sm font-bold text-gray-700 bg-transparent outline-none cursor-pointer w-full">
                {availablePeriods.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          )}

          {onUploadTrigger && (
            <button onClick={onUploadTrigger} className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98] flex-1 lg:flex-none">
              <Upload size={18} /><span className="whitespace-nowrap">Import Monthly Ledger</span>
            </button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl shadow-inner"><Users size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Audit Population</p>
              <h3 className="text-3xl font-black text-gray-900">{filteredEmployees.length}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-inner"><CreditCard size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Disbursements</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalNet.toLocaleString()}</h3>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] border border-gray-100 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-orange-50 text-orange-600 rounded-2xl shadow-inner"><PieChart size={24} /></div>
            <div>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1">PF Statutory Pool</p>
              <h3 className="text-3xl font-black text-gray-900">₹{totalPF.toLocaleString()}</h3>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-8 border-b border-gray-50 bg-white flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 tracking-tight flex items-center gap-3">
             <Building2 className="text-indigo-400" size={24} /> Workforce Register
          </h2>
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-emerald-600 uppercase bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100 flex items-center gap-2">
              <Shield size={12} /> Audit Ready & Secured
            </span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/30 text-gray-400 text-[10px] font-bold uppercase tracking-widest border-b border-gray-50">
                <th className="px-8 py-6">Employee Member</th>
                <th className="px-8 py-6">Period</th>
                <th className="px-8 py-6 text-right">Gross Earnings</th>
                <th className="px-8 py-6 text-right">Total Deductions</th>
                <th className="px-8 py-6 text-right">Net Payable</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {currentItems.map((emp) => (
                <tr key={`${emp.id}-${emp.month}-${emp.year}`} className="hover:bg-indigo-50/20 transition-colors group">
                  <td className="px-8 py-6">
                    <div className="space-y-1">
                      <p className="text-sm font-extrabold text-gray-900 group-hover:text-indigo-600">{emp.name}</p>
                      <div className="flex flex-col gap-1">
                        <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-tighter">ID: {emp.id}</p>
                        <MaskedField label="ESI" value={emp.esiNo} />
                        <MaskedField label="UAN" value={emp.uanNo} />
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-xs font-bold text-gray-500 uppercase">{emp.month} {emp.year}</td>
                  <td className="px-8 py-6 text-right font-black text-sm text-gray-800">₹{emp.grossEarnings.toLocaleString()}</td>
                  <td className="px-8 py-6 text-right font-black text-sm text-red-500">₹{emp.totalDeductions.toLocaleString()}</td>
                  <td className="px-8 py-6 text-right">
                    <span className="px-5 py-2 bg-indigo-50 text-indigo-600 rounded-2xl text-xs font-black">₹{emp.netSalary.toLocaleString()}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {totalPages > 1 && (
          <div className="px-8 py-6 bg-gray-50/50 border-t border-gray-50 flex items-center justify-between">
            <p className="text-xs font-bold text-gray-400 uppercase">Page {currentPage} of {totalPages}</p>
            <div className="flex items-center gap-2">
              <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} className="p-2.5 bg-white border border-gray-200 rounded-xl"><ChevronLeft size={18} /></button>
              <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} className="p-2.5 bg-white border border-gray-200 rounded-xl"><ChevronRight size={18} /></button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default HomeTab;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Users as UsersIcon,
  Upload, 
  AlertCircle,
  X,
  Image as ImageIcon,
  Cloud,
  RefreshCcw,
  LogOut,
  CheckCircle2,
  ShieldCheck,
  Building2,
  Camera,
  ShieldAlert,
  Lock
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping, AuthState, SyncStatus, Role, User } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import UserManagementTab from './components/UserManagementTab';
import Login from './components/Login';

const DEFAULT_LOGO = "data:image/png;base64,";

const FIELD_DEFINITIONS: { key: keyof ColumnMapping; label: string; aliases: string[] }[] = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code'] },
  { key: 'name', label: 'Employee Name', aliases: ['name', 'emp name', 'fullname'] },
  { key: 'esiNo', label: 'ESI Account', aliases: ['esi'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan'] },
  { key: 'totalDays', label: 'Total Period Days', aliases: ['total days', 'days in month'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked', 'worked days', 'present'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot', 'ot hours'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary'] },
  { key: 'basicDA', label: 'Basic + DA', aliases: ['basic', 'basic da'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'epf'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'others'] }
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DEFAULT_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'online' });

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedLogo = localStorage.getItem('company_logo');
    if (savedLogo) setCompanyLogo(savedLogo);

    const savedSession = localStorage.getItem('payslip_session_v3');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: JSON.parse(savedSession), loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
  }, []);

  const handleLogin = async (username: string, password: string) => {
    const user = await cloudApi.authenticate(username, password);
    if (user) {
      localStorage.setItem('payslip_session_v3', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid credentials. Access denied.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_session_v3');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) loadFromCloud();
  }, [auth.isAuthenticated]);

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ lastSynced: new Date(), isSyncing: false, status: 'online' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud synchronization failed.");
    }
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setCompanyLogo(base64);
        localStorage.setItem('company_logo', base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim().replace(/,/g, '').replace(/\s/g, '');
    if (str === '-' || str === '') return 0;
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true, skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const newMapping: Partial<ColumnMapping> = {};
          const assignedHeaders = new Set<string>();

          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => 
              !assignedHeaders.has(h) && 
              fieldDef.aliases.some(alias => h.toLowerCase().trim().includes(alias))
            );
            if (match) {
              newMapping[fieldDef.key] = match;
              assignedHeaders.add(match);
            }
          });

          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const day = String(prevDateObj.getDate()).padStart(2, '0');
      const prevMonthEndStr = `${day}-${displayMonth}-${displayYear}`;

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);
        const earnings = getVal('basicDA') + getVal('bonus') + getVal('otAmount') + getVal('arrears') + getVal('attendanceBonus');
        const deductions = getVal('esiDeduction') + getVal('pfDeduction') + getVal('ptDeduction') + getVal('lwfDeduction') + getVal('otherDeduction') + getVal('canteenDeduction');
        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA: getVal('basicDA'), bonus: getVal('bonus'),
          otAmount: getVal('otAmount'), arrears: getVal('arrears'), attendanceBonus: getVal('attendanceBonus'),
          esiDeduction: getVal('esiDeduction'), pfDeduction: getVal('pfDeduction'), ptDeduction: getVal('ptDeduction'),
          lwfDeduction: getVal('lwfDeduction'), canteenDeduction: getVal('canteenDeduction'), otherDeduction: getVal('otherDeduction'),
          grossEarnings: earnings, totalDeductions: deductions, netSalary: earnings - deductions, 
          month: displayMonth, year: displayYear, displayDate: prevMonthEndStr
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { setUploadError("Mapping failed."); }
  };

  const isAdmin = auth.user?.role === Role.ADMIN;

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex flex-col gap-6 mb-10">
          <div className="relative group w-24 h-24 self-center">
            <div className="w-24 h-24 bg-gray-50 rounded-3xl flex items-center justify-center overflow-hidden border border-gray-100 shadow-sm transition-all group-hover:scale-[1.02]">
              {companyLogo ? (
                <img src={companyLogo} alt="Company Logo" className="w-full h-full object-contain p-2" />
              ) : (
                <Building2 size={32} className="text-gray-300" />
              )}
            </div>
            {isAdmin && (
              <button 
                onClick={() => logoInputRef.current?.click()}
                className="absolute -bottom-2 -right-2 p-2.5 bg-indigo-600 text-white rounded-2xl shadow-lg border-4 border-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-700 active:scale-95"
