const STORAGE_KEY = 'payslip_portal_cloud_data_v3';
const USERS_KEY = 'payslip_portal_users_v3';
const EMPLOYERS_KEY = 'payslip_portal_employers_v3';
const ENCRYPTION_SECRET = 'MARUTHI_SECURE_2025_KEY';

const secureStore = {
  encrypt: (data: any): string => {
    const json = JSON.stringify(data);
    return btoa(unescape(encodeURIComponent(json + ENCRYPTION_SECRET)));
  },
  decrypt: (cipher: string): any => {
    try {
      const decoded = decodeURIComponent(escape(atob(cipher)));
      const cleanJson = decoded.replace(ENCRYPTION_SECRET, '');
      return JSON.parse(cleanJson);
    } catch (e) {
      console.error("Decryption failed");
      return null;
    }
  }
};

