import { EmployeeSalaryData, User, Role } from '../types';

const STORAGE_KEY = 'payslip_portal_cloud_data_v3';
const USERS_KEY = 'payslip_portal_users_v3';
const EMPLOYERS_KEY = 'payslip_portal_employers_v3';
const ENCRYPTION_SECRET = 'MARUTHI_SECURE_2025_KEY';

const secureStore = {
  encrypt: (data: any): string => {
    const json = JSON.stringify(data);
    return btoa(unescape(encodeURIComponent(json + ENCRYPTION_SECRET)));
  },
  decrypt: (cipher: string): any => {
    try {
      const decoded = decodeURIComponent(escape(atob(cipher)));
      const cleanJson = decoded.replace(ENCRYPTION_SECRET, '');
      return JSON.parse(cleanJson);
    } catch (e) {
      console.error("Decryption failed");
      return null;
    }
  }
};

const initializeData = () => {
  const existingUsers = localStorage.getItem(USERS_KEY);
  if (!existingUsers) {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'maruthihrsolution25@gmail.com'
    };
    localStorage.setItem(USERS_KEY, secureStore.encrypt([defaultAdmin]));
  }

  const existingEmployers = localStorage.getItem(EMPLOYERS_KEY);
  if (!existingEmployers) {
    localStorage.setItem(EMPLOYERS_KEY, secureStore.encrypt(['HEALTHY FOOD PRODUCTS']));
  }
};

initializeData();

export const cloudApi = {
  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    const cipher = localStorage.getItem(STORAGE_KEY);
    if (!cipher) return [];
    return secureStore.decrypt(cipher) || [];
  },

  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    const cipher = secureStore.encrypt(employees);
    localStorage.setItem(STORAGE_KEY, cipher);
  },

  async fetchUsers(): Promise<User[]> {
    const cipher = localStorage.getItem(USERS_KEY);
    if (!cipher) return [];
    return secureStore.decrypt(cipher) || [];
  },

  async saveUsers(users: User[]): Promise<void> {
    const cipher = secureStore.encrypt(users);
    localStorage.setItem(USERS_KEY, cipher);
  },

  async fetchEmployers(): Promise<string[]> {
    const cipher = localStorage.getItem(EMPLOYERS_KEY);
    if (!cipher) return ['HEALTHY FOOD PRODUCTS'];
    return secureStore.decrypt(cipher) || ['HEALTHY FOOD PRODUCTS'];
  },

  async saveEmployers(employers: string[]): Promise<void> {
    const cipher = secureStore.encrypt(employers);
    localStorage.setItem(EMPLOYERS_KEY, cipher);
  },

  async authenticate(username: string, password: string): Promise<User | null> {
    const users = await this.fetchUsers();
    const user = users.find(u => u.username === username && u.password === password);
    return user || null;
  },

  // Full System Backup for Cloud Safety
  async exportFullDatabase(): Promise<string> {
    const data = {
      employees: await this.fetchEmployees(),
      users: await this.fetchUsers(),
      employers: await this.fetchEmployers(),
      timestamp: new Date().toISOString()
    };
    return JSON.stringify(data, null, 2);
  }
};

