        const { data } = await supabase.from('payroll_records').select('data').eq('id', 'global_users').single();
        if (data?.data) return data.data;
      } catch (e) {}
    }

    const localData = await localOp<User[]>(STORES.USERS, 'readonly', (s) => s.get('all_users'));
    if (!localData) {
      await this.saveUsers([defaultAdmin]);
      return [defaultAdmin];
    }
    return localData;
  },

  async saveUsers(users: User[]): Promise<void> {
    await localOp(STORES.USERS, 'readwrite', (s) => s.put(users, 'all_users'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_users', data: users });
    }
