];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DEFAULT_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'offline' });

  const [employers, setEmployers] = useState<string[]>([]);
  const [selectedEmployer, setSelectedEmployer] = useState<string>('');

  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const handleLogout = useCallback((reason?: string) => {
    localStorage.removeItem('payslip_session_v5');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    if (reason === 'inactivity') {
      setAuthError('Session expired due to inactivity. Please login again.');
    }
    setActiveTab(TabType.HOME);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
  }, []);

  // Inactivity Detection Logic
  const resetInactivityTimer = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (auth.isAuthenticated) {
      timeoutRef.current = setTimeout(() => {
        handleLogout('inactivity');
      }, INACTIVITY_TIMEOUT);
    }
  }, [auth.isAuthenticated, handleLogout]);

  useEffect(() => {
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart'];

    if (auth.isAuthenticated) {
      resetInactivityTimer();
      events.forEach(event => window.addEventListener(event, resetInactivityTimer));
    }

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      events.forEach(event => window.removeEventListener(event, resetInactivityTimer));
    };
  }, [auth.isAuthenticated, resetInactivityTimer]);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_session_v5');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: JSON.parse(savedSession), loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    const cloudLogo = await cloudApi.fetchLogo();
    if (cloudLogo) setCompanyLogo(cloudLogo);

    const employerList = await cloudApi.fetchEmployers();
    setEmployers(employerList);
    if (employerList.length > 0) setSelectedEmployer(employerList[0]);
  };

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: cloudApi.isCloudActive() ? 'online' : 'offline' });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  useEffect(() => {
    if (auth.isAuthenticated) loadFromCloud();
  }, [auth.isAuthenticated]);

  const filteredEmployees = useMemo(() => employees.filter(e => e.principalEmployer === selectedEmployer), [employees, selectedEmployer]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setCompanyLogo(base64);
        await cloudApi.saveLogo(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleLogin = async (username: string, password: string) => {
    const user = await cloudApi.authenticate(username, password);
    if (user) {
      localStorage.setItem('payslip_session_v5', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid credentials.');
    }
  };

  const isAdmin = auth.user?.role === Role.ADMIN;
  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} logo={companyLogo} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex flex-col gap-6 mb-10">
          <div className="relative group w-20 h-20 self-center">
            <div className="w-20 h-20 bg-gray-50 rounded-2xl flex items-center justify-center overflow-hidden border border-gray-100 shadow-sm transition-all group-hover:scale-[1.02]">
              {companyLogo ? (
                <img src={companyLogo} alt="Logo" className="w-full h-full object-contain p-2" />
              ) : (
                <Building2 size={24} className="text-gray-300" />
              )}
            </div>
            {isAdmin && (
              <button onClick={() => logoInputRef.current?.click()} className="absolute -bottom-1 -right-1 p-2 bg-indigo-600 text-white rounded-xl shadow-lg border-2 border-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-700">
                <Camera size={10} />
              </button>
            )}
            <input ref={logoInputRef} type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
          </div>
          <div className="text-center">
            <h1 className="text-lg font-black text-gray-900">Maruthi HR</h1>
            <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">Consultancy Portal</p>
          </div>
        </div>

        <div className="mb-8 space-y-3">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Briefcase size={12} className="text-indigo-400" /> Client</label>
          <div className="flex gap-2">
            <select value={selectedEmployer} onChange={(e) => setSelectedEmployer(e.target.value)} className="flex-1 bg-indigo-50/50 border border-indigo-100 rounded-2xl px-4 py-3 text-xs font-black text-indigo-900 outline-none">
              {employers.map(e => <option key={e} value={e}>{e}</option>)}
            </select>
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><LayoutDashboard size={20} /><span>Payroll Audit</span></button>
        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><FileText size={20} /><span>Payslips</span></button>
        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><PieChart size={20} /><span>Insights</span></button>
        {isAdmin && <button onClick={() => setActiveTab(TabType.USERS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.USERS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><UsersIcon size={20} /><span>Users</span></button>}

        <div className="mt-auto pt-8 border-t border-gray-50 space-y-4">
          <div className={`px-4 py-4 rounded-2xl border flex items-start gap-3 transition-colors ${sync.status === 'online' ? 'bg-emerald-50/50 border-emerald-100' : 'bg-amber-50/50 border-amber-100'}`}>
             {sync.status === 'online' ? <Cloud className="text-emerald-600" size={20} /> : <CloudOff className="text-amber-600" size={20} />}
             <div className="flex flex-col">
                <p className={`text-[9px] font-black uppercase tracking-widest ${sync.status === 'online' ? 'text-emerald-900' : 'text-amber-900'}`}>{sync.status === 'online' ? 'Cloud Connected' : 'Local Mode'}</p>
                <p className="text-[8px] font-bold text-gray-500">Global Sync Active</p>
             </div>
          </div>
          <button onClick={() => handleLogout()} className="w-full flex items-center justify-center gap-2 py-4 text-[10px] font-black text-gray-400 hover:text-red-500 transition-all uppercase tracking-widest"><LogOut size={16} /> Logout</button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={filteredEmployees} onUploadTrigger={isAdmin ? () => fileInputRef.current?.click() : undefined} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={filteredEmployees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={filteredEmployees} />}
          {activeTab === TabType.USERS && isAdmin && <UserManagementTab employees={filteredEmployees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={() => {}} className="hidden" />
      </main>
    </div>
  );
};

