  const handleLogin = async (username: string, password: string) => {
    const user = await cloudApi.authenticate(username, password);
    if (user) {
      localStorage.setItem('payslip_session_v5', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid credentials.');
    }
  };

  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault();
    setResetError(null);
    if (!auth.user) return;
    if (resetOldPass !== auth.user.password) {
      setResetError('Current password is incorrect.');
      return;
    }
    if (resetNewPass !== resetConfirmPass) {
      setResetError('New passwords do not match.');
      return;
    }
    if (resetNewPass.length < 6) {
      setResetError('Password must be at least 6 characters.');
      return;
    }

    setIsResetting(true);
    try {
      await cloudApi.updateUserPassword(auth.user.username, resetNewPass);
      // Update local session state
      const updatedUser = { ...auth.user, password: resetNewPass };
      localStorage.setItem('payslip_session_v5', JSON.stringify(updatedUser));
      setAuth(prev => ({ ...prev, user: updatedUser }));
      setResetSuccess(true);
      setTimeout(() => {
        setIsResetModalOpen(false);
        setResetSuccess(false);
        setResetOldPass('');
        setResetNewPass('');
        setResetConfirmPass('');
      }, 2000);
    } catch (err) {
      setResetError('Failed to update password. Try again.');
    } finally {
      setIsResetting(false);
    }
  };

