  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax', 'professional tax'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf', 'labour welfare fund'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen', 'food deduction'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'advance'] },
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [companyLogo, setCompanyLogo] = useState<string>(DEFAULT_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'offline' });
  const [employers, setEmployers] = useState<string[]>([]);
  const [selectedEmployer, setSelectedEmployer] = useState<string>('');

  // Mapping Modal State
  const [isMappingModalOpen, setIsMappingModalOpen] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Record<string, string>>({});

  // Security Modal State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [resetOldPass, setResetOldPass] = useState('');
  const [resetNewPass, setResetNewPass] = useState('');
  const [resetConfirmPass, setResetConfirmPass] = useState('');
  const [resetError, setResetError] = useState<string | null>(null);
  const [resetSuccess, setResetSuccess] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const isAdmin = auth.user?.role === Role.ADMIN;

  const parseCleanNumber = (val: any): number => {
    if (val === undefined || val === null || val === '-' || String(val).trim() === '-') return 0;
    const clean = String(val).replace(/[^0-9.]/g, '');
    return parseFloat(clean) || 0;
  };

  const handleLogout = useCallback((reason?: string) => {
    localStorage.removeItem('payslip_session_v5');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    if (reason === 'inactivity') setAuthError('Session expired due to inactivity.');
    setActiveTab(TabType.HOME);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
  }, []);

  const resetInactivityTimer = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (auth.isAuthenticated) {
      timeoutRef.current = setTimeout(() => handleLogout('inactivity'), INACTIVITY_TIMEOUT);
    }
  }, [auth.isAuthenticated, handleLogout]);

  useEffect(() => {
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'visibilitychange'];
    if (auth.isAuthenticated) {
      resetInactivityTimer();
      events.forEach(e => window.addEventListener(e, resetInactivityTimer));
    }
    return () => events.forEach(e => window.removeEventListener(e, resetInactivityTimer));
  }, [auth.isAuthenticated, resetInactivityTimer]);

  useEffect(() => {
    const saved = localStorage.getItem('payslip_session_v5');
    if (saved) setAuth({ isAuthenticated: true, user: JSON.parse(saved), loading: false });
    else setAuth(prev => ({ ...prev, loading: false }));
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    const logo = await cloudApi.fetchLogo();
    if (logo) setCompanyLogo(logo);
    const employerList = await cloudApi.fetchEmployers();
    setEmployers(employerList);
    if (employerList.length > 0) setSelectedEmployer(employerList[0]);
  };

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: cloudApi.isCloudActive() ? 'online' : 'offline' });
    } catch {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  useEffect(() => { if (auth.isAuthenticated) loadFromCloud(); }, [auth.isAuthenticated]);

  const filteredEmployees = useMemo(() => employees.filter(e => e.principalEmployer === selectedEmployer), [employees, selectedEmployer]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base = reader.result as string;
        setCompanyLogo(base);
        await cloudApi.saveLogo(base);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isAdmin) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const headers = Object.keys(results.data[0] || {});
        setCsvHeaders(headers);
        setCsvData(results.data);

        // Auto-mapping logic
        const initialMapping: Record<string, string> = {};
        const usedCsvCols = new Set<string>();

        REQUIRED_FIELDS.forEach(field => {
          const match = headers.find(h => {
            const normalizedH = h.toLowerCase().trim();
            return !usedCsvCols.has(h) && (normalizedH === field.key.toLowerCase() || field.aliases.some(a => normalizedH.includes(a)));
          });
          if (match) {
            initialMapping[field.key] = match;
            usedCsvCols.add(match);
          }
        });

        setMapping(initialMapping);
        setIsMappingModalOpen(true);
        e.target.value = '';
      }
    });
  };

  const finalizeImport = async () => {
    const monthStr = new Date().toLocaleString('default', { month: 'short' });
    const yearNum = new Date().getFullYear();
    const dateStr = new Date().toLocaleDateString();

    const processed: EmployeeSalaryData[] = csvData.map((row, idx) => {
      const data: any = {};
      REQUIRED_FIELDS.forEach(f => {
        const csvVal = row[mapping[f.key]];
        data[f.key] = ['id', 'name'].includes(f.key) ? (csvVal || `AUTO-${idx}`) : parseCleanNumber(csvVal);
      });

      const gross = data.basicDA + data.bonus + data.otAmount + data.arrears + data.attendanceBonus;
      const deductions = data.esiDeduction + data.pfDeduction + data.ptDeduction + data.lwfDeduction + data.otherDeduction + data.canteenDeduction;

      return {
        ...data,
        grossEarnings: gross,
        totalDeductions: deductions,
        netSalary: gross - deductions,
        month: monthStr,
        year: yearNum,
        displayDate: dateStr,
        principalEmployer: selectedEmployer
      } as EmployeeSalaryData;
    });

    const combined = [...employees, ...processed];
    setEmployees(combined);
    await cloudApi.saveEmployees(combined);
    setIsMappingModalOpen(false);
    alert(`Imported ${processed.length} records for ${selectedEmployer}`);
  };

  const handleLogin = async (u: string, p: string) => {
    const user = await cloudApi.authenticate(u, p);
    if (user) {
      localStorage.setItem('payslip_session_v5', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else setAuthError('Invalid credentials.');
  };

  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault();
    setResetError(null);
    if (!auth.user) return;
    if (resetOldPass !== auth.user.password) return setResetError('Incorrect current password.');
    if (resetNewPass !== resetConfirmPass) return setResetError('Passwords mismatch.');
    if (resetNewPass.length < 6) return setResetError('Too short.');

    setIsResetting(true);
    try {
      await cloudApi.updateUserPassword(auth.user.username, resetNewPass);
      const updated = { ...auth.user, password: resetNewPass };
      localStorage.setItem('payslip_session_v5', JSON.stringify(updated));
      setAuth(prev => ({ ...prev, user: updated }));
      setResetSuccess(true);
      setTimeout(() => {
        setIsResetModalOpen(false);
        setResetSuccess(false);
        setResetOldPass(''); setResetNewPass(''); setResetConfirmPass('');
      }, 2000);
    } catch { setResetError('Update failed.'); } finally { setIsResetting(false); }
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} logo={companyLogo} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex flex-col gap-6 mb-10">
          <div className="relative group w-20 h-20 self-center">
            <div className="w-20 h-20 bg-gray-50 rounded-2xl flex items-center justify-center overflow-hidden border border-gray-100 shadow-sm">
              <img src={companyLogo} alt="Logo" className="w-full h-full object-contain p-2" />
            </div>
            {isAdmin && (
              <button onClick={() => logoInputRef.current?.click()} className="absolute -bottom-1 -right-1 p-2 bg-indigo-600 text-white rounded-xl shadow-lg border-2 border-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-700">
                <Camera size={10} />
              </button>
            )}
            <input ref={logoInputRef} type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
          </div>
          <div className="text-center">
            <h1 className="text-lg font-black text-gray-900">Maruthi HR</h1>
            <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">Management Portal</p>
          </div>
        </div>

        <div className="mb-8 space-y-3">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Briefcase size={12} className="text-indigo-400" /> Client Database</label>
          <select value={selectedEmployer} onChange={(e) => setSelectedEmployer(e.target.value)} className="w-full bg-indigo-50/50 border border-indigo-100 rounded-2xl px-4 py-3 text-xs font-black text-indigo-900 outline-none">
            {employers.map(e => <option key={e} value={e}>{e}</option>)}
          </select>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><LayoutDashboard size={20} /><span>Payroll Audit</span></button>
        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><FileText size={20} /><span>Payslips</span></button>
        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><PieChart size={20} /><span>Insights</span></button>

        {isAdmin && (
          <button onClick={() => setActiveTab(TabType.USERS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.USERS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><UsersIcon size={20} /><span>Staff Mgmt</span></button>
        )}

        <div className="mt-auto pt-8 border-t border-gray-50 space-y-4">
          <div className="space-y-2">
            <button onClick={() => setIsResetModalOpen(true)} className="w-full flex items-center gap-4 px-5 py-3 rounded-2xl text-[10px] font-black text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-all uppercase tracking-widest shadow-sm"><ShieldEllipsis size={16} /> Security Settings</button>
            <button onClick={() => handleLogout()} className="w-full flex items-center gap-4 px-5 py-3 rounded-2xl text-[10px] font-black text-gray-400 hover:text-red-500 hover:bg-red-50 transition-all uppercase tracking-widest"><LogOut size={16} /> Logout</button>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={filteredEmployees} onUploadTrigger={isAdmin ? () => fileInputRef.current?.click() : undefined} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={filteredEmployees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={filteredEmployees} />}
          {activeTab === TabType.USERS && isAdmin && <UserManagementTab employees={filteredEmployees} />}
        </div>
        {isAdmin && <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />}
      </main>

      {/* Column Mapping Modal */}
      {isMappingModalOpen && (
        <div className="fixed inset-0 z-[300] bg-gray-900/60 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-[40px] shadow-3xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <Settings2 size={24} />
                <div>
                  <h3 className="text-xl font-black">Verify Ledger Columns</h3>
                  <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">Mapping CSV headers to Payroll fields</p>
                </div>
              </div>
              <button onClick={() => setIsMappingModalOpen(false)} className="hover:bg-white/10 p-2 rounded-full"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-y-auto space-y-4 bg-gray-50/30">
              <div className="grid grid-cols-2 gap-4 text-[10px] font-black text-gray-400 uppercase tracking-widest px-4">
                <span>System Field</span>
                <span>Your CSV Column</span>
              </div>
              {REQUIRED_FIELDS.map((field) => {
                const currentSelection = mapping[field.key];
                const availableCsvHeaders = csvHeaders.filter(h => h === currentSelection || !Object.values(mapping).includes(h));

                return (
                  <div key={field.key} className="flex items-center gap-4 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm group hover:border-indigo-200 transition-all">
                    <div className="flex-1 flex items-center justify-between">
                      <span className="text-sm font-black text-gray-700">{field.label}</span>
                      <ChevronRight size={14} className="text-gray-300 group-hover:text-indigo-400" />
                    </div>
                    <select 
                      value={currentSelection || ''} 
                      onChange={(e) => setMapping(prev => ({ ...prev, [field.key]: e.target.value }))}
                      className={`flex-1 bg-gray-50 border rounded-xl px-4 py-2.5 text-xs font-bold outline-none appearance-none cursor-pointer transition-all ${currentSelection ? 'border-indigo-200 text-indigo-700 bg-indigo-50/30' : 'border-gray-100 text-gray-400'}`}
                    >
                      <option value="">-- Select Column --</option>
                      {availableCsvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                );
              })}
            </div>

            <div className="p-8 border-t border-gray-100 bg-white shrink-0 flex justify-end gap-4">
              <button onClick={() => setIsMappingModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase text-gray-400 hover:text-gray-600">Cancel</button>
              <button 
                onClick={finalizeImport} 
                disabled={Object.keys(mapping).length < REQUIRED_FIELDS.length}
                className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-3 transition-all active:scale-[0.98]"
              >
                <span>Process Import</span>
                <CheckCircle2 size={18} />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Security Modal */}
      {isResetModalOpen && (
        <div className="fixed inset-0 z-[200] bg-gray-900/60 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black flex items-center gap-3"><ShieldEllipsis size={24}/> Account Security</h3>
              <button onClick={() => setIsResetModalOpen(false)} className="hover:bg-white/10 p-2 rounded-full transition-colors"><X size={24}/></button>
            </div>

            {resetSuccess ? (
              <div className="p-10 flex flex-col items-center text-center space-y-4">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-[30px] flex items-center justify-center shadow-inner animate-bounce"><CheckCircle2 size={40} /></div>
                <h4 className="text-xl font-black text-gray-900">Password Updated</h4>
                <p className="text-sm text-gray-500 font-medium">Your credentials have been successfully reset.</p>
              </div>
            ) : (
              <form onSubmit={handlePasswordReset} className="p-8 space-y-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Current Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetOldPass} onChange={e => setResetOldPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="••••••••" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">New Password</label>
                  <div className="relative">
                    <Key className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetNewPass} onChange={e => setResetNewPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Min 6 characters" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Confirm New Password</label>
                  <div className="relative">
                    <UserCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetConfirmPass} onChange={e => setResetConfirmPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Repeat new password" />
                  </div>
                </div>
                {resetError && <div className="bg-red-50 border border-red-100 p-3 rounded-xl flex items-center gap-2 text-red-600 text-[10px] font-bold uppercase animate-in slide-in-from-top-1"><AlertCircle size={14} />{resetError}</div>}
                <button type="submit" disabled={isResetting} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2">
                  {isResetting ? <Loader2 className="animate-spin" size={18} /> : <><span>Save Security Key</span><ArrowRight size={16}/></>}
                </button>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Users as UsersIcon,
  Upload, 
  AlertCircle,
  X,
  Cloud,
  CloudOff,
  RefreshCcw,
  LogOut,
  CheckCircle2,
  Building2,
  Camera,
  Lock,
  Briefcase,
  UserCheck,
  ShieldEllipsis,
  ArrowRight,
  Loader2,
  Key,
  ChevronRight,
  Settings2,
  RotateCcw
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, AuthState, SyncStatus, Role, User } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import UserManagementTab from './components/UserManagementTab';
import Login from './components/Login';

const DEFAULT_LOGO = "data:image/png;base64,";

const INACTIVITY_TIMEOUT = 15 * 60 * 1000; 

const IGNORE_VAL = "___IGNORE___";

const SCHEMA_FIELDS = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code', 'sl no', 'staff id'] },
  { key: 'name', label: 'Full Name', aliases: ['name', 'employee name', 'staff name', 'worker name', 'name of employee'] },
  { key: 'esiNo', label: 'ESI Number', aliases: ['esi', 'esi no', 'esi number', 'esi registration'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan', 'uan no', 'pf uan', 'uan number', 'pf number'] },
  { key: 'totalDays', label: 'Total Days', aliases: ['total days', 'days in month', 'month days'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked days', 'attendance', 'present days'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot hrs', 'overtime hours', 'ot hours', 'ot'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary', 'target gross', 'salary'] },
  { key: 'basicDA', label: 'Basic & DA', aliases: ['basic', 'basic & da', 'da', 'monthly basic'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus', 'statutory bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot pay', 'overtime amount', 'ot amount', 'ot earnings'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears', 'previous due', 'adjustments'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['att bonus', 'attendance bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction', 'esi contribution', 'employee esi'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'pf contribution', 'epf', 'employee pf'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax', 'professional tax', 'p.t'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf', 'labour welfare fund'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen', 'food deduction', 'mess'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'advance', 'misc deduction'] },
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [companyLogo, setCompanyLogo] = useState<string>(DEFAULT_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'offline' });
  const [employers, setEmployers] = useState<string[]>([]);
  const [selectedEmployer, setSelectedEmployer] = useState<string>('');

  // Mapping Modal State
  const [isMappingModalOpen, setIsMappingModalOpen] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [csvData, setCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Record<string, string>>({});

  // Security Modal State
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [resetOldPass, setResetOldPass] = useState('');
  const [resetNewPass, setResetNewPass] = useState('');
  const [resetConfirmPass, setResetConfirmPass] = useState('');
  const [resetError, setResetError] = useState<string | null>(null);
  const [resetSuccess, setResetSuccess] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const isAdmin = auth.user?.role === Role.ADMIN;

  // FIXED: Robust Numeric Parser for currency-formatted strings and dash values
  const parseCleanNumber = (val: any): number => {
    if (val === undefined || val === null) return 0;
    const str = String(val).trim();
    if (str === '-' || str === '' || str === '0') return 0;
    // Remove commas, spaces, and any non-numeric chars except the decimal point
    const clean = str.replace(/,/g, '').replace(/\s/g, '');
    const num = parseFloat(clean);
    return isNaN(num) ? 0 : num;
  };

  const handleLogout = useCallback((reason?: string) => {
    localStorage.removeItem('payslip_session_v5');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    if (reason === 'inactivity') setAuthError('Session expired due to inactivity.');
    setActiveTab(TabType.HOME);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
  }, []);

  const resetInactivityTimer = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (auth.isAuthenticated) {
      timeoutRef.current = setTimeout(() => handleLogout('inactivity'), INACTIVITY_TIMEOUT);
    }
  }, [auth.isAuthenticated, handleLogout]);

  useEffect(() => {
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'visibilitychange'];
    if (auth.isAuthenticated) {
      resetInactivityTimer();
      events.forEach(e => window.addEventListener(e, resetInactivityTimer));
    }
    return () => events.forEach(e => window.removeEventListener(e, resetInactivityTimer));
  }, [auth.isAuthenticated, resetInactivityTimer]);

  useEffect(() => {
    const saved = localStorage.getItem('payslip_session_v5');
    if (saved) setAuth({ isAuthenticated: true, user: JSON.parse(saved), loading: false });
    else setAuth(prev => ({ ...prev, loading: false }));
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    const logo = await cloudApi.fetchLogo();
    if (logo) setCompanyLogo(logo);
    const employerList = await cloudApi.fetchEmployers();
    setEmployers(employerList);
    if (employerList.length > 0) setSelectedEmployer(employerList[0]);
  };

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ lastSynced: new Date(), isSyncing: false, status: cloudApi.isCloudActive() ? 'online' : 'offline' });
    } catch {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  useEffect(() => { if (auth.isAuthenticated) loadFromCloud(); }, [auth.isAuthenticated]);

  const filteredEmployees = useMemo(() => employees.filter(e => e.principalEmployer === selectedEmployer), [employees, selectedEmployer]);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base = reader.result as string;
        setCompanyLogo(base);
        await cloudApi.saveLogo(base);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !isAdmin) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const headers = Object.keys(results.data[0] || {}).map(h => h.trim());
        setCsvHeaders(headers);
        setCsvData(results.data);

        // RESTORED: Auto-mapping logic with normalization
        const initialMapping: Record<string, string> = {};
        const usedCsvCols = new Set<string>();

        SCHEMA_FIELDS.forEach(field => {
          const match = headers.find(h => {
            const normalizedH = h.toLowerCase();
            return !usedCsvCols.has(h) && (normalizedH === field.key.toLowerCase() || field.aliases.some(a => normalizedH.includes(a)));
          });
          if (match) {
            initialMapping[field.key] = match;
            usedCsvCols.add(match);
          }
        });

        setMapping(initialMapping);
        setIsMappingModalOpen(true);
        e.target.value = '';
      }
    });
  };

  const finalizeImport = async () => {
    const monthStr = new Date().toLocaleString('default', { month: 'short' });
    const yearNum = new Date().getFullYear();
    const dateStr = new Date().toLocaleDateString();

    const processed: EmployeeSalaryData[] = csvData.map((row, idx) => {
      const data: any = {};
      SCHEMA_FIELDS.forEach(f => {
        const csvCol = mapping[f.key];
        const rawValue = csvCol && csvCol !== IGNORE_VAL ? row[csvCol] : null;

        if (['id', 'name'].includes(f.key)) {
          data[f.key] = rawValue ? String(rawValue).trim() : (f.key === 'id' ? `AUTO-${idx}` : 'Unknown');
        } else if (['esiNo', 'uanNo'].includes(f.key)) {
          data[f.key] = rawValue ? String(rawValue).trim() : 'N/A';
        } else {
          data[f.key] = parseCleanNumber(rawValue);
        }
      });

      // Recalculate Totals based on mapped earnings/deductions
      const gross = data.basicDA + data.bonus + data.otAmount + data.arrears + data.attendanceBonus;
      const deductions = data.esiDeduction + data.pfDeduction + data.ptDeduction + data.lwfDeduction + data.otherDeduction + data.canteenDeduction;

      return {
        ...data,
        grossEarnings: gross,
        totalDeductions: deductions,
        netSalary: gross - deductions,
        month: monthStr,
        year: yearNum,
        displayDate: dateStr,
        principalEmployer: selectedEmployer
      } as EmployeeSalaryData;
    });

    const combined = [...employees, ...processed];
    setEmployees(combined);
    await cloudApi.saveEmployees(combined);
    setIsMappingModalOpen(false);
    alert(`Imported ${processed.length} records for ${selectedEmployer}`);
  };

  const handleLogin = async (u: string, p: string) => {
    const user = await cloudApi.authenticate(u, p);
    if (user) {
      localStorage.setItem('payslip_session_v5', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else setAuthError('Invalid credentials.');
  };

  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault();
    setResetError(null);
    if (!auth.user) return;
    if (resetOldPass !== auth.user.password) return setResetError('Incorrect current password.');
    if (resetNewPass !== resetConfirmPass) return setResetError('Passwords mismatch.');
    if (resetNewPass.length < 6) return setResetError('Too short.');

    setIsResetting(true);
    try {
      await cloudApi.updateUserPassword(auth.user.username, resetNewPass);
      const updated = { ...auth.user, password: resetNewPass };
      localStorage.setItem('payslip_session_v5', JSON.stringify(updated));
      setAuth(prev => ({ ...prev, user: updated }));
      setResetSuccess(true);
      setTimeout(() => {
        setIsResetModalOpen(false);
        setResetSuccess(false);
        setResetOldPass(''); setResetNewPass(''); setResetConfirmPass('');
      }, 2000);
    } catch { setResetError('Update failed.'); } finally { setIsResetting(false); }
  };

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} logo={companyLogo} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">
        <div className="flex flex-col gap-6 mb-10">
          <div className="relative group w-20 h-20 self-center">
            <div className="w-20 h-20 bg-gray-50 rounded-2xl flex items-center justify-center overflow-hidden border border-gray-100 shadow-sm">
              <img src={companyLogo} alt="Logo" className="w-full h-full object-contain p-2" />
            </div>
            {isAdmin && (
              <button onClick={() => logoInputRef.current?.click()} className="absolute -bottom-1 -right-1 p-2 bg-indigo-600 text-white rounded-xl shadow-lg border-2 border-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-700">
                <Camera size={10} />
              </button>
            )}
            <input ref={logoInputRef} type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
          </div>
          <div className="text-center">
            <h1 className="text-lg font-black text-gray-900">Maruthi HR</h1>
            <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">Management Portal</p>
          </div>
        </div>

        <div className="mb-8 space-y-3">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Briefcase size={12} className="text-indigo-400" /> Client Database</label>
          <select value={selectedEmployer} onChange={(e) => setSelectedEmployer(e.target.value)} className="w-full bg-indigo-50/50 border border-indigo-100 rounded-2xl px-4 py-3 text-xs font-black text-indigo-900 outline-none">
            {employers.map(e => <option key={e} value={e}>{e}</option>)}
          </select>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><LayoutDashboard size={20} /><span>Payroll Audit</span></button>
        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><FileText size={20} /><span>Payslips</span></button>
        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><PieChart size={20} /><span>Insights</span></button>

        {isAdmin && (
          <button onClick={() => setActiveTab(TabType.USERS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.USERS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}><UsersIcon size={20} /><span>Staff Mgmt</span></button>
        )}

        <div className="mt-auto pt-8 border-t border-gray-50 space-y-4">
          <div className="space-y-2">
            <button onClick={() => setIsResetModalOpen(true)} className="w-full flex items-center gap-4 px-5 py-3 rounded-2xl text-[10px] font-black text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-all uppercase tracking-widest shadow-sm"><ShieldEllipsis size={16} /> Security Settings</button>
            <button onClick={() => handleLogout()} className="w-full flex items-center gap-4 px-5 py-3 rounded-2xl text-[10px] font-black text-gray-400 hover:text-red-500 hover:bg-red-50 transition-all uppercase tracking-widest"><LogOut size={16} /> Logout</button>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={filteredEmployees} onUploadTrigger={isAdmin ? () => fileInputRef.current?.click() : undefined} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={filteredEmployees} companyLogo={companyLogo} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={filteredEmployees} />}
          {activeTab === TabType.USERS && isAdmin && <UserManagementTab employees={filteredEmployees} />}
        </div>
        {isAdmin && <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />}
      </main>

      {/* RESTORED: Robust Column Mapping Modal */}
      {isMappingModalOpen && (
        <div className="fixed inset-0 z-[300] bg-gray-900/60 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-[40px] shadow-3xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <Settings2 size={24} />
                <div>
                  <h3 className="text-xl font-black">Ledger Column Mapping</h3>
                  <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">Link CSV headers to system payroll fields</p>
                </div>
              </div>
              <button onClick={() => setIsMappingModalOpen(false)} className="hover:bg-white/10 p-2 rounded-full"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-y-auto space-y-4 bg-gray-50/30">
              <div className="grid grid-cols-2 gap-4 text-[10px] font-black text-gray-400 uppercase tracking-widest px-4">
                <span>System Payroll Field</span>
                <span>Select Column from CSV</span>
              </div>
              {SCHEMA_FIELDS.map((field) => {
                const currentSelection = mapping[field.key];
                // Unique Selection Logic: Only show unmapped headers or the currently selected one
                const availableCsvHeaders = csvHeaders.filter(h => h === currentSelection || !Object.values(mapping).includes(h));

                return (
                  <div key={field.key} className="flex items-center gap-4 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm group hover:border-indigo-200 transition-all">
                    <div className="flex-1 flex items-center justify-between">
                      <span className="text-sm font-black text-gray-700">{field.label}</span>
                      <ChevronRight size={14} className="text-gray-300 group-hover:text-indigo-400" />
                    </div>
                    <select 
                      value={currentSelection || ''} 
                      onChange={(e) => setMapping(prev => ({ ...prev, [field.key]: e.target.value }))}
                      className={`flex-1 bg-gray-50 border rounded-xl px-4 py-2.5 text-xs font-bold outline-none appearance-none cursor-pointer transition-all ${currentSelection && currentSelection !== IGNORE_VAL ? 'border-indigo-200 text-indigo-700 bg-indigo-50/30' : 'border-gray-100 text-gray-400'}`}
                    >
                      <option value="">-- Choose Header --</option>
                      <option value={IGNORE_VAL} className="font-bold text-red-500 italic">Ignore / Not in CSV</option>
                      {availableCsvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                );
              })}
            </div>

            <div className="p-8 border-t border-gray-100 bg-white shrink-0 flex justify-between items-center">
              <button onClick={() => setMapping({})} className="flex items-center gap-2 px-6 py-4 text-[10px] font-black uppercase text-gray-400 hover:text-indigo-600 transition-colors">
                <RotateCcw size={16} /> Reset Mapping
              </button>
              <div className="flex gap-4">
                <button onClick={() => setIsMappingModalOpen(false)} className="px-8 py-4 text-[10px] font-black uppercase text-gray-400 hover:text-gray-600">Cancel</button>
                <button 
                  onClick={finalizeImport} 
                  disabled={!mapping.id || !mapping.name}
                  className="px-10 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-3 transition-all active:scale-[0.98]"
                >
                  <span>Verify & Import</span>
                  <CheckCircle2 size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Security Settings Modal (Available for all) */}
      {isResetModalOpen && (
        <div className="fixed inset-0 z-[200] bg-gray-900/60 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black flex items-center gap-3"><ShieldEllipsis size={24}/> Security Settings</h3>
              <button onClick={() => setIsResetModalOpen(false)} className="hover:bg-white/10 p-2 rounded-full transition-colors"><X size={24}/></button>
            </div>

            {resetSuccess ? (
              <div className="p-10 flex flex-col items-center text-center space-y-4">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-[30px] flex items-center justify-center shadow-inner animate-bounce"><CheckCircle2 size={40} /></div>
                <h4 className="text-xl font-black text-gray-900">Security Key Updated</h4>
                <p className="text-sm text-gray-500 font-medium">Your credentials have been updated successfully.</p>
              </div>
            ) : (
              <form onSubmit={handlePasswordReset} className="p-8 space-y-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Current Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetOldPass} onChange={e => setResetOldPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="••••••••" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">New Password</label>
                  <div className="relative">
                    <Key className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetNewPass} onChange={e => setResetNewPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Min 6 characters" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Confirm Password</label>
                  <div className="relative">
                    <UserCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input required type="password" value={resetConfirmPass} onChange={e => setResetConfirmPass(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl pl-12 pr-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Repeat new password" />
                  </div>
                </div>
                {resetError && <div className="bg-red-50 border border-red-100 p-3 rounded-xl flex items-center gap-2 text-red-600 text-[10px] font-bold uppercase animate-in slide-in-from-top-1"><AlertCircle size={14} />{resetError}</div>}
                <button type="submit" disabled={isResetting} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-2">
                  {isResetting ? <Loader2 className="animate-spin" size={18} /> : <><span>Update Credentials</span><ArrowRight size={16}/></>}
                </button>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

// Removed missing 'vite/client' type reference that was causing a build error.
import { createClient } from '@supabase/supabase-js';
import { EmployeeSalaryData, User, Role } from '../types';

const getEnvVar = (key: string): string => {
  try {
    const metaEnv = (import.meta as any).env;
    if (metaEnv && metaEnv[key]) return metaEnv[key];
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key] as string;
    }
  } catch (e) {}
  return '';
};

const supabaseUrl = getEnvVar('VITE_SUPABASE_URL');
const supabaseKey = getEnvVar('VITE_SUPABASE_ANON_KEY');
const supabase = (supabaseUrl && supabaseKey) ? createClient(supabaseUrl, supabaseKey) : null;

const DB_NAME = 'MaruthiHR_LocalCache_V5';
const DB_VERSION = 1;
const STORES = {
  EMPLOYEES: 'employees',
  USERS: 'users',
  EMPLOYERS: 'employers'
};

const getIDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      Object.values(STORES).forEach(store => {
        if (!db.objectStoreNames.contains(store)) db.createObjectStore(store);
      });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const localOp = async <T>(storeName: string, mode: IDBTransactionMode, operation: (store: IDBObjectStore) => IDBRequest): Promise<T> => {
  const db = await getIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);
    const request = operation(store);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const cloudApi = {
  isCloudActive(): boolean {
    return !!supabase;
  },

  async fetchLogo(): Promise<string | null> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_logo')
          .single();
        if (data?.data) {
          localStorage.setItem('company_logo', data.data);
          return data.data;
        }
      } catch (e) {}
    }
    return localStorage.getItem('company_logo');
  },

  async saveLogo(logoBase64: string): Promise<void> {
    localStorage.setItem('company_logo', logoBase64);
    if (supabase) {
      await supabase
        .from('payroll_records')
        .upsert({ id: 'global_logo', data: logoBase64, updated_at: new Date().toISOString() });
    }
  },

  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    if (supabase) {
      try {
        const { data, error } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_roster')
          .single();

        if (data?.data) {
          await this.saveLocalEmployees(data.data);
          return data.data;
        }
      } catch (err) {
        console.warn("Cloud fetch failed, falling back to local cache", err);
      }
    }

    try {
      const data = await localOp<EmployeeSalaryData[]>(STORES.EMPLOYEES, 'readonly', (s) => s.get('all_records'));
      return data || [];
    } catch {
      return [];
    }
  },

  async saveLocalEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await localOp(STORES.EMPLOYEES, 'readwrite', (s) => s.put(employees, 'all_records'));
  },

  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await this.saveLocalEmployees(employees);

    if (supabase) {
      const { error } = await supabase
        .from('payroll_records')
        .upsert({ id: 'global_roster', data: employees, updated_at: new Date().toISOString() });

      if (error) throw new Error("Cloud sync failed: " + error.message);
    }
  },

  async fetchUsers(): Promise<User[]> {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'maruthihrsolution25@gmail.com'
    };

    if (supabase) {
      try {
        const { data } = await supabase.from('payroll_records').select('data').eq('id', 'global_users').single();
        if (data?.data) return data.data;
      } catch (e) {}
    }

    const localData = await localOp<User[]>(STORES.USERS, 'readonly', (s) => s.get('all_users'));
    if (!localData) {
      await this.saveUsers([defaultAdmin]);
      return [defaultAdmin];
    }
    return localData;
  },

  async saveUsers(users: User[]): Promise<void> {
    await localOp(STORES.USERS, 'readwrite', (s) => s.put(users, 'all_users'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_users', data: users });
    }
  },

  async fetchEmployers(): Promise<string[]> {
    const defaults = ['HEALTHY FOOD PRODUCTS'];

    if (supabase) {
      try {
        const { data } = await supabase.from('payroll_records').select('data').eq('id', 'global_employers').single();
        if (data?.data) return data.data;
      } catch (e) {}
    }

    const localData = await localOp<string[]>(STORES.EMPLOYERS, 'readonly', (s) => s.get('all_employers'));
    if (!localData) {
      await this.saveEmployers(defaults);
      return defaults;
    }
    return localData;
  },

  async saveEmployers(employers: string[]): Promise<void> {
    await localOp(STORES.EMPLOYERS, 'readwrite', (s) => s.put(employers, 'all_employers'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_employers', data: employers });
    }
  },

  async authenticate(username: string, password: string): Promise<User | null> {
    const users = await this.fetchUsers();
    return users.find(u => u.username === username && u.password === password) || null;
  },

  async exportFullDatabase(): Promise<string> {
    const data = {
      employees: await this.fetchEmployees(),
      users: await this.fetchUsers(),
      employers: await this.fetchEmployers(),
      timestamp: new Date().toISOString(),
      provider: supabase ? 'Supabase Cloud' : 'IndexedDB Local'
    };
    return JSON.stringify(data, null, 2);
  }
};

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  FileText, 
  PieChart, 
  Users as UsersIcon,
  Upload, 
  AlertCircle,
  X,
  Image as ImageIcon,
  Cloud,
  CloudOff,
  RefreshCcw,
  LogOut,
  CheckCircle2,
  ShieldCheck,
  Building2,
  Camera,
  ShieldAlert,
  Lock,
  Plus,
  Briefcase,
  Database,
  Download,
  Info,
  Server
} from 'lucide-react';
import Papa from 'papaparse';
import { EmployeeSalaryData, TabType, ColumnMapping, AuthState, SyncStatus, Role, User } from './types';
import { cloudApi } from './services/api';
import HomeTab from './components/HomeTab';
import PayslipsTab from './components/PayslipsTab';
import InsightsTab from './components/InsightsTab';
import UserManagementTab from './components/UserManagementTab';
import Login from './components/Login';

const DEFAULT_LOGO = "data:image/png;base64,";

const FIELD_DEFINITIONS: { key: keyof ColumnMapping; label: string; aliases: string[] }[] = [
  { key: 'id', label: 'Employee ID', aliases: ['id', 'emp id', 'employee id', 'code'] },
  { key: 'name', label: 'Employee Name', aliases: ['name', 'emp name', 'fullname'] },
  { key: 'esiNo', label: 'ESI Account', aliases: ['esi'] },
  { key: 'uanNo', label: 'UAN Number', aliases: ['uan'] },
  { key: 'totalDays', label: 'Total Period Days', aliases: ['total days', 'days in month'] },
  { key: 'workedDays', label: 'Worked Days', aliases: ['worked', 'worked days', 'present'] },
  { key: 'otHours', label: 'OT Hours', aliases: ['ot', 'ot hours'] },
  { key: 'fixedGross', label: 'Fixed Gross', aliases: ['fixed gross', 'gross salary'] },
  { key: 'basicDA', label: 'Basic + DA', aliases: ['basic', 'basic da'] },
  { key: 'bonus', label: 'Bonus', aliases: ['bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus'] },
  { key: 'esiDeduction', label: 'ESI Deduction', aliases: ['esi deduction'] },
  { key: 'pfDeduction', label: 'PF Deduction', aliases: ['pf deduction', 'epf'] },
  { key: 'ptDeduction', label: 'Prof. Tax', aliases: ['pt', 'prof tax'] },
  { key: 'lwfDeduction', label: 'LWF', aliases: ['lwf'] },
  { key: 'canteenDeduction', label: 'Canteen', aliases: ['canteen'] },
  { key: 'otherDeduction', label: 'Other Deduction', aliases: ['other deduction', 'others'] }
];

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({ isAuthenticated: false, user: null, loading: true });
  const [authError, setAuthError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>(TabType.HOME);
  const [employees, setEmployees] = useState<EmployeeSalaryData[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [companyLogo, setCompanyLogo] = useState<string>(DEFAULT_LOGO);
  const [sync, setSync] = useState<SyncStatus>({ lastSynced: null, isSyncing: false, status: 'offline' });

  const [employers, setEmployers] = useState<string[]>([]);
  const [selectedEmployer, setSelectedEmployer] = useState<string>('');
  const [isAddEmployerOpen, setIsAddEmployerOpen] = useState(false);
  const [newEmployerName, setNewEmployerName] = useState('');

  const [showMapping, setShowMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [currentCsvData, setCurrentCsvData] = useState<any[]>([]);
  const [mapping, setMapping] = useState<Partial<ColumnMapping>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedSession = localStorage.getItem('payslip_session_v5');
    if (savedSession) {
      setAuth({ isAuthenticated: true, user: JSON.parse(savedSession), loading: false });
    } else {
      setAuth(prev => ({ ...prev, loading: false }));
    }
    loadInitialData();
  }, []);

  const loadInitialData = async () => {
    const cloudLogo = await cloudApi.fetchLogo();
    if (cloudLogo) setCompanyLogo(cloudLogo);

    const employerList = await cloudApi.fetchEmployers();
    setEmployers(employerList);
    if (employerList.length > 0) setSelectedEmployer(employerList[0]);
  };

  const loadFromCloud = async () => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      const data = await cloudApi.fetchEmployees();
      setEmployees(data);
      setSync({ 
        lastSynced: new Date(), 
        isSyncing: false, 
        status: cloudApi.isCloudActive() ? 'online' : 'offline' 
      });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => e.principalEmployer === selectedEmployer);
  }, [employees, selectedEmployer]);

  const pushToCloud = async (newEmployees: EmployeeSalaryData[]) => {
    setSync(prev => ({ ...prev, isSyncing: true }));
    try {
      await cloudApi.saveEmployees(newEmployees);
      setSync({ 
        lastSynced: new Date(), 
        isSyncing: false, 
        status: cloudApi.isCloudActive() ? 'online' : 'offline' 
      });
    } catch (err) {
      setSync(prev => ({ ...prev, isSyncing: false, status: 'error' }));
      setUploadError("Cloud Sync Failed. Data saved locally only.");
    }
  };

  const handleBackup = async () => {
    const backup = await cloudApi.exportFullDatabase();
    const blob = new Blob([backup], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Maruthi_Payroll_CloudBackup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLogin = async (username: string, password: string) => {
    const user = await cloudApi.authenticate(username, password);
    if (user) {
      localStorage.setItem('payslip_session_v5', JSON.stringify(user));
      setAuth({ isAuthenticated: true, user, loading: false });
      setAuthError(null);
    } else {
      setAuthError('Invalid credentials. Access denied.');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('payslip_session_v5');
    setAuth({ isAuthenticated: false, user: null, loading: false });
    setActiveTab(TabType.HOME);
  };

  useEffect(() => {
    if (auth.isAuthenticated) loadFromCloud();
  }, [auth.isAuthenticated]);

  const handleAddEmployer = async () => {
    if (!newEmployerName.trim()) return;
    const updated = [...employers, newEmployerName.trim()];
    await cloudApi.saveEmployers(updated);
    setEmployers(updated);
    setSelectedEmployer(newEmployerName.trim());
    setNewEmployerName('');
    setIsAddEmployerOpen(false);
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setCompanyLogo(base64);
        await cloudApi.saveLogo(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const cleanNumber = (val: any): number => {
    if (val === null || val === undefined) return 0;
    let str = String(val).trim().replace(/,/g, '').replace(/\s/g, '');
    if (str === '-' || str === '') return 0;
    const parsed = parseFloat(str);
    return isNaN(parsed) ? 0 : parsed;
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true, skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setCurrentCsvData(results.data);

          const newMapping: Partial<ColumnMapping> = {};
          const assignedHeaders = new Set<string>();

          FIELD_DEFINITIONS.forEach(fieldDef => {
            const match = headers.find(h => 
              !assignedHeaders.has(h) && 
              fieldDef.aliases.some(alias => h.toLowerCase().trim().includes(alias))
            );
            if (match) {
              newMapping[fieldDef.key] = match;
              assignedHeaders.add(match);
            }
          });

          setMapping(newMapping);
          setShowMapping(true);
        }
      }
    });
    if (event.target) event.target.value = '';
  };

  const processDataWithMapping = () => {
    try {
      const now = new Date();
      const prevDateObj = new Date(now.getFullYear(), now.getMonth(), 0);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      const displayMonth = monthNames[prevDateObj.getMonth()];
      const displayYear = prevDateObj.getFullYear();
      const day = String(prevDateObj.getDate()).padStart(2, '0');
      const prevMonthEndStr = `${day}-${displayMonth}-${displayYear}`;

      const parsedData = currentCsvData.map((row: any) => {
        const getVal = (field: keyof ColumnMapping) => cleanNumber(row[mapping[field]!]);
        const earnings = getVal('basicDA') + getVal('bonus') + getVal('otAmount') + getVal('arrears') + getVal('attendanceBonus');
        const deductions = getVal('esiDeduction') + getVal('pfDeduction') + getVal('ptDeduction') + getVal('lwfDeduction') + getVal('otherDeduction') + getVal('canteenDeduction');
        return {
          id: row[mapping.id!] || 'N/A', name: (row[mapping.name!] || 'Unknown').toUpperCase(),
          esiNo: row[mapping.esiNo!] || 'N/A', uanNo: row[mapping.uanNo!] || 'N/A',
          totalDays: getVal('totalDays'), workedDays: getVal('workedDays'), otHours: getVal('otHours'),
          fixedGross: getVal('fixedGross'), basicDA: getVal('basicDA'), bonus: getVal('bonus'),
          otAmount: getVal('otAmount'), arrears: getVal('arrears'), attendanceBonus: getVal('attendanceBonus'),
          esiDeduction: getVal('esiDeduction'), pfDeduction: getVal('pfDeduction'), ptDeduction: getVal('ptDeduction'),
          lwfDeduction: getVal('lwfDeduction'), canteenDeduction: getVal('canteenDeduction'), otherDeduction: getVal('otherDeduction'),
          grossEarnings: earnings, totalDeductions: deductions, netSalary: earnings - deductions, 
          month: displayMonth, year: displayYear, displayDate: prevMonthEndStr,
          principalEmployer: selectedEmployer
        } as EmployeeSalaryData;
      });

      const updatedList = [...employees, ...parsedData];
      setEmployees(updatedList);
      pushToCloud(updatedList);
      setShowMapping(false);
    } catch (err) { setUploadError("Mapping failed."); }
  };

  const isAdmin = auth.user?.role === Role.ADMIN;

  if (auth.loading) return <div className="h-screen flex items-center justify-center bg-gray-50"><RefreshCcw className="animate-spin text-indigo-600" size={48} /></div>;
  if (!auth.isAuthenticated) return <Login onLogin={handleLogin} error={authError} />;

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col md:flex-row">
      <nav className="w-full md:w-80 bg-white border-r border-gray-100 p-8 flex flex-col gap-2 overflow-y-auto">

        <div className="flex flex-col gap-6 mb-10">
          <div className="relative group w-20 h-20 self-center">
            <div className="w-20 h-20 bg-gray-50 rounded-2xl flex items-center justify-center overflow-hidden border border-gray-100 shadow-sm transition-all group-hover:scale-[1.02]">
              {companyLogo ? (
                <img src={companyLogo} alt="Company Logo" className="w-full h-full object-contain p-2" />
              ) : (
                <Building2 size={24} className="text-gray-300" />
              )}
            </div>
            {isAdmin && (
              <button 
                onClick={() => logoInputRef.current?.click()}
                className="absolute -bottom-1 -right-1 p-2 bg-indigo-600 text-white rounded-xl shadow-lg border-2 border-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-700"
              >
                <Camera size={10} />
              </button>
            )}
            <input ref={logoInputRef} type="file" accept="image/*" className="hidden" onChange={handleLogoChange} />
          </div>
          <div className="text-center">
            <h1 className="text-lg font-black text-gray-900 tracking-tighter leading-none">Maruthi HR</h1>
            <p className="text-[8px] font-bold text-indigo-500 uppercase tracking-widest mt-1">
              Consultancy Portal
            </p>
          </div>
        </div>

        <div className="mb-8 space-y-3">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <Briefcase size={12} className="text-indigo-400" /> Active Client
          </label>
          <div className="flex gap-2">
            <select 
              value={selectedEmployer} 
              onChange={(e) => setSelectedEmployer(e.target.value)}
              className="flex-1 bg-indigo-50/50 border border-indigo-100 rounded-2xl px-4 py-3 text-xs font-black text-indigo-900 outline-none focus:ring-2 focus:ring-indigo-600 appearance-none"
            >
              {employers.map(e => <option key={e} value={e}>{e}</option>)}
            </select>
            {isAdmin && (
              <button 
                onClick={() => setIsAddEmployerOpen(true)}
                className="p-3 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
        </div>

        <button onClick={() => setActiveTab(TabType.HOME)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.HOME ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <LayoutDashboard size={20} /><span>Payroll Audit</span>
        </button>

        <button onClick={() => setActiveTab(TabType.PAYSLIPS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.PAYSLIPS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <FileText size={20} /><span>Payslip Search</span>
        </button>

        <button onClick={() => setActiveTab(TabType.INSIGHTS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.INSIGHTS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
          <PieChart size={20} /><span>Statutory Insights</span>
        </button>

        {isAdmin && (
          <button onClick={() => setActiveTab(TabType.USERS)} className={`flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${activeTab === TabType.USERS ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>
            <UsersIcon size={20} /><span>User Accounts</span>
          </button>
        )}

        <div className="mt-auto pt-8 border-t border-gray-50 space-y-4">
          <div className={`px-4 py-4 rounded-2xl border flex items-start gap-3 transition-colors ${sync.status === 'online' ? 'bg-emerald-50/50 border-emerald-100' : sync.status === 'offline' ? 'bg-amber-50/50 border-amber-100' : 'bg-red-50/50 border-red-100'}`}>
             {sync.status === 'online' ? <Cloud className="text-emerald-600" size={20} /> : <CloudOff className="text-amber-600" size={20} />}
             <div className="flex flex-col">
                <p className={`text-[9px] font-black uppercase tracking-widest ${sync.status === 'online' ? 'text-emerald-900' : 'text-amber-900'}`}>
                  {sync.status === 'online' ? 'Cloud Connected' : 'Local Only Mode'}
                </p>
                <p className={`text-[8px] font-bold leading-tight mt-1 ${sync.status === 'online' ? 'text-emerald-600' : 'text-amber-600'}`}>
                  {sync.status === 'online' 
                    ? `Global sync active. Last seen: ${sync.lastSynced?.toLocaleTimeString()}` 
                    : 'Cloud keys missing. Data stays on this device only.'}
                </p>
             </div>
          </div>

          {isAdmin && (
            <button 
              onClick={handleBackup}
              className="w-full flex items-center gap-4 px-5 py-4 text-gray-400 hover:bg-gray-50 rounded-2xl transition-all group"
            >
              <Database size={20} className="group-hover:text-indigo-600" />
              <div className="text-left">
                <p className="text-xs font-bold leading-none">System Backup</p>
                <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-1">Export JSON</p>
              </div>
              <Download size={14} className="ml-auto" />
            </button>
          )}

          <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 py-4 text-[10px] font-black text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all uppercase tracking-widest">
            <LogOut size={16} /> Close Portal
          </button>
        </div>
      </nav>

      <main className="flex-1 p-10 overflow-auto">
        {uploadError && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center justify-between text-red-700 animate-bounce">
            <div className="flex items-center gap-3">
              <AlertCircle size={20} />
              <p className="text-xs font-bold uppercase tracking-widest">{uploadError}</p>
            </div>
            <button onClick={() => setUploadError(null)} className="p-1 hover:bg-red-100 rounded-full"><X size={16} /></button>
          </div>
        )}

        {isAdmin && !cloudApi.isCloudActive() && (
          <div className="mb-8 p-6 bg-blue-600 rounded-[32px] text-white shadow-xl shadow-blue-100 flex items-center justify-between animate-in fade-in zoom-in">
             <div className="flex items-center gap-6">
                <div className="p-4 bg-white/10 rounded-2xl"><Server size={32} /></div>
                <div>
                   <h3 className="text-lg font-black tracking-tight">Cloud Database Not Active</h3>
                   <p className="text-xs font-bold opacity-80 uppercase tracking-widest mt-1">Setup Supabase to share data across devices</p>
                </div>
             </div>
             <button 
                onClick={() => window.open('https://supabase.com', '_blank')}
                className="px-6 py-3 bg-white text-blue-600 font-black rounded-xl text-[10px] uppercase tracking-widest hover:bg-blue-50 transition-colors"
             >
                Activate Cloud
             </button>
          </div>
        )}

        <div className="mb-6 flex items-center justify-between">
            <div className="bg-white border border-gray-100 rounded-2xl px-6 py-4 flex items-center gap-4 shadow-sm">
                <div className={`w-2 h-2 rounded-full ${sync.status === 'online' ? 'bg-emerald-500 animate-pulse' : 'bg-amber-400'}`}></div>
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Client Environment:</span>
                <span className="text-xs font-black text-indigo-600 uppercase tracking-tighter">{selectedEmployer}</span>
            </div>

            <div className="flex items-center gap-2 px-4 py-2 bg-indigo-50/30 rounded-full border border-indigo-50">
                <RefreshCcw size={14} className={`text-indigo-400 ${sync.isSyncing ? 'animate-spin' : ''}`} />
                <span className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">
                  {sync.isSyncing ? 'Syncing...' : 'Real-time V5.0 (Global)'}
                </span>
            </div>
        </div>

        <div className="animate-in fade-in duration-700">
          {activeTab === TabType.HOME && <HomeTab employees={filteredEmployees} onUploadTrigger={isAdmin ? () => fileInputRef.current?.click() : undefined} />}
          {activeTab === TabType.PAYSLIPS && <PayslipsTab employees={filteredEmployees} companyLogo={companyLogo} showBulkOptions={isAdmin} />}
          {activeTab === TabType.INSIGHTS && <InsightsTab employees={filteredEmployees} />}
          {activeTab === TabType.USERS && isAdmin && <UserManagementTab employees={filteredEmployees} />}
        </div>
        <input ref={fileInputRef} type="file" accept=".csv" onChange={handleFileSelect} className="hidden" />
      </main>

      {/* Modals */}
      {isAddEmployerOpen && (
        <div className="fixed inset-0 z-[150] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 flex flex-col items-center text-center">
              <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-6">
                <Plus size={32} />
              </div>
              <h3 className="text-xl font-black text-gray-900 mb-2">New Principal Employer</h3>
              <p className="text-sm text-gray-500 font-medium mb-8">Add a new company/client to your Maruthi portal.</p>

              <input 
                value={newEmployerName}
                onChange={e => setNewEmployerName(e.target.value)}
                placeholder="Client Company Name"
                className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-4 text-sm font-bold mb-6 outline-none focus:ring-2 focus:ring-indigo-600"
              />

              <div className="flex gap-4 w-full">
                <button onClick={() => setIsAddEmployerOpen(false)} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 transition-all uppercase tracking-widest text-xs">Cancel</button>
                <button onClick={handleAddEmployer} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-700 transition-all uppercase tracking-widest text-xs">Add Client</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showMapping && isAdmin && (
        <div className="fixed inset-0 z-[120] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden flex flex-col max-h-[90vh] animate-in slide-in-from-bottom-8">
            <div className="p-10 border-b border-gray-50 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black">Import for {selectedEmployer}</h3>
                <p className="text-indigo-200 text-xs font-bold uppercase tracking-widest">Mapping Data Structure</p>
              </div>
              <button onClick={() => setShowMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={28} /></button>
            </div>
            <div className="p-10 overflow-y-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 bg-gray-50/30">
              {FIELD_DEFINITIONS.map((f) => (
                <div key={f.key} className="flex flex-col gap-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase">{f.label}</label>
                  <select 
                    value={mapping[f.key] || ''} 
                    onChange={(e) => setMapping({ ...mapping, [f.key]: e.target.value })} 
                    className="w-full bg-white border border-gray-200 rounded-2xl px-5 py-3 text-sm font-bold"
                  >
                    <option value="">-- Ignore --</option>
                    {csvHeaders.filter(h => h === mapping[f.key] || !Object.values(mapping).includes(h)).map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={processDataWithMapping} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> UPLOAD TO CLOUD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

