  { key: 'bonus', label: 'Bonus', aliases: ['bonus'] },
  { key: 'otAmount', label: 'OT Amount', aliases: ['ot amount'] },
  { key: 'arrears', label: 'Arrears', aliases: ['arrears'] },
  { key: 'attendanceBonus', label: 'Attendance Bonus', aliases: ['attendance bonus'] },
