const getEnvVar = (key: string): string => {
  try {
    const metaEnv = (import.meta as any).env;
    if (metaEnv && metaEnv[key]) return metaEnv[key];
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key] as string;
    }
  } catch (e) {}
  return '';
};

const supabaseUrl = getEnvVar('VITE_SUPABASE_URL');
const supabaseKey = getEnvVar('VITE_SUPABASE_ANON_KEY');
const supabase = (supabaseUrl && supabaseKey) ? createClient(supabaseUrl, supabaseKey) : null;

const DB_NAME = 'MaruthiHR_LocalCache_V5';
const DB_VERSION = 1;
const STORES = {
  EMPLOYEES: 'employees',
  USERS: 'users',
  EMPLOYERS: 'employers',
  ATTENDANCE: 'attendance'
};

const getIDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      Object.values(STORES).forEach(store => {
        if (!db.objectStoreNames.contains(store)) db.createObjectStore(store);
      });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const localOp = async <T>(storeName: string, mode: IDBTransactionMode, operation: (store: IDBObjectStore) => IDBRequest): Promise<T> => {
  const db = await getIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);
    const request = operation(store);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const cloudApi = {
  isCloudActive(): boolean {
    return !!supabase;
  },

  async fetchLogo(): Promise<string | null> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_logo')
          .maybeSingle();

        if (data?.data) {
          localStorage.setItem('company_logo', data.data);
          return data.data;
        }
      } catch (e) {
        console.warn("Logo cloud fetch failed", e);
      }
    }
    return localStorage.getItem('company_logo');
  },

  async saveLogo(logoBase64: string): Promise<void> {
    localStorage.setItem('company_logo', logoBase64);
    if (supabase) {
      await supabase
        .from('payroll_records')
        .upsert({ id: 'global_logo', data: logoBase64, updated_at: new Date().toISOString() });
    }
  },

  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_roster')
          .maybeSingle();

        if (data?.data) {
          await this.saveLocalEmployees(data.data);
          return data.data;
        }
      } catch (err) {
        console.warn("Cloud roster fetch failed, falling back to local", err);
      }
    }

    try {
      const data = await localOp<EmployeeSalaryData[]>(STORES.EMPLOYEES, 'readonly', (s) => s.get('all_records'));
      return data || [];
    } catch {
      return [];
    }
  },

  async saveLocalEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await localOp(STORES.EMPLOYEES, 'readwrite', (s) => s.put(employees, 'all_records'));
  },

  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await this.saveLocalEmployees(employees);

    if (supabase) {
      const { error } = await supabase
        .from('payroll_records')
        .upsert({ id: 'global_roster', data: employees, updated_at: new Date().toISOString() });

      if (error) throw new Error("Cloud sync failed: " + error.message);
    }
  },

  async fetchAttendance(): Promise<AttendanceRecord[]> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_attendance')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Attendance cloud fetch failed", e);
      }
    }
    const localData = await localOp<AttendanceRecord[]>(STORES.ATTENDANCE, 'readonly', (s) => s.get('all_attendance'));
    return localData || [];
  },

  async saveAttendance(records: AttendanceRecord[]): Promise<void> {
    await localOp(STORES.ATTENDANCE, 'readwrite', (s) => s.put(records, 'all_attendance'));
    if (supabase) {
      await supabase
        .from('payroll_records')
        .upsert({ id: 'global_attendance', data: records, updated_at: new Date().toISOString() });
    }
  },

  async fetchUsers(): Promise<User[]> {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'maruthihrsolution25@gmail.com'
    };

    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_users')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Users cloud fetch failed", e);
      }
    }

    const localData = await localOp<User[]>(STORES.USERS, 'readonly', (s) => s.get('all_users'));
    if (!localData) {
      await this.saveUsers([defaultAdmin]);
      return [defaultAdmin];
    }
    return localData;
  },

  async saveUsers(users: User[]): Promise<void> {
    await localOp(STORES.USERS, 'readwrite', (s) => s.put(users, 'all_users'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_users', data: users, updated_at: new Date().toISOString() });
    }
  },

  async updateUserPassword(username: string, newPass: string): Promise<void> {
    const users = await this.fetchUsers();
    const updated = users.map(u => u.username === username ? { ...u, password: newPass } : u);
    await this.saveUsers(updated);
  },

  async fetchEmployers(): Promise<string[]> {
    const defaults = ['HEALTHY FOOD PRODUCTS'];

    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_employers')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Employers cloud fetch failed", e);
      }
    }

    const localData = await localOp<string[]>(STORES.EMPLOYERS, 'readonly', (s) => s.get('all_employers'));
    if (!localData) {
      await this.saveEmployers(defaults);
      return defaults;
    }
    return localData;
  },

  async saveEmployers(employers: string[]): Promise<void> {
    await localOp(STORES.EMPLOYERS, 'readwrite', (s) => s.put(employers, 'all_employers'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_employers', data: employers, updated_at: new Date().toISOString() });
    }
  },

  async authenticate(username: string, password: string): Promise<User | null> {
    const users = await this.fetchUsers();
    return users.find(u => u.username === username && u.password === password) || null;
  },

  async exportFullDatabase(): Promise<string> {
    const data = {
      employees: await this.fetchEmployees(),
      users: await this.fetchUsers(),
      employers: await this.fetchEmployers(),
      attendance: await this.fetchAttendance(),
      timestamp: new Date().toISOString(),
      provider: supabase ? 'Supabase Cloud' : 'IndexedDB Local'
    };
    return JSON.stringify(data, null, 2);
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { AttendanceRecord, AttendanceStatus, EmployeeSalaryData } from '../types';
import { Calendar, UserCheck, Save, ChevronLeft, ChevronRight, Loader2, Search, Info } from 'lucide-react';
import { cloudApi } from '../services/api';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadAttendance();
  }, []);

  const loadAttendance = async () => {
    const data = await cloudApi.fetchAttendance();
    setAttendanceRecords(data);
  };

  // Derive current roster for the selected client
  const roster = useMemo(() => {
    const uniqueStaff = new Map<string, string>();
    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      uniqueStaff.set(e.id, e.name);
    });
    return Array.from(uniqueStaff.entries()).map(([id, name]) => ({ id, name }));
  }, [employees, selectedEmployer]);

  const currentRecords = useMemo(() => {
    return roster.map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.id && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      if (existing) return existing;

      // Create empty record if none exists
      return {
        employeeId: staff.id,
        employeeName: staff.name,
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        days: {},
        totalWorkedDays: 0
      } as AttendanceRecord;
    });
  }, [roster, attendanceRecords, selectedEmployer, viewMonth, viewYear]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const cycleStatus = (recordIdx: number, day: number) => {
    const nextStatusMap: Record<string, AttendanceStatus> = {
      'null': 'P',
      'P': 'H',
      'H': 'A',
      'A': 'L',
      'L': null
    };

    const updated = [...attendanceRecords];
    const record = currentRecords[recordIdx];
    const existingIdx = updated.findIndex(r => 
      r.employeeId === record.employeeId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    const targetRecord = existingIdx >= 0 ? { ...updated[existingIdx] } : { ...record };
    const currentStatus = targetRecord.days[day] || 'null';
    targetRecord.days[day] = nextStatusMap[String(currentStatus)];

    // Recalculate Worked Days
    targetRecord.totalWorkedDays = Object.values(targetRecord.days).reduce((acc, status) => {
      if (status === 'P') return acc + 1;
      if (status === 'H') return acc + 0.5;
      return acc;
    }, 0);

    if (existingIdx >= 0) {
      updated[existingIdx] = targetRecord;
    } else {
      updated.push(targetRecord);
    }
    setAttendanceRecords(updated);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  const getStatusColor = (status: AttendanceStatus) => {
    if (status === 'P') return 'bg-emerald-500 text-white';
    if (status === 'A') return 'bg-red-500 text-white';
    if (status === 'H') return 'bg-amber-500 text-white';
    if (status === 'L') return 'bg-indigo-500 text-white';
    return 'bg-gray-100 text-transparent';
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Attendance Register</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Log daily presence to auto-populate monthly worked days</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button 
            onClick={saveToCloud}
            disabled={isSaving}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98] disabled:opacity-50"
          >
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span>Sync Attendance</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center gap-4">
           <div className="w-8 h-8 rounded-lg bg-emerald-500 flex items-center justify-center text-[10px] font-black text-white">P</div>
           <span className="text-[10px] font-bold text-gray-500 uppercase">Present (1.0)</span>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center gap-4">
           <div className="w-8 h-8 rounded-lg bg-amber-500 flex items-center justify-center text-[10px] font-black text-white">H</div>
           <span className="text-[10px] font-bold text-gray-500 uppercase">Half Day (0.5)</span>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center gap-4">
           <div className="w-8 h-8 rounded-lg bg-red-500 flex items-center justify-center text-[10px] font-black text-white">A</div>
           <span className="text-[10px] font-bold text-gray-500 uppercase">Absent (0)</span>
        </div>
        <div className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center gap-4">
           <div className="w-8 h-8 rounded-lg bg-indigo-500 flex items-center justify-center text-[10px] font-black text-white">L</div>
           <span className="text-[10px] font-bold text-gray-500 uppercase">Leave (0)</span>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              placeholder="Filter roster..." 
              className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none"
            />
          </div>
          <div className="px-4 py-2 bg-indigo-50 rounded-xl flex items-center gap-2">
            <UserCheck size={14} className="text-indigo-600" />
            <span className="text-[10px] font-black text-indigo-900 uppercase">{filteredRecords.length} Active Staff</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="sticky left-0 z-20 bg-white px-6 py-4 text-left border-r border-gray-100">
                  <span className="text-[10px] font-black text-gray-400 uppercase">Employee Details</span>
                </th>
                {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => (
                  <th key={day} className="px-2 py-4 text-center border-r border-gray-100 last:border-r-0 min-w-[40px]">
                    <span className="text-[10px] font-black text-gray-400">{day}</span>
                  </th>
                ))}
                <th className="px-6 py-4 text-center bg-indigo-50/50 min-w-[100px]">
                   <span className="text-[10px] font-black text-indigo-600 uppercase">Total Days</span>
                </th>
              </tr>
            </thead>
            <tbody>
              {filteredRecords.map((record, rIdx) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors border-b border-gray-50 last:border-b-0">
                  <td className="sticky left-0 z-10 bg-white px-6 py-4 border-r border-gray-100 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">
                    <p className="text-xs font-black text-gray-900 leading-tight">{record.employeeName}</p>
                    <p className="text-[9px] font-bold text-indigo-400 uppercase">{record.employeeId}</p>
                  </td>
                  {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => (
                    <td key={day} className="p-1 border-r border-gray-50 last:border-r-0">
                      <button 
                        onClick={() => cycleStatus(rIdx, day)}
                        className={`w-full aspect-square rounded-lg flex items-center justify-center text-[10px] font-black transition-all hover:scale-105 active:scale-90 ${getStatusColor(record.days[day])}`}
                      >
                        {record.days[day] || ''}
                      </button>
                    </td>
                  ))}
                  <td className="px-6 py-4 text-center bg-indigo-50/20">
                     <span className="text-sm font-black text-indigo-700">{record.totalWorkedDays.toFixed(1)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="p-6 bg-blue-50 border border-blue-100 rounded-[32px] flex gap-4">
         <Info className="text-blue-500 shrink-0" size={20} />
         <p className="text-xs font-medium text-blue-700 leading-relaxed">
           <strong>Pro Tip:</strong> These attendance logs are automatically linked to your CSV Imports. If you import a payroll ledger for {viewMonth} {viewYear}, the system will pre-fill the "Worked Days" field using the data above, overriding manual entries.
         </p>
      </div>
    </div>
  );
};

