                    <option value="">-- Ignore --</option>
                    {csvHeaders.filter(h => h === mapping[f.key] || !Object.values(mapping).includes(h)).map(h => (
                      <option key={h} value={h}>{h}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
            <div className="p-10 bg-white border-t border-gray-100 flex gap-6">
              <button onClick={processDataWithMapping} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                <Cloud size={18} /> UPLOAD TO CLOUD
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { AttendanceRecord, AttendanceStatus, EmployeeSalaryData } from '../types';
import { Calendar, UserCheck, Save, ChevronLeft, ChevronRight, Loader2, Search, Info } from 'lucide-react';
import { cloudApi } from '../services/api';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadAttendance();
  }, []);

  const loadAttendance = async () => {
    const data = await cloudApi.fetchAttendance();
    setAttendanceRecords(data);
  };

  // Derive current roster for the selected client
  const roster = useMemo(() => {
    const uniqueStaff = new Map<string, string>();
    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      uniqueStaff.set(e.id, e.name);
    });
    return Array.from(uniqueStaff.entries()).map(([id, name]) => ({ id, name }));
  }, [employees, selectedEmployer]);

  const currentRecords = useMemo(() => {
    return roster.map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.id && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      if (existing) return existing;

      // Create empty record if none exists
      return {
        employeeId: staff.id,
        employeeName: staff.name,
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        days: {},
        totalWorkedDays: 0
      } as AttendanceRecord;
    });
  }, [roster, attendanceRecords, selectedEmployer, viewMonth, viewYear]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const cycleStatus = (recordIdx: number, day: number) => {
    const nextStatusMap: Record<string, AttendanceStatus> = {
      'null': 'P',
      'P': 'H',
      'H': 'A',
      'A': 'L',
      'L': null
    };

    const updated = [...attendanceRecords];
    const record = currentRecords[recordIdx];
    const existingIdx = updated.findIndex(r => 
      r.employeeId === record.employeeId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    const targetRecord = existingIdx >= 0 ? { ...updated[existingIdx] } : { ...record };
    const currentStatus = targetRecord.days[day] || 'null';
    targetRecord.days[day] = nextStatusMap[String(currentStatus)];

    // Recalculate Worked Days
    // Fix: Explicitly type accumulator as number to avoid 'unknown' operator error
    targetRecord.totalWorkedDays = Object.values(targetRecord.days).reduce((acc: number, status) => {
      if (status === 'P') return acc + 1;
      if (status === 'H') return acc + 0.5;
      return acc;
    }, 0);

    if (existingIdx >= 0) {
      updated[existingIdx] = targetRecord;
    } else {
      updated.push(targetRecord);
    }
    setAttendanceRecords(updated);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  const getStatusColor = (status: AttendanceStatus) => {
    if (status === 'P') return 'bg-emerald-500 text-white';
    if (status === 'A') return 'bg-red-500 text-white';
    if (status === 'H') return 'bg-amber-500 text-white';
    if (status === 'L') return 'bg-indigo-500 text-white';
    return 'bg-gray-100 text-transparent';
  };

  return (
