}

export type ColumnMapping = Record<keyof Omit<EmployeeSalaryData, 'grossEarnings' | 'totalDeductions' | 'netSalary' | 'month' | 'year' | 'displayDate' | 'principalEmployer'>, string>;

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
