import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData } from '../types';
import { Calendar, Save, Loader2, Search, Info, UserCheck, ClipboardCheck, Upload, X, ShieldCheck, TrendingUp, Settings2 } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);

  // Mapping State
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadAttendance();
  }, []);

  const loadAttendance = async () => {
    const data = await cloudApi.fetchAttendance();
    setAttendanceRecords(data);
  };

  const roster = useMemo(() => {
    const uniqueStaff = new Map<string, {name: string, grade: string}>();

    // First, check existing attendance records for this month/client to pull grades
    attendanceRecords.filter(r => r.client === selectedEmployer).forEach(r => {
      uniqueStaff.set(r.employeeId, { name: r.employeeName, grade: r.grade || 'Grade 1' });
    });

    // Then merge with current payroll employees
    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { name: e.name, grade: e.grade || 'Grade 1' });
      }
    });

    return Array.from(uniqueStaff.entries()).map(([id, info]) => ({ id, ...info }));
  }, [employees, attendanceRecords, selectedEmployer]);

  const currentRecords = useMemo(() => {
    return roster.map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.id && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      return existing || {
        employeeId: staff.id,
        employeeName: staff.name,
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        pfPercent: 12,
        esiPercent: 0.75
      } as AttendanceRecord;
    });
  }, [roster, attendanceRecords, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          // Auto-mapping logic
          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
  };

  const processRosterMapping = () => {
    const newAttendanceEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      pfPercent: 12,
      esiPercent: 0.75
    }));

    // Merge with existing
    const merged = [...attendanceRecords];
    newAttendanceEntries.forEach(newEntry => {
      const idx = merged.findIndex(r => r.employeeId === newEntry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = newEntry;
      else merged.push(newEntry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  const getGradeColor = (grade: string) => {
    switch(grade) {
      case 'Grade 1': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'Grade 2': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Grade 3': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Grade 4': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Roster & Attendance</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Configure grades, CTC, and capture monthly worked stats</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button 
            onClick={() => rosterFileInputRef.current?.click()}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl shadow-sm hover:bg-gray-50 transition-all active:scale-[0.98]"
          >
            <Upload size={18} />
            <span className="text-xs uppercase tracking-widest">Upload Roster</span>
          </button>
          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button 
            onClick={saveToCloud}
            disabled={isSaving}
            className="flex items-center justify-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98] disabled:opacity-50"
          >
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><UserCheck size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Roster</p>
            <p className="text-xl font-black text-gray-900">{filteredRecords.length}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Avg CTC</p>
            <p className="text-xl font-black text-gray-900">₹{(filteredRecords.reduce((acc, r) => acc + (r.ctc || 0), 0) / Math.max(1, filteredRecords.length)).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><Settings2 size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">OT Pool</p>
            <p className="text-xl font-black text-gray-900">{filteredRecords.reduce((acc, r) => acc + (r.otHours || 0), 0)} Hrs</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><ShieldCheck size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Compliance</p>
            <p className="text-xl font-black">Audit Ready</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              placeholder="Filter by name or ID..." 
              className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-8 py-4 text-left min-w-[200px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee</span></th>
                <th className="px-4 py-4 text-center w-[120px]"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                <th className="px-4 py-4 text-center w-[110px]"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-4 py-4 text-center w-[110px]"><span className="text-[10px] font-black text-amber-500 uppercase">OT Hrs</span></th>
                <th className="px-4 py-4 text-center w-[150px]"><span className="text-[10px] font-black text-indigo-600 uppercase">CTC (Monthly)</span></th>
                <th className="px-4 py-4 text-center w-[90px]"><span className="text-[10px] font-black text-indigo-400 uppercase">PF %</span></th>
                <th className="px-4 py-4 text-center w-[90px]"><span className="text-[10px] font-black text-indigo-400 uppercase">ESI %</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-8 py-5">
                    <p className="text-xs font-black text-gray-900 leading-tight">{record.employeeName}</p>
                    <p className="text-[9px] font-bold text-indigo-400 uppercase tracking-tight">{record.employeeId}</p>
                  </td>
                  <td className="px-4 py-5 text-center">
                    <select 
                      value={record.grade}
                      onChange={(e) => updateRecord(record.employeeId, { grade: e.target.value })}
                      className={`text-[10px] font-black border rounded-lg px-2 py-1 outline-none appearance-none cursor-pointer ${getGradeColor(record.grade)}`}
                    >
                      <option value="Grade 1">Grade 1</option>
                      <option value="Grade 2">Grade 2</option>
                      <option value="Grade 3">Grade 3</option>
                      <option value="Grade 4">Grade 4</option>
                    </select>
                  </td>
                  <td className="px-4 py-5">
                    <input 
                      type="number" step="0.5" min="0" max={record.totalDays}
                      value={record.workedDays || ''}
                      onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-emerald-50/50 border border-emerald-100 rounded-xl px-2 py-2 text-center text-xs font-black text-emerald-700"
                    />
                  </td>
                  <td className="px-4 py-5">
                    <input 
                      type="number" step="1" min="0"
                      value={record.otHours || ''}
                      onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-amber-50/50 border border-amber-100 rounded-xl px-2 py-2 text-center text-xs font-black text-amber-700"
                    />
                  </td>
                  <td className="px-4 py-5">
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-bold text-indigo-300">₹</span>
                      <input 
                        type="number"
                        value={record.ctc || ''}
                        onChange={(e) => updateRecord(record.employeeId, { ctc: parseFloat(e.target.value) || 0 })}
                        className="w-full bg-indigo-50/50 border border-indigo-100 rounded-xl pl-6 pr-2 py-2 text-center text-xs font-black text-indigo-700"
                      />
                    </div>
                  </td>
                  <td className="px-4 py-5">
                    <input 
                      type="number" step="0.1"
                      value={record.pfPercent}
                      onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl px-2 py-2 text-center text-xs font-bold text-gray-600"
                    />
                  </td>
                  <td className="px-4 py-5">
                    <input 
                      type="number" step="0.01"
                      value={record.esiPercent}
                      onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl px-2 py-2 text-center text-xs font-bold text-gray-600"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="p-6 bg-blue-50 border border-blue-100 rounded-[32px] flex gap-4">
         <ClipboardCheck className="text-blue-500 shrink-0" size={20} />
         <p className="text-xs font-medium text-blue-700 leading-relaxed">
           <strong>Integration Note:</strong> This tab acts as your master compensation sheet. Settings here for <strong>Grades, CTC, PF%, and ESI%</strong> will override the defaults during the payroll generation process.
         </p>
      </div>

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Master Roster</h3>
              <button onClick={() => setShowRosterMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select 
                    value={rosterMapping[field]} 
                    onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})}
                    className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none"
                  >
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button 
                onClick={processRosterMapping}
                className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs"
              >
                Import Master Roster
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

