import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData } from '../types';
import { Calendar, Save, Loader2, Search, Info, UserCheck, Upload, X, TrendingUp, Settings2, IndianRupee, Calculator, CheckCircle } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);

  // Mapping State
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: '', ctc: '', basic: '', bonus: ''
  });

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadAttendance();
  }, []);

  const loadAttendance = async () => {
    const data = await cloudApi.fetchAttendance();
    setAttendanceRecords(data);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    // 1. Earned Components
    const earnedBasic = record.basicDA * workedRatio;
    const earnedBonus = record.bonus * workedRatio;

    // 2. OT Calculation: (Basic / 26 / 8) * 2 * OT Hours (Standard Rate)
    const otRate = (record.basicDA / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    // 3. Gross Calculation
    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    // 4. Deductions
    const pfDeduction = Math.floor(earnedBasic * (record.pfPercent / 100));
    const esiDeduction = Math.ceil(earnedGross * (record.esiPercent / 100));

    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + (record.ptDeduction || 0);

    return {
      ...record,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const roster = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeName: e.name, 
          grade: e.grade || 'Grade 1',
          ctc: e.fixedGross,
          basicDA: e.basicDA,
          bonus: e.bonus
        });
      }
    });

    return Array.from(uniqueStaff.entries()).map(([id, info]) => ({ id, ...info }));
  }, [employees, attendanceRecords, selectedEmployer]);

  const currentRecords = useMemo(() => {
    return roster.map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.id && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = existing || {
        employeeId: staff.id,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: staff.ctc || 0,
        basicDA: staff.basicDA || 0,
        bonus: staff.bonus || 0,
        pfPercent: 12,
        esiPercent: 0.75,
        canteenDeduction: 0,
        ptDeduction: 0
      } as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [roster, attendanceRecords, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '', ctc: '', basic: '', bonus: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
            if (low.includes('ctc') || low.includes('fixed gross')) newMap.ctc = h;
            if (low.includes('basic')) newMap.basic = h;
            if (low.includes('bonus')) newMap.bonus = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: parseFloat(row[rosterMapping.ctc]) || 0,
      basicDA: parseFloat(row[rosterMapping.basic]) || 0,
      bonus: parseFloat(row[rosterMapping.bonus]) || 0,
      pfPercent: 12,
      esiPercent: 0.75,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    const merged = [...attendanceRecords];
    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = entry;
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Define grade-level CTC and components to auto-calculate monthly payout</p>
        </div>

        <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => rosterFileInputRef.current?.click()} className="flex items-center gap-3 px-6 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all">
            <Upload size={18} /><span className="text-xs uppercase tracking-widest">Import Roster</span>
          </button>
          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Est. Gross Payout</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable Pool</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Settings2 size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Deduction Pool</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Audit Status</p>
            <p className="text-xl font-black">Calculation Verified</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search roster..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic+DA</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <span className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full">{record.grade}</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.basicDA || ''} onChange={(e) => updateRecord(record.employeeId, { basicDA: parseFloat(e.target.value) || 0 })} className="w-24 bg-indigo-50/30 border border-indigo-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-indigo-700" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.bonus || ''} onChange={(e) => updateRecord(record.employeeId, { bonus: parseFloat(e.target.value) || 0 })} className="w-20 bg-indigo-50/30 border border-indigo-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-indigo-700" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="p-6 bg-blue-50 border border-blue-100 rounded-[32px] flex gap-4">
         <Calculator className="text-blue-500 shrink-0" size={24} />
         <div className="space-y-1">
            <p className="text-xs font-black text-blue-900 uppercase">Calculation Engine V2.0 Active</p>
            <p className="text-[10px] font-medium text-blue-700 leading-relaxed">
              Earned salary is automatically prorated based on Worked Days. Overtime is calculated at 200% hourly rate (derived from Basic). PF and ESI are dynamically recalculated using the customized percentages set in the roster.
            </p>
         </div>
      </div>

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Financial Roster</h3>
              <button onClick={() => setShowRosterMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 grid grid-cols-2 gap-6">
              {Object.keys(rosterMapping).map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <div className="col-span-2 pt-4">
                <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Finalize Roster Import</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

