import { createClient } from '@supabase/supabase-js';
import { EmployeeSalaryData, User, Role, AttendanceRecord, GradeConfig } from '../types';

const getEnvVar = (key: string): string => {
  try {
    const metaEnv = (import.meta as any).env;
    if (metaEnv && metaEnv[key]) return metaEnv[key];
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key] as string;
    }
  } catch (e) {}
  return '';
};

const supabaseUrl = getEnvVar('VITE_SUPABASE_URL');
const supabaseKey = getEnvVar('VITE_SUPABASE_ANON_KEY');
const supabase = (supabaseUrl && supabaseKey) ? createClient(supabaseUrl, supabaseKey) : null;

const DB_NAME = 'MaruthiHR_LocalCache_V5';
const DB_VERSION = 1;
const STORES = {
  EMPLOYEES: 'employees',
  USERS: 'users',
  EMPLOYERS: 'employers',
  ATTENDANCE: 'attendance',
  GRADES: 'grade_configs'
};

const getIDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      Object.values(STORES).forEach(store => {
        if (!db.objectStoreNames.contains(store)) db.createObjectStore(store);
      });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const localOp = async <T>(storeName: string, mode: IDBTransactionMode, operation: (store: IDBObjectStore) => IDBRequest): Promise<T> => {
  const db = await getIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);
    const request = operation(store);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const cloudApi = {
  isCloudActive(): boolean {
    return !!supabase;
  },

  async fetchGradeConfigs(): Promise<GradeConfig[]> {
    const defaults: GradeConfig[] = [
      { grade: 'Grade 1', basicDA: 15000, bonus: 2000, pfPercent: 12, esiPercent: 0.75, ptAmount: 200 },
      { grade: 'Grade 2', basicDA: 12000, bonus: 1500, pfPercent: 12, esiPercent: 0.75, ptAmount: 150 },
      { grade: 'Grade 3', basicDA: 10000, bonus: 1000, pfPercent: 12, esiPercent: 0.75, ptAmount: 100 },
      { grade: 'Grade 4', basicDA: 8000, bonus: 500, pfPercent: 12, esiPercent: 0.75, ptAmount: 0 }
    ];

    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_grade_configs')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Grade config cloud fetch failed", e);
      }
    }

    const localData = await localOp<GradeConfig[]>(STORES.GRADES, 'readonly', (s) => s.get('all_configs'));
    return localData || defaults;
  },

  async saveGradeConfigs(configs: GradeConfig[]): Promise<void> {
    await localOp(STORES.GRADES, 'readwrite', (s) => s.put(configs, 'all_configs'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_grade_configs', data: configs, updated_at: new Date().toISOString() });
    }
  },

  async fetchLogo(): Promise<string | null> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_logo')
          .maybeSingle();

        if (data?.data) {
          localStorage.setItem('company_logo', data.data);
          return data.data;
        }
      } catch (e) {
        console.warn("Logo error", e);
      }
    }
    return localStorage.getItem('company_logo');
  },

  async saveLogo(logoBase64: string): Promise<void> {
    localStorage.setItem('company_logo', logoBase64);
    if (supabase) {
      await supabase
        .from('payroll_records')
        .upsert({ id: 'global_logo', data: logoBase64, updated_at: new Date().toISOString() });
    }
  },

  async fetchEmployees(): Promise<EmployeeSalaryData[]> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_roster')
          .maybeSingle();

        if (data?.data) {
          await this.saveLocalEmployees(data.data);
          return data.data;
        }
      } catch (err) {
        console.warn("Cloud roster fetch failed", err);
      }
    }

    try {
      const data = await localOp<EmployeeSalaryData[]>(STORES.EMPLOYEES, 'readonly', (s) => s.get('all_records'));
      return data || [];
    } catch {
      return [];
    }
  },

  async saveLocalEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await localOp(STORES.EMPLOYEES, 'readwrite', (s) => s.put(employees, 'all_records'));
  },

  async saveEmployees(employees: EmployeeSalaryData[]): Promise<void> {
    await this.saveLocalEmployees(employees);

    if (supabase) {
      const { error } = await supabase
        .from('payroll_records')
        .upsert({ id: 'global_roster', data: employees, updated_at: new Date().toISOString() });

      if (error) throw new Error("Cloud sync failed: " + error.message);
    }
  },

  async fetchAttendance(): Promise<AttendanceRecord[]> {
    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_attendance')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Attendance error", e);
      }
    }
    const localData = await localOp<AttendanceRecord[]>(STORES.ATTENDANCE, 'readonly', (s) => s.get('all_attendance'));
    return localData || [];
  },

  async saveAttendance(records: AttendanceRecord[]): Promise<void> {
    await localOp(STORES.ATTENDANCE, 'readwrite', (s) => s.put(records, 'all_attendance'));
    if (supabase) {
      await supabase
        .from('payroll_records')
        .upsert({ id: 'global_attendance', data: records, updated_at: new Date().toISOString() });
    }
  },

  async fetchUsers(): Promise<User[]> {
    const defaultAdmin: User = {
      username: 'admin',
      password: 'admin123',
      role: Role.ADMIN,
      name: 'System Administrator',
      email: 'maruthihrsolution25@gmail.com'
    };

    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_users')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Users error", e);
      }
    }

    const localData = await localOp<User[]>(STORES.USERS, 'readonly', (s) => s.get('all_users'));
    if (!localData) {
      await this.saveUsers([defaultAdmin]);
      return [defaultAdmin];
    }
    return localData;
  },

  async saveUsers(users: User[]): Promise<void> {
    await localOp(STORES.USERS, 'readwrite', (s) => s.put(users, 'all_users'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_users', data: users, updated_at: new Date().toISOString() });
    }
  },

  async updateUserPassword(username: string, newPass: string): Promise<void> {
    const users = await this.fetchUsers();
    const updated = users.map(u => u.username === username ? { ...u, password: newPass } : u);
    await this.saveUsers(updated);
  },

  async fetchEmployers(): Promise<string[]> {
    const defaults = ['HEALTHY FOOD PRODUCTS'];

    if (supabase) {
      try {
        const { data } = await supabase
          .from('payroll_records')
          .select('data')
          .eq('id', 'global_employers')
          .maybeSingle();
        if (data?.data) return data.data;
      } catch (e) {
        console.warn("Employers error", e);
      }
    }

    const localData = await localOp<string[]>(STORES.EMPLOYERS, 'readonly', (s) => s.get('all_employers'));
    if (!localData) {
      await this.saveEmployers(defaults);
      return defaults;
    }
    return localData;
  },

  async saveEmployers(employers: string[]): Promise<void> {
    await localOp(STORES.EMPLOYERS, 'readwrite', (s) => s.put(employers, 'all_employers'));
    if (supabase) {
      await supabase.from('payroll_records').upsert({ id: 'global_employers', data: employers, updated_at: new Date().toISOString() });
    }
  },

  async authenticate(username: string, password: string): Promise<User | null> {
    const users = await this.fetchUsers();
    return users.find(u => u.username === username && u.password === password) || null;
  },

  async exportFullDatabase(): Promise<string> {
    const data = {
      employees: await this.fetchEmployees(),
      users: await this.fetchUsers(),
      employers: await this.fetchEmployers(),
      attendance: await this.fetchAttendance(),
      timestamp: new Date().toISOString()
    };
    return JSON.stringify(data, null, 2);
  }
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    // 1. Get Grade defaults from Master if not already customized in the record
    const master = gradeConfigs.find(g => g.grade === record.grade);

    // Prorate ratio
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    // Earnings
    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;

    // OT: (Basic / 26 / 8) * 2 * OT Hours
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    // Deductions
    const pfPct = record.pfPercent || master?.pfPercent || 12;
    const esiPct = record.esiPercent || master?.esiPercent || 0.75;
    const ptAmt = record.ptDeduction || master?.ptAmount || 0;

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));

    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, // Ensure current values are reflected
      bonus: bonus,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    // Build roster from payroll history and uploaded planning data
    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    if (e.target) e.target.value = '';
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    const merged = [...attendanceRecords];
    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = { ...merged[idx], grade: entry.grade, employeeName: entry.employeeName };
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <button onClick={() => rosterFileInputRef.current?.click()} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
          </button>
          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex gap-2">
            <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Components Pulled from Master</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Bonus</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <span className="text-xs font-bold text-gray-400">₹{record.basicDA?.toLocaleString()}</span>
                  </td>
                  <td className="px-2 py-4 text-center">
                    <span className="text-xs font-bold text-gray-400">₹{record.bonus?.toLocaleString()}</span>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => setShowRosterMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  const now = new Date();
  const [viewYear, setViewYear] = useState(now.getFullYear());
  const [viewMonth, setViewMonth] = useState(now.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    // 1. Get Grade defaults from Master if not already customized in the record
    const master = gradeConfigs.find(g => g.grade === record.grade);

    // Prorate ratio
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    // Earnings
    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;

    // OT: (Basic / 26 / 8) * 2 * OT Hours
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    // Deductions - Use record value if > 0, otherwise fallback to master
    const pfPct = record.pfPercent > 0 ? record.pfPercent : (master?.pfPercent || 12);
    const esiPct = record.esiPercent > 0 ? record.esiPercent : (master?.esiPercent || 0.75);
    const ptAmt = record.ptDeduction > 0 ? record.ptDeduction : (master?.ptAmount || 0);

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));

    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, 
      bonus: bonus,
      // Store current pct in the calculated record for UI display consistency
      pfPercent: pfPct,
      esiPercent: esiPct,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    if (e.target) e.target.value = '';
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    const merged = [...attendanceRecords];
    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = { ...merged[idx], grade: entry.grade, employeeName: entry.employeeName };
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <button onClick={() => rosterFileInputRef.current?.click()} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
          </button>
          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex gap-2">
            <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Dynamic Payroll Simulation</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-gray-900">₹{record.basicDA?.toLocaleString()}</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Fixed</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.1" value={record.pfPercent || ''} onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.01" value={record.esiPercent || ''} onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => setShowRosterMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  // Default to Previous Month
  const defaultDate = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  }, []);

  const [viewYear, setViewYear] = useState(defaultDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(defaultDate.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  const dynamicYears = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return [currentYear - 1, currentYear, currentYear + 1];
  }, []);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    // 1. Get Grade defaults from Master if not already customized in the record
    const master = gradeConfigs.find(g => g.grade === record.grade);

    // Prorate ratio
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    // Earnings
    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;

    // OT: (Basic / 26 / 8) * 2 * OT Hours
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    // Deductions - Use record value if > 0, otherwise fallback to master
    const pfPct = record.pfPercent > 0 ? record.pfPercent : (master?.pfPercent || 12);
    const esiPct = record.esiPercent > 0 ? record.esiPercent : (master?.esiPercent || 0.75);
    const ptAmt = record.ptDeduction > 0 ? record.ptDeduction : (master?.ptAmount || 0);

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));

    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, 
      bonus: bonus,
      // Store current pct in the calculated record for UI display consistency
      pfPercent: pfPct,
      esiPercent: esiPct,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    if (e.target) e.target.value = '';
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    const merged = [...attendanceRecords];
    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = { ...merged[idx], grade: entry.grade, employeeName: entry.employeeName };
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {dynamicYears.map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <button onClick={() => rosterFileInputRef.current?.click()} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
          </button>
          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex gap-2">
            <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Dynamic Payroll Simulation</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-gray-900">₹{record.basicDA?.toLocaleString()}</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Fixed</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.1" value={record.pfPercent || ''} onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.01" value={record.esiPercent || ''} onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => setShowRosterMapping(false)} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield, RotateCcw } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);
  const [isReuploadMode, setIsReuploadMode] = useState(false);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  // Default to Previous Month
  const defaultDate = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  }, []);

  const [viewYear, setViewYear] = useState(defaultDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(defaultDate.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  const dynamicYears = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return [currentYear - 1, currentYear, currentYear + 1];
  }, []);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    const master = gradeConfigs.find(g => g.grade === record.grade);
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    const pfPct = record.pfPercent > 0 ? record.pfPercent : (master?.pfPercent || 12);
    const esiPct = record.esiPercent > 0 ? record.esiPercent : (master?.esiPercent || 0.75);
    const ptAmt = record.ptDeduction > 0 ? record.ptDeduction : (master?.ptAmount || 0);

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));
    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, 
      bonus: bonus,
      pfPercent: pfPct,
      esiPercent: esiPct,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>, reupload: boolean = false) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsReuploadMode(reupload);

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    if (e.target) e.target.value = '';
  };

  const handleTriggerReupload = () => {
    if (window.confirm(`WARNING: This will delete ALL current records for ${viewMonth} ${viewYear} before importing the new file. This cannot be undone. Continue?`)) {
      rosterFileInputRef.current?.click();
      // We set the mode in handleRosterUpload which is called when file is picked
    }
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    let merged = [...attendanceRecords];

    // If Re-upload, wipe data for the current period first
    if (isReuploadMode) {
      merged = merged.filter(r => 
        !(r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear)
      );
    }

    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = { ...merged[idx], grade: entry.grade, employeeName: entry.employeeName };
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
    setIsReuploadMode(false);
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {dynamicYears.map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <div className="flex gap-2">
            <button onClick={() => { setIsReuploadMode(false); rosterFileInputRef.current?.click(); }} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
              <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
            </button>
            <button onClick={handleTriggerReupload} className="flex items-center gap-3 px-5 py-3 bg-white border border-orange-200 text-orange-600 font-bold rounded-2xl hover:bg-orange-50 transition-all shadow-sm">
              <RotateCcw size={16} /><span className="text-[10px] uppercase tracking-widest">Re-upload</span>
            </button>
          </div>

          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={(e) => handleRosterUpload(e, isReuploadMode)} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex gap-2">
            <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Dynamic Payroll Simulation</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-gray-900">₹{record.basicDA?.toLocaleString()}</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Fixed</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.1" value={record.pfPercent || ''} onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.01" value={record.esiPercent || ''} onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => { setShowRosterMapping(false); setIsReuploadMode(false); }} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield, RotateCcw } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);
  const [isReuploadMode, setIsReuploadMode] = useState(false);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  // Default to Previous Month
  const defaultDate = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  }, []);

  const [viewYear, setViewYear] = useState(defaultDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(defaultDate.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate();

  const dynamicYears = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return [currentYear - 1, currentYear, currentYear + 1];
  }, []);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    const master = gradeConfigs.find(g => g.grade === record.grade);
    const workedRatio = record.workedDays / Math.max(1, record.totalDays);

    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    const pfPct = record.pfPercent > 0 ? record.pfPercent : (master?.pfPercent || 12);
    const esiPct = record.esiPercent > 0 ? record.esiPercent : (master?.esiPercent || 0.75);
    const ptAmt = record.ptDeduction > 0 ? record.ptDeduction : (master?.ptAmount || 0);

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));
    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, 
      bonus: bonus,
      pfPercent: pfPct,
      esiPercent: esiPct,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    const updated = [...attendanceRecords];
    const idx = updated.findIndex(r => 
      r.employeeId === empId && 
      r.client === selectedEmployer && 
      r.month === viewMonth && 
      r.year === viewYear
    );

    if (idx >= 0) {
      updated[idx] = { ...updated[idx], ...updates };
    } else {
      const base = currentRecords.find(r => r.employeeId === empId);
      if (base) {
        updated.push({ ...base, ...updates });
      }
    }
    setAttendanceRecords(updated);
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    if (e.target) e.target.value = '';
  };

  const handleTriggerReupload = () => {
    if (window.confirm(`WARNING: This will delete ALL current records for ${viewMonth} ${viewYear} before importing the new file. This cannot be undone. Continue?`)) {
      setIsReuploadMode(true);
      rosterFileInputRef.current?.click();
    }
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    let merged = [...attendanceRecords];

    // If Re-upload, wipe data for the current period first
    if (isReuploadMode) {
      merged = merged.filter(r => 
        !(r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear)
      );
    }

    newEntries.forEach(entry => {
      const idx = merged.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
      if (idx >= 0) merged[idx] = { ...merged[idx], grade: entry.grade, employeeName: entry.employeeName };
      else merged.push(entry);
    });

    setAttendanceRecords(merged);
    setShowRosterMapping(false);
    setIsReuploadMode(false);
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {dynamicYears.map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <div className="flex gap-2">
            <button onClick={() => { setIsReuploadMode(false); rosterFileInputRef.current?.click(); }} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
              <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
            </button>
            <button onClick={handleTriggerReupload} className="flex items-center gap-3 px-5 py-3 bg-white border border-orange-200 text-orange-600 font-bold rounded-2xl hover:bg-orange-50 transition-all shadow-sm">
              <RotateCcw size={16} /><span className="text-[10px] uppercase tracking-widest">Re-upload</span>
            </button>
          </div>

          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex gap-2">
            <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Dynamic Payroll Simulation</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.5" min="0" max={record.totalDays} value={record.workedDays || ''} onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-gray-900">₹{record.basicDA?.toLocaleString()}</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Fixed</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.1" value={record.pfPercent || ''} onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.01" value={record.esiPercent || ''} onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => { setShowRosterMapping(false); setIsReuploadMode(false); }} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { AttendanceRecord, EmployeeSalaryData, GradeConfig } from '../types';
import { Calendar, Save, Loader2, Search, Upload, X, TrendingUp, Settings2, Calculator, CheckCircle, Database, Shield, RotateCcw, AlertTriangle } from 'lucide-react';
import { cloudApi } from '../services/api';
import Papa from 'papaparse';

interface AttendanceTabProps {
  employees: EmployeeSalaryData[];
  selectedEmployer: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ employees, selectedEmployer }) => {
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [gradeConfigs, setGradeConfigs] = useState<GradeConfig[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const rosterFileInputRef = useRef<HTMLInputElement>(null);
  const reuploadPendingRef = useRef<boolean>(false);

  // Modals
  const [showRosterMapping, setShowRosterMapping] = useState(false);
  const [showGradeMaster, setShowGradeMaster] = useState(false);

  // CSV Import State
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [rosterMapping, setRosterMapping] = useState<Record<string, string>>({
    id: '', name: '', grade: ''
  });

  // Default to Previous Month
  const defaultDate = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() - 1);
    return d;
  }, []);

  const [viewYear, setViewYear] = useState(defaultDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(defaultDate.toLocaleString('default', { month: 'short' }));

  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const daysInMonth = useMemo(() => new Date(viewYear, monthNames.indexOf(viewMonth) + 1, 0).getDate(), [viewYear, viewMonth]);

  const dynamicYears = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return [currentYear - 1, currentYear, currentYear + 1];
  }, []);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [att, grades] = await Promise.all([
      cloudApi.fetchAttendance(),
      cloudApi.fetchGradeConfigs()
    ]);
    setAttendanceRecords(att);
    setGradeConfigs(grades);
  };

  const calculatePayroll = (record: AttendanceRecord): AttendanceRecord => {
    const master = gradeConfigs.find(g => g.grade === record.grade);
    // Ensure workedDays never exceeds totalDays for calculation safety
    const safeWorkedDays = Math.min(record.workedDays, record.totalDays);
    const workedRatio = safeWorkedDays / Math.max(1, record.totalDays);

    const basic = record.basicDA || master?.basicDA || 0;
    const bonus = record.bonus || master?.bonus || 0;

    const earnedBasic = basic * workedRatio;
    const earnedBonus = bonus * workedRatio;
    const otRate = (basic / 26 / 8) * 2;
    const earnedOT = otRate * record.otHours;

    const earnedGross = earnedBasic + earnedBonus + earnedOT;

    const pfPct = record.pfPercent > 0 ? record.pfPercent : (master?.pfPercent || 12);
    const esiPct = record.esiPercent > 0 ? record.esiPercent : (master?.esiPercent || 0.75);
    const ptAmt = record.ptDeduction > 0 ? record.ptDeduction : (master?.ptAmount || 0);

    const pfDeduction = Math.floor(earnedBasic * (pfPct / 100));
    const esiDeduction = Math.ceil(earnedGross * (esiPct / 100));
    const totalDeductions = pfDeduction + esiDeduction + (record.canteenDeduction || 0) + ptAmt;

    return {
      ...record,
      basicDA: basic, 
      bonus: bonus,
      pfPercent: pfPct,
      esiPercent: esiPct,
      computedGross: earnedGross,
      computedDeductions: totalDeductions,
      computedNet: earnedGross - totalDeductions
    };
  };

  const currentRecords = useMemo(() => {
    const uniqueStaff = new Map<string, Partial<AttendanceRecord>>();

    attendanceRecords.filter(r => r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear).forEach(r => {
      uniqueStaff.set(r.employeeId, r);
    });

    employees.filter(e => e.principalEmployer === selectedEmployer).forEach(e => {
      if (!uniqueStaff.has(e.id)) {
        uniqueStaff.set(e.id, { 
          employeeId: e.id,
          employeeName: e.name, 
          grade: e.grade || 'Grade 1'
        });
      }
    });

    return Array.from(uniqueStaff.values()).map(staff => {
      const existing = attendanceRecords.find(r => 
        r.employeeId === staff.employeeId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      const base = (existing || {
        employeeId: staff.employeeId,
        employeeName: staff.employeeName || 'Unknown',
        client: selectedEmployer,
        month: viewMonth,
        year: viewYear,
        totalDays: daysInMonth,
        workedDays: 0,
        leaveDays: 0,
        grade: staff.grade || 'Grade 1',
        otHours: 0,
        ctc: 0,
        basicDA: 0,
        bonus: 0,
        pfPercent: 0,
        esiPercent: 0,
        canteenDeduction: 0,
        ptDeduction: 0
      }) as AttendanceRecord;

      return calculatePayroll(base);
    });
  }, [employees, attendanceRecords, gradeConfigs, selectedEmployer, viewMonth, viewYear, daysInMonth]);

  const filteredRecords = currentRecords.filter(r => 
    r.employeeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    r.employeeId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const updateRecord = (empId: string, updates: Partial<AttendanceRecord>) => {
    // ENFORCE CONSTRAINT: Worked days cannot exceed total days in the month
    if (updates.workedDays !== undefined) {
      if (updates.workedDays > daysInMonth) {
        updates.workedDays = daysInMonth;
      } else if (updates.workedDays < 0) {
        updates.workedDays = 0;
      }
    }

    setAttendanceRecords(prev => {
      const updated = [...prev];
      const idx = updated.findIndex(r => 
        r.employeeId === empId && 
        r.client === selectedEmployer && 
        r.month === viewMonth && 
        r.year === viewYear
      );

      if (idx >= 0) {
        updated[idx] = { ...updated[idx], ...updates };
      } else {
        const base = currentRecords.find(r => r.employeeId === empId);
        if (base) {
          updated.push({ ...base, ...updates });
        }
      }
      return updated;
    });
  };

  const handleRosterUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);

          const newMap = { id: '', name: '', grade: '' };
          headers.forEach(h => {
            const low = h.toLowerCase();
            if (low.includes('id') || low.includes('code')) newMap.id = h;
            if (low.includes('name')) newMap.name = h;
            if (low.includes('grade')) newMap.grade = h;
          });
          setRosterMapping(newMap);
          setShowRosterMapping(true);
        }
      }
    });
    // Do NOT reset ref here, reset it after mapping is finished
    if (e.target) e.target.value = '';
  };

  const handleTriggerReupload = () => {
    if (window.confirm(`WARNING: This will delete ALL current records for ${viewMonth} ${viewYear} before importing the new file. This cannot be undone. Continue?`)) {
      reuploadPendingRef.current = true;
      rosterFileInputRef.current?.click();
    }
  };

  const processRosterMapping = () => {
    const newEntries: AttendanceRecord[] = rawCsvData.map(row => ({
      employeeId: String(row[rosterMapping.id]),
      employeeName: String(row[rosterMapping.name] || 'Unknown').toUpperCase(),
      client: selectedEmployer,
      month: viewMonth,
      year: viewYear,
      totalDays: daysInMonth,
      workedDays: 0,
      leaveDays: 0,
      grade: row[rosterMapping.grade] || 'Grade 1',
      otHours: 0,
      ctc: 0,
      basicDA: 0,
      bonus: 0,
      pfPercent: 0,
      esiPercent: 0,
      canteenDeduction: 0,
      ptDeduction: 0
    }));

    setAttendanceRecords(prev => {
      let next = [...prev];

      // If Re-upload, wipe data for the current period first
      if (reuploadPendingRef.current) {
        next = next.filter(r => 
          !(r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear)
        );
      }

      newEntries.forEach(entry => {
        const idx = next.findIndex(r => r.employeeId === entry.employeeId && r.client === selectedEmployer && r.month === viewMonth && r.year === viewYear);
        if (idx >= 0) next[idx] = { ...next[idx], grade: entry.grade, employeeName: entry.employeeName };
        else next.push(entry);
      });

      return next;
    });

    setShowRosterMapping(false);
    reuploadPendingRef.current = false; // Reset the ref after processing
  };

  const saveGradeConfigs = async () => {
    await cloudApi.saveGradeConfigs(gradeConfigs);
    setShowGradeMaster(false);
  };

  const saveToCloud = async () => {
    setIsSaving(true);
    try {
      await cloudApi.saveAttendance(attendanceRecords);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Financial Roster Planner</h2>
          <p className="text-sm text-gray-500 mt-1 font-medium italic">Internal component management with automated payroll proration</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-gray-100 shadow-sm">
             <Calendar size={18} className="text-indigo-500 mr-2" />
             <select value={viewMonth} onChange={e => setViewMonth(e.target.value)} className="bg-transparent font-bold text-xs outline-none">
                {monthNames.map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <select value={viewYear} onChange={e => setViewYear(parseInt(e.target.value))} className="bg-transparent font-bold text-xs outline-none ml-2">
                {dynamicYears.map(y => <option key={y} value={y}>{y}</option>)}
             </select>
          </div>

          <button onClick={() => setShowGradeMaster(true)} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
            <Settings2 size={16} /><span className="text-[10px] uppercase tracking-widest">Grade Master</span>
          </button>

          <div className="flex gap-2">
            <button onClick={() => { reuploadPendingRef.current = false; rosterFileInputRef.current?.click(); }} className="flex items-center gap-3 px-5 py-3 bg-white border border-gray-200 text-gray-600 font-bold rounded-2xl hover:bg-gray-50 transition-all shadow-sm">
              <Database size={16} /><span className="text-[10px] uppercase tracking-widest">Upload Staff</span>
            </button>
            <button onClick={handleTriggerReupload} className="flex items-center gap-3 px-5 py-3 bg-white border border-orange-200 text-orange-600 font-bold rounded-2xl hover:bg-orange-50 transition-all shadow-sm">
              <RotateCcw size={16} /><span className="text-[10px] uppercase tracking-widest">Re-upload</span>
            </button>
          </div>

          <input ref={rosterFileInputRef} type="file" accept=".csv" onChange={handleRosterUpload} className="hidden" />

          <button onClick={saveToCloud} disabled={isSaving} className="flex items-center gap-3 px-6 py-3 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all active:scale-[0.98]">
            {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
            <span className="text-xs uppercase tracking-widest">Sync Planner</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><Calculator size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Planned Gross</p>
            <p className="text-xl font-black text-gray-900">₹{filteredRecords.reduce((acc, r) => acc + (r.computedGross || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-emerald-50 text-emerald-600 rounded-xl"><TrendingUp size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Payable</p>
            <p className="text-xl font-black text-emerald-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedNet || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[28px] border border-gray-100 shadow-sm flex items-center gap-4">
          <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><Shield size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Liability</p>
            <p className="text-xl font-black text-rose-600">₹{filteredRecords.reduce((acc, r) => acc + (r.computedDeductions || 0), 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
          </div>
        </div>
        <div className="bg-indigo-600 p-6 rounded-[28px] text-white shadow-xl shadow-indigo-100 flex items-center gap-4">
          <div className="p-3 bg-white/10 rounded-xl"><CheckCircle size={20} /></div>
          <div>
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Staff Status</p>
            <p className="text-xl font-black">{filteredRecords.length} Active</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[32px] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
        <div className="p-6 border-b border-gray-50 flex items-center justify-between gap-4 bg-white sticky top-0 z-10">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search by name or code..." className="w-full bg-gray-50 border-none rounded-xl pl-12 pr-4 py-2.5 text-xs font-bold outline-none" />
          </div>
          <div className="hidden md:flex items-center gap-3">
             <div className="flex items-center gap-2 px-3 py-1.5 bg-amber-50 text-amber-600 border border-amber-100 rounded-lg text-[9px] font-black uppercase tracking-widest animate-pulse">
                <AlertTriangle size={12} /> Limit: {daysInMonth} Days
             </div>
             <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100 uppercase tracking-widest">Dynamic Payroll Simulation</span>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/30 border-b border-gray-100">
                <th className="px-6 py-4 text-left min-w-[180px]"><span className="text-[10px] font-black text-gray-400 uppercase">Employee / Grade</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-emerald-600 uppercase">Worked</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-500 uppercase">OT Hrs</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">Basic</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                <th className="px-3 py-4 text-center"><span className="text-[10px] font-black text-rose-500 uppercase">Canteen</span></th>
                <th className="px-6 py-4 text-right bg-indigo-50/50"><span className="text-[10px] font-black text-indigo-700 uppercase">Computed Net</span></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredRecords.map((record) => (
                <tr key={record.employeeId} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="text-xs font-black text-gray-900">{record.employeeName}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{record.employeeId}</span>
                      <select 
                        value={record.grade}
                        onChange={e => updateRecord(record.employeeId, { grade: e.target.value })}
                        className="text-[8px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full border-none outline-none appearance-none cursor-pointer"
                      >
                        <option value="Grade 1">Grade 1</option>
                        <option value="Grade 2">Grade 2</option>
                        <option value="Grade 3">Grade 3</option>
                        <option value="Grade 4">Grade 4</option>
                      </select>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input 
                      type="number" 
                      step="0.5" 
                      min="0" 
                      max={daysInMonth} 
                      value={record.workedDays || ''} 
                      onChange={(e) => updateRecord(record.employeeId, { workedDays: parseFloat(e.target.value) || 0 })} 
                      className="w-16 bg-emerald-50/50 border border-emerald-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-emerald-700 outline-none focus:ring-2 focus:ring-emerald-500 transition-all" 
                    />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="1" min="0" value={record.otHours || ''} onChange={(e) => updateRecord(record.employeeId, { otHours: parseFloat(e.target.value) || 0 })} className="w-16 bg-orange-50/50 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4 text-center">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-gray-900">₹{record.basicDA?.toLocaleString()}</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Fixed</span>
                    </div>
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.1" value={record.pfPercent || ''} onChange={(e) => updateRecord(record.employeeId, { pfPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" step="0.01" value={record.esiPercent || ''} onChange={(e) => updateRecord(record.employeeId, { esiPercent: parseFloat(e.target.value) || 0 })} className="w-14 bg-orange-50/30 border border-orange-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-orange-700 outline-none" />
                  </td>
                  <td className="px-2 py-4">
                    <input type="number" value={record.canteenDeduction || ''} onChange={(e) => updateRecord(record.employeeId, { canteenDeduction: parseFloat(e.target.value) || 0 })} className="w-20 bg-rose-50/30 border border-rose-100 rounded-lg px-2 py-1.5 text-center text-xs font-black text-rose-700 outline-none" />
                  </td>
                  <td className="px-6 py-4 text-right bg-indigo-50/20">
                    <p className="text-xs font-black text-indigo-700">₹{record.computedNet?.toLocaleString(undefined, { minimumFractionDigits: 1 })}</p>
                    <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Gross: ₹{record.computedGross?.toFixed(1)}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showGradeMaster && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-4xl rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black">Grade Master Configuration</h3>
                <p className="text-[10px] font-bold text-indigo-200 uppercase tracking-widest mt-1">Set fixed components for all employees in a grade</p>
              </div>
              <button onClick={() => setShowGradeMaster(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24}/></button>
            </div>

            <div className="p-8 overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-gray-400 uppercase">Grade</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Basic + DA</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-indigo-600 uppercase">Bonus</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">PF %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-orange-600 uppercase">ESI %</span></th>
                    <th className="pb-4 px-2"><span className="text-[10px] font-black text-rose-600 uppercase">PT Amt</span></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {gradeConfigs.map((config, idx) => (
                    <tr key={config.grade} className="hover:bg-gray-50/50">
                      <td className="py-4 px-2 text-sm font-black text-gray-900">{config.grade}</td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.basicDA} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].basicDA = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.bonus} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].bonus = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-24 bg-indigo-50/50 border border-indigo-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.1" value={config.pfPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].pfPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" step="0.01" value={config.esiPercent} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].esiPercent = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-orange-50/50 border border-orange-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                      <td className="py-4 px-2">
                        <input type="number" value={config.ptAmount} onChange={e => {
                          const updated = [...gradeConfigs];
                          updated[idx].ptAmount = parseFloat(e.target.value) || 0;
                          setGradeConfigs(updated);
                        }} className="w-20 bg-rose-50/50 border border-rose-100 rounded-xl px-3 py-2 text-xs font-bold outline-none" />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div className="mt-8 flex gap-4">
                <button onClick={saveGradeConfigs} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Save Master Config</button>
                <button onClick={() => setShowGradeMaster(false)} className="px-8 py-4 bg-gray-100 text-gray-500 font-black rounded-2xl hover:bg-gray-200 uppercase tracking-widest text-xs">Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showRosterMapping && (
        <div className="fixed inset-0 z-[500] bg-gray-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-3xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="text-xl font-black">Map Staff Roster</h3>
              <button onClick={() => { setShowRosterMapping(false); reuploadPendingRef.current = false; }} className="p-2 hover:bg-white/10 rounded-full"><X size={24} /></button>
            </div>
            <div className="p-8 space-y-6">
              {['id', 'name', 'grade'].map((field) => (
                <div key={field} className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{field} Column</label>
                  <select value={rosterMapping[field]} onChange={e => setRosterMapping({...rosterMapping, [field]: e.target.value})} className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none">
                    <option value="">Select Column...</option>
                    {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              ))}
              <button onClick={processRosterMapping} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Import Staff Details</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendanceTab;
